/* Adding new filed to UsrLogin table */
IF NOT EXISTS(SELECT * FROM   INFORMATION_SCHEMA.COLUMNS
    WHERE  upper(TABLE_NAME) = upper('UsrLogin') AND upper(COLUMN_NAME) = upper('UlSysCd'))
BEGIN    
	Alter table UsrLogin Add UlSysCd varchar(5) NOT NULL CONSTRAINT DF_UlSysCd DEFAULT ''
END
