	join Param on PTyp ='GSTFLDS' and PMCd =InGstCd and PSCd =1 		
Update InvHd set InGstOn2 =PValue, InAmt2Per =PNum  from InvHd  
	join Param on PTyp ='GSTFLDS' and PMCd =InGstCd and PSCd =2 
		where InTc ='IN' 

Update InvHd set InGstOn3 =PValue, InAmt3Per =PNum  from InvHd  
	join Param on PTyp ='GSTFLDS' and PMCd =InGstCd and PSCd =3 
		where InTc ='IN' 
		
Update InvHd set InGstOn4 =PValue, InAmt4Per =PNum  from InvHd  
	join Param on PTyp ='GSTFLDS' and PMCd =InGstCd and PSCd =4 
		where InTc ='IN' 

Update InvHd set InGstOn5 =PValue, InAmt5Per =PNum  from InvHd  
	join Param on PTyp ='GSTFLDS' and PMCd =InGstCd and PSCd =5 
		where InTc ='IN' 

Update InvHd set InGstOn6 =PValue, InAmt6Per =PNum  from InvHd  
	join Param on PTyp ='GSTFLDS' and PMCd =InGstCd and PSCd =6 
		where InTc ='IN' 

