	Drop table TmpHead

Create Table TmpHead(hRow int,hComCd varchar(3))
insert into TmpHead select ROW_NUMBER() OVER ( ORDER BY hcocd ),hcocd from Head  
	
declare @i int
declare @hcocd varchar(3)
set @i=1
while @i <= (select COUNT(*) from TmpHead )
begin	
 select @hcocd=	hComCd from TmpHead where hRow =@i 
insert into vParam 
	(vPCoCd,
	vPTyp   ,  
	vPMCd    , 
	vPSCd     ,
	vPDesc    ,                     
	vPDesc225 ,                
    vPValue   ,                     
	vPNum     ,             
	vPValue1  ,                                                                                         
	vPNum1    ,             
	vPValue2   ,                                                                                 
	vPValue3  ,                      
	ModUsr,
	ModDt  ,                 
	ModTime ,                                
	vPValidYn ,
	vPValue4  ,                      
	vPPrtKey	)        
select top 1 
	@hcocd ,  
	'UNLOCK', 
	'UNLOCK' ,
	'',
	'UnLock Voucher', 
	'' ,  
  	'' , 
	0  ,   
	'' ,                   
	0  ,   
	'' , 
	'' ,
	'MIC',
	'1980-01-01 00:00:00'  ,  
	0.00 ,                                
	''  ,                      
	'' ,
	'C'	
 from vParam  
 where not exists (Select 'a' from vParam where vPCoCd =@hcocd and vPTyp='UNLOCK' and vPMCd ='UNLOCK' and vPSCd='')

 set @i= @i+1
end
GOGO







/* create a new table ShpNote */
