create table ShpNote 
(
	SnCoCd varchar(3) not null,
	SnTc varchar(3) not null,
	SnYy  varchar(2) not null,
	SnChr  varchar(3) not null,
	SnNo int not null,
	SnDt smalldatetime not null,
	SnCmCd  varchar(8) not null,
	SnCurCd  varchar(5) not null,
	SnInTc  varchar(3) not null,
	SnInYy varchar(2) not null,
	SnInChr varchar(3) not null,
	SnInNo int not null,
	SnInDt smalldatetime not null,
	SnIdNo int IDENTITY(1,1) NOT FOR REPLICATION not null,
	ModUsr varchar(5) not null,
	ModDt smalldatetime not null,
	ModTime numeric(5,2) not null
)

IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID('PK_ShpNote')) 
ALTER TABLE ShpNote ADD CONSTRAINT PK_ShpNote PRIMARY KEY CLUSTERED 
(
	SnCoCd ASC ,
	SnTc ASC,
	SnYy ASC ,
	SnChr ASC ,
