ALTER Procedure [dbo].[InsOrderCpy]
(
	@wTargetOdCoCd varchar(3),
	@wTargetOdTc varchar(3),
	@wTargetOdYy varchar(2),
	@wTargetOdChr varchar(3),
	@wTargetOdNo int,
	@wOdSr int,
	@wOdDmCd varchar(15),
	@wOdSfx varchar(15),
	@wOdDmSz varchar(5),
	@wOdPrdSeq varchar(80),
	@wOdDelDt date,
	@wOdOrdEnt float,
	@wOdOrdQty float,
	@wOdPrdEnt float,
	@wOdPrdQty float,
	@wOdCalcPrc float,
	@wOdSalPrc float,
	@wOdCstPrc float,
	@wOdDmPrdInst varchar(250),
	@wOdCmPrdInst varchar(250),
	@wOdCmStmpInst varchar (90),
	@wOdSzInst varchar(90),
	@wOdPrtCd varchar(2),
	@wOdVaCtg varchar(5),
	@wOdKt varchar(5),
	@wOdMulBy float,
	@wOdFixPrc varchar(1),
	@wOdGldAs varchar(5),
	@wOdIWtEqOrd varchar(1),
	@wOdIWtFrOrd varchar(5),
	@wOdIGldRtEqOrd varchar(1),
	@wOdBagPcs float,
	@wOdDmCol varchar(5),
	@wOdGldAsWt float,
	@wOdExpDelDt date,
	@wOdSfxDesc varchar(255),
	@wOdWh varchar(2),
	@wOdByy varchar(2),
	@wOdBChr varchar(3),
	@wOdBNo int,
	@wOdMrp float,
	@wOdMrpDisc float,
	@wOdLine varchar(5),
	@wOdPoNo varchar(20),
	@wOdSubCust varchar(8),
	@ws_baseVch varchar(50),
	@wOdCell  varchar(8),
	@wOdDmStkCoCd varchar(3),
	@wOdDmStkYy varchar(2),
	@wOdDmStkChr varchar(3),
	@wOdDmStkNo int,
	@wOdChgPtrOnStwYN varchar(1),
	@wOdMrpMulBy float,
	@wOdILabWtFrOrd varchar(1),
	@wOdInvAllBags varchar(1),
	@wOdLabAs varchar(5),
	@wOdLabAsWt float,
	@wOdSalRem varchar(100),
	@wOdOmCtCd varchar(8),
	@wOdCrmFixPrcYN varchar(1),
	@wOdPicNm varchar(45),
	@wOdGmChk varchar(8),
	@wOdModUsr varchar(5),
	@wOdGrMet varchar(8),
	@wOdGrDia varchar(8),
    @wOdGrCS varchar(8),
    @wOdGrFin varchar(8),
	@wOdMinWt float,
	@wOdMaxWt float,
	@wOdChkTol varchar(1),
	@wOdSubRem varchar(120),
	@wOdDmIdNo int
    ,@wOdMinDiaTolWt float 
    ,@wOdMaxDiaTolWt float
	,@wOdBaseIdKey int
	,@wOdRefIdKey int
	,@wOdCls char(1)
	,@wOdHld char(1)
	,@wOdWDiaAvlblDt date
	,@wOdHDiaAvlblDt date
	,@wOdFndAvlblDt date
	,@wOdInsDt date
	,@wOdOmDt date 
	,@wOdDmTcTyp varchar(2)
	,@wOdOmIdNo int
	,@wOdOmCmCd varchar(8)
	,@qOdPerPcDiaWt float
	,@qOdPerPcCsWt float
	,@qOdPerPcDiaQty int
	,@qOdPerPcCsQty int
	,@qOdMainMetRmCtg varchar(1)
	,@qOdCstLabAsWt float
	,@qOdPerPcDiaPrdWt float
	,@qOdPerPcCsPrdWt float
	,@qMode int
	,@wOdRepGrWt float
	,@wOdMasterPrc float
	,@wOdTag float
	,@wOdProfit float
	,@wOdProfitPer float
	,@wOdOmTag float
)
--OdSr - RedSr
as
Begin

	if @qMode=1 
	begin

		INSERT INTO  dbo . OrdDsg 
           ( OdTc 
           , OdYy 
           , OdChr 
           , OdNo 
           , OdSr 
           , OdDmCd 
           , OdSfx 
           , OdDmSz 
           , OdPrdSeq 
           , OdDelDt 
           , OdOrdEnt 
           , OdOrdQty 
           , OdExpQty 
           , OdPrdEnt 
           , OdPrdQty 
           , OdFgQty 
           , OdCalcPrc 
           , OdSalPrc 
           , OdCstPrc 
           , OdDmPrdInst 
           , OdCmPrdInst 
           , OdCmStmpInst 
           , OdSzInst 
           , OdPrtCd 
           , OdHld 
           , OdHldDesc 
           , OdVaCtg 
           , OdKt 
           , OdMulby 
           , OdFixPrc 
           , OdGldAs 
           , OdIWtEqOrd 
           , OdIWtFrOrd 
           , OdIGldRtEqOrd 
           , OdCls 
           , OdBagPcs 
           , OdDmCol 
           , OdGldAsWt 
           , ModUsr 
           , ModDt 
           , ModTime 
           , OdExpDelDt 
           , OdSfxDesc 
           , OdCoCd 
           , OdWh 
           , OdWDiaAvlblDt 
           , OdHDiaAvlblDt 

           , OdLine 
           , OdSalRem 
           , OdOmCtCd 
           , OdMinWt 
           , OdMaxWt 
           , OdBYy 
           , OdBChr 
           , OdBNo 
           , OdGmChk 
           , OdChkTol 
           , OdGrMet 
           , OdGrDia 
           , OdGrCS 
           , OdGrFin 
           , OdCrmFixPrcYN 
           , OdSubRem 
           , OdLabAs 
           , OdLabAsWt 
           , OdOmCmCd 
           , OdOmDt 
           , OdOmIdNo 
		   ,OdDmIdNo
           , OdPrtKey 
           , OdPrtFgQty 
           , OdPrtExpQty 
           , OdPicNm 
           , OdPoNo 
           , OdILabWtFrOrd 
           , OdChgPtrOnStwYN 
           , InsDt 
           , OdMinDiaTolWt 
           , OdMaxDiaTolWt 
           , OdBaseIdKey 
           , OdRefIdKey 
           , OdMrpMulby 
           , OdMrp 
           , OdDmStkYy 
           , OdDmStkChr 
           , OdDmStkNo 
			, OdJLRmCd 
			, OdJLLn1 
			, OdJLLn2 
			, OdJLLn3 
			, OdJLLotNo 
			, OdJLQty 
			, OdJLWt 
			, OdJLExpWt 
			, OdJLVchRt 
			, OdJLRateByQW 
			, OdJLVchVal 
			, OdInvAllBags 
			,OdCell
			,OdRepGrWt
			,OdDmStkCoCd
			,OdMrpDisc
			,OdFndAvlblDt 
			,OdDmTcTyp
			,OdSubCust 
			,OdMasterPrc
			,OdTag
			,OdProfit
			,OdProfitPer
			,OdOmTag
           )
		SELECT     
		   @wTargetOdTc,
           @wTargetOdYy,
           @wTargetOdChr,
           @wTargetOdNo,
		   @wOdSr,
           @wOdDmCd,
           @wOdSfx, 
           @wOdDmSz, 
		   @wOdPrdSeq,
           @wOdDeldt, 
           @wOdOrdEnt, 
           @wOdOrdQty, 
		   0 as OdExpQty,		   
		   @wOdPrdEnt,
		   @wOdPrdQty, 
		   0 as OdFgQty,
           @wOdCalcPrc,
           @wOdSalPrc,
			@wOdCstPrc,
           @wOdDmPrdInst,
           @wOdCmPrdInst,
           @wOdCmStmpInst,
		   @wOdSzInst,
           @wOdPrtCd,
           @wOdHld,
           '' as OdHldDesc,
           @wOdVaCtg
           ,@wOdKt
           ,@wOdMulBy 
           ,@wOdFixPrc
		   ,@wOdGldAs
           ,@wOdIWtEqOrd
           ,@wOdIWtFrOrd
           ,@wOdIGldRtEqOrd
		   ,@wOdCls
           ,@wOdBagPcs
           ,@wOdDmCol
           ,@wOdGldAsWt
          ,@wOdModUsr
			,getdate()
			,datepart(hh,getdate())+(convert(float,datepart(mi,getdate()))/100)
           ,@wOdExpDelDt
		   ,@wOdSfxDesc
		   ,@wTargetOdCoCd
           ,@wOdWh
           ,@wOdWDiaAvlblDt 
           ,@wOdHDiaAvlblDt 
           ,@wOdLine
           ,@wOdSalRem
           ,@wOdOmCtCd
           ,@wOdMinWt
           ,@wOdMaxWt
           ,@wOdBYy
           ,@wOdBChr
           ,@wOdBNo
           ,@wOdGmChk
           ,@wOdChkTol
           ,@wOdGrMet
           ,@wOdGrDia
           ,@wOdGrCS
           ,@wOdGrFin
           ,@wOdCrmFixPrcYN
           ,@wOdSubRem
           ,@wOdLabAs
           ,@wOdLabAsWt
           ,@wOdOmCmCd
           ,@wOdOmDt
           ,@wOdOmIdNo
           ,@wOdDmIdNo
           ,'C'
           ,0 as OdPrtFgQty
           ,0 as OdPrtExpQty
           ,@wOdPicNm
           ,@wOdPoNo
           ,@wOdILabWtFrOrd
		   ,@wOdChgPtrOnStwYN
           ,@wOdInsDt/*convert(varchar(8),getdate(),3) as InsDt*/
           ,@wOdMinDiaTolWt
           ,@wOdMaxDiaTolWt
		   ,@wOdBaseIdKey
		   ,@wOdRefIdKey 
           ,@wOdMrpMulby
           ,@wOdMrp
           ,@wOdDmStkYy 
           ,@wOdDmStkChr
           ,@wOdDmStkNo
		    ,'' as OdJLRmCd
      ,0 as OdJLLn1
      ,0 as OdJLLn2
      ,0 as OdJLLn3
      ,'' as OdJLLotNo
      ,0 as OdJLQty
      ,0.0 as OdJLWt
      ,0.0 as OdJLExpWt
      ,0.0 as OdJLVchRt
      ,'' OdJLRateByQW
      ,0.0 as OdJLVchVal
      ,@wOdInvAllBags
	  ,@wOdCell	  
	  ,@wOdRepGrWt
	  ,@wOdDmStkCoCd 
	  ,@wOdMrpDisc
      ,@wOdFndAvlblDt 
	  ,@wOdDmTcTyp 
	  ,@wOdSubCust 
	  ,@WOdMasterPrc 
	  ,@wOdTag
	  ,@wOdProfit
	  ,@wOdProfitPer 
	  ,@wOdOmTag
	  end
	  else
	  begin
		UPDATE OrdDsg set 
           OdDmcd=@wOdDmCd,
           OdSfx=@wOdSfx, 
           OdDmSz=@wOdDmSz, 
		   OdPrdSeq=@wOdPrdSeq,
           OdDeldt=@wOdDelDt, 
           OdOrdEnt=@wOdOrdEnt,
           OdOrdQty=@wodordqty,
		   OdExpQty=0,		   
		   OdPrdEnt=@wOdPrdEnt,
		   OdPrdQty=@wOdPrdEnt, 
		   OdFgQty=0,
           OdCalcPrc=@wOdCalcPrc,
           OdSalPrc=@wOdSalPrc,
			OdCstPrc=@wOdCstPrc,
           OdDmPrdInst=@wOdDmPrdInst,
           OdCmPrdInst=@wOdCmPrdInst,
           OdCmStmpInst=@wOdCmStmpInst,
		   OdSzInst=@wOdSzInst,
           OdPrtCd=@wOdPrtCd,
           OdHld=@wOdHld,
           OdHldDesc='',
           OdVaCtg=@wOdVaCtg,
           OdKt=@wOdKt,
           OdMulBy=@wOdMulBy ,
           OdFixPrc=@wOdFixPrc,
		   OdGldAs=@wOdGldAs,
           OdIWtEqOrd=@wOdIWtEqOrd,
           OdIWtFrOrd=@wOdIWtFrOrd,
           OdIGldRtEqOrd=@wOdIGldRtEqOrd,
		   OdCls=@wOdCls,
           OdBagPcs=@wOdBagPcs,
           OdDmCol=@wOdDmCol,
           OdGldAsWt=@wOdGldAsWt,
          ModUsr=@wOdModUsr,
           OdExpDelDt=@wOdExpDelDt ,
		   OdSfxDesc=@wOdSfxDesc,
		
           OdWh=@wOdWh,
           OdWDiaAvlblDt =@wOdWDiaAvlblDt ,
           OdHDiaAvlblDt =@wOdHDiaAvlblDt ,
           OdLine=@wOdLine,
           OdSalRem=@wOdSalRem,
           OdOmCtCd=@wOdOmCtCd,
           OdMinWt=@wOdMinWt,
           OdMaxWt=@wOdMaxWt,
           OdBYy=@wOdBYy,
           OdBChr=@wOdBChr,
           OdBNo=@wOdBNo,
           odGmChk=@wOdGmChk,
           OdChkTol=@wOdChkTol,
           OdGrMet=@wOdGrMet,
           OdGrDia=@wOdGrDia,
           OdGrCS=@wOdGrCS,
           OdGrFin=@wOdGrFin,
           OdCrmFixPrcYN=@wOdCrmFixPrcYN,
          OdSubRem=@wOdSubRem,
           OdLabAs=@wOdLabAs,
           OdLabAsWt=@wOdLabAsWt,
           OdOmCmCd=@wOdOmCmCd,
           OdOmDt=@wOdOmDt,
           OdPicNm=@wOdPicNm,
           OdPoNo=@wOdPoNo,
           OdILabWtFrOrd=@wOdILabWtFrOrd,
		   OdChgPtrOnStwYN=@wOdChgPtrOnStwYN,
      
           OdMinDiaTolWt=@wOdMinDiaTolWt,
           OdMaxDiaTolWt=@wOdMaxDiaTolWt,
		   OdBaseIdKey=@wOdBaseIdKey,
		   OdRefIdKey =@wOdRefIdKey ,
           OdMrpMulby=@wOdMrpMulby,
          OdMrp=@wOdMrp,
           OdDmStkYy=@wOdDmStkYy ,
           OdDmStkChr=@wOdDmStkChr,
           OdDmStkNo=@wOdDmStkNo,
      OdInvAllBags=@wOdInvAllBags,
	  OdCell=@wOdCell,
	  OdRepGrWt = @wOdRepGrWt,
	  OdDmStkCoCd =@wOdDmStkCoCd ,
	  OdMrpDisc=@wOdMrpDisc,
      OdFndAvlblDt=@wOdFndAvlblDt ,
	  OdDmTcTyp =@wOdDmTcTyp ,
