GOGO
create TRIGGER [dbo].[ShpNote_INUPDL] ON [dbo].[ShpNote] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	/****** Trigger Version - 3.8.0 ******/
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
		
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'ShpNote' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with CdBCoCd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ SnCoCd  +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ SnCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	if @mode in ('A','C')
	Begin
		/****** Checking valid company code   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Head where HCoCd= SnCoCd and HCd= @wHCd)
		if @row>0
		begin
			select @errMsg= 'Invalid Company Code '
			goto ErrHndlr
		end
		/****** Checking valid TC    *******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp= 'TC' and PMCd =SnTc and PValue= 'SN' )
		if @row>0
		begin
			select @errMsg= 'Invalid Shipment Note TC '
			goto ErrHndlr
		end		
		/****** Checking valid Year   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp= 'YY' and PMCd =SnYy)
		if @row>0
		begin
			select @errMsg= 'Invalid Shipment Note Year '
			goto ErrHndlr
		end
		/****** Checking valid Character   *******/
		select @row=count('x') from inserted where not exists (select 'x' from vParam where vPCoCd =SnCoCd and vPTyp= 'CHR' 
																	and vPMCd =SnTc and vPSCd =SnChr )
		if @row>0
		begin
			select @errMsg= 'Invalid Shipment Note Character '
			goto ErrHndlr
		end		
		/****** Checking valid shipment note no.   *******/
		select @row= count('x') from inserted where SnNo<= 0  
		if @row> 0   
		begin  
			select @errmsg= 'Shipment Note Number Cannot Be <= Zero'  
			goto ErrHndlr  
		end  
		/****** Checking customer code   *******/
		select @row=count('x') from inserted where not exists (select 'x' from CustMst where CmCtg ='C' and SnCmCd =CmCd )
		if @row>0
		begin
			select @errMsg= 'Invalid Customer Code '
			goto ErrHndlr
		end 
		/****** Checking currency code   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp= 'CURNCY' and PMCd=SnCurCd and PSCd= '')
		if @row>0
		begin
			select @errMsg= 'Invalid Currency Code '
			goto ErrHndlr
		end
		/****** Checking customer &currency match   *******/
		select @row= count('x') from inserted where SnCurCd <>(select CmCurCd from CustMst where CmCtg= 'C' and CmCd= SnCmCd ) 
		if @row> 0 
		begin
			select @errmsg= 'Customer And Currency Not Matching'
			goto ErrHndlr
		end		
		/****** Checking valid Invoice TC    *******/
		select @row=count('x') from inserted where SnInTc<>'' and not exists (select 'x' from Param where PTyp= 'TC' and PMCd =SnInTc and PValue= 'IN' )
		if @row>0
		begin
			select @errMsg= 'Invalid Invoice TC '
			goto ErrHndlr
		end		
		/****** Checking valid Invoice Year   *******/
		select @row=count('x') from inserted where SnInYy<>'' and not exists (select 'x' from Param where PTyp= 'YY' and PMCd =SnInYy )
		if @row>0
		begin
			select @errMsg= 'Invalid Invoice Year '
			goto ErrHndlr
		end
		/****** Checking valid Invoice Character   *******/
		select @row=count('x') from inserted where SnInChr<>'' and not exists (select 'x' from vParam where vPCoCd =SnCoCd and vPTyp= 'CHR' 
																	and vPMCd =SnInTc and vPSCd =SnInChr )
		if @row>0
		begin
			select @errMsg= 'Invalid Invoice Character '
			goto ErrHndlr
		end		
		/****** Checking valid invoice no.   *******/
		select @row= count('x') from inserted where SnInNo <>0 and not exists (select 'x' from InvHd where InCoCd =SnCoCd 
							and InTc =SnInTc and InYy =SnInYy and InChr =SnInChr and InNo =SnInNo )
		if @row> 0   
		begin  
			select @errmsg= 'Invalid Invoice Number '  
			goto ErrHndlr  
		end  	
										
	End
	
	/***** cannot delete if records exists in child tables ******/
	if @mode = 'D' 
	Begin
		select @row= count('x') from deleted where exists (select 'x' from ShpNoteOrdMst where SomCoCd =SnCoCd and SomTc =SnTc 
			and SomYy =SnYy and SomChr =SnChr and SomNo =SnNo )
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Child Records Exists'
			goto ErrHndlr
		end
		select @row= count('x') from deleted where exists (select 'x' from ShpNoteOrdDsg where SnCoCd =SodCoCd and SnTc =SodTc 
			and SnYy =SodYy and SnChr =SodChr and SnNo =SodNo )
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design Records Exists'
			goto ErrHndlr
		end		
	end
	
RETURN
ErrHndlr:
	Begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	End
END

GOGO


