create TRIGGER [dbo].[ShpNoteOrdMst_INUPDL] ON [dbo].[ShpNoteOrdMst] 
       FOR INSERT,UPDATE,DELETE  
	   NOT FOR REPLICATION
AS  
BEGIN  
	/****** Trigger Version - 3.8.0 ******/
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
		
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'ShpNoteOrdMst' )  
	RETURN  
	
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
	else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
	end   

	Select @wHCd= 'ZSELF'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with CdBCoCd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ SomCoCd  +',%') 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ SomCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	if @mode in ('A','C')
	Begin
		/****** Checking valid company code   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Head where HCoCd= SomOmCoCd and HCd= @wHCd)
		if @row>0
		begin
			select @errMsg= 'Invalid Company Code '
			goto ErrHndlr
		end
		/****** Checking order TC    *******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp= 'TC' and PMCd =SomOmTc and PValue= 'SO' )
		if @row>0
		begin
			select @errMsg= 'Invalid Order TC '
			goto ErrHndlr
		end		
		/****** Checking order Year   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp= 'YY' and PMCd =SomOmYy)
		if @row>0
		begin
			select @errMsg= 'Invalid Order Year '
			goto ErrHndlr
		end
		/****** Checking order Character   *******/
		select @row=count('x') from inserted where not exists (select 'x' from vParam where vPCoCd =SomOmCoCd and vPTyp= 'CHR' 
																	and vPMCd =SomOmTc and vPSCd =SomOmChr )
		if @row>0
		begin
			select @errMsg= 'Invalid Order Character '
			goto ErrHndlr
		end						
		/****** Checking order no.   *******/
		select @row= count('x') from inserted where not exists (select 'x' from OrdMst where OmCoCd =SomOmCoCd 
							and OmTc =SomOmTc and OmYy =SomOmYy and OmChr =SomOmChr and OmNo =SomOmNo )
		if @row> 0   
		begin  
			select @errmsg= 'Invalid Order Number '  
			goto ErrHndlr  
		end  	
										
	End
	/***** cannot delete if records exists in ShpNoteOrdDsg table ******/
	if @mode = 'D' 
	Begin
		select @row= count('x') from deleted where exists (select 'x' from ShpNoteOrdDsg where SomCoCd =SodCoCd and SomTc =SodTc 
			and SomYy =SodYy and SomChr =SodChr and SomNo =SodNo and SomSr =SodSr )
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Design Records Exists'
			goto ErrHndlr
		end
				
	end
RETURN
ErrHndlr:
	Begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	End
END



GOGO



