		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ SodCoCd +',%')
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	if @mode in ('A','C')
	Begin
		/****** Checking valid company code   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Head where HCoCd= SodOdCoCd and HCd= @wHCd)
		if @row>0
		begin
			select @errMsg= 'Invalid Company Code '
			goto ErrHndlr
		end
		/****** Checking order TC    *******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp= 'TC' and PMCd =SodOdTc and PValue= 'SO' )
		if @row>0
		begin
			select @errMsg= 'Invalid Order TC '
			goto ErrHndlr
		end		
		/****** Checking order Year   *******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where PTyp= 'YY' and PMCd =SodOdYy)
		if @row>0
		begin
			select @errMsg= 'Invalid Order Year '
			goto ErrHndlr
		end
		/****** Checking order Character   *******/
		select @row=count('x') from inserted where not exists (select 'x' from vParam where vPCoCd =SodOdCoCd and vPTyp= 'CHR' 
																	and vPMCd =SodOdTc and vPSCd =SodOdChr )
		if @row>0
		begin
			select @errMsg= 'Invalid Order Character '
			goto ErrHndlr
		end						
		/****** Checking order no.   *******/
		select @row= count('x') from inserted where not exists (select 'x' from OrdDsg where OdCoCd =SodOdCoCd 
							and OdTc =SodOdTc and OdYy =SodOdYy and OdChr =SodOdChr and OdNo =SodOdNo )
		if @row> 0   
		begin  
			select @errmsg= 'Invalid Order Number '  
			goto ErrHndlr  
		end  	
		/****** Checking order serial   *******/
		select @row= count('x') from inserted where not exists (select 'x' from OrdDsg where OdCoCd =SodOdCoCd 
							and OdTc =SodOdTc and OdYy =SodOdYy and OdChr =SodOdChr and OdNo =SodOdNo and OdSr =SodOdSr )
		if @row> 0   
		begin  
			select @errmsg= 'Invalid Order Serial '  
			goto ErrHndlr  
		end  	
										
	End
	
RETURN
ErrHndlr:
	Begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	End
END




GOGO





ALTER TRIGGER [dbo].[CustMst_INUPDL] ON [dbo].[CustMst] 
       FOR INSERT,UPDATE,DELETE
		NOT FOR REPLICATION
AS
BEGIN
	/* Trigger Version 2.14.0 Next */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @SYS VARCHAR(5)	
	DECLARE @ReplAgt BIT

	IF @@ROWCOUNT=0		RETURN

	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'CustMst' )
		RETURN

	select @mode=case (Select count('x') from inserted) when 0 then 'D'
		     Else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
		     End	

	set @wSelfCd = 'ZSELF'	
	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		 /****** Cannot Insert/Update/Delete if SysDb <>'WEB'*****  
		Insert/Update/Delete Allowed if SysDb='WEB' /Throu Replication****/
		
		 if @mode in ('A','C','D')
		 Begin  
			If   Exists( select 'x' From SysDb where SysId='EMR' and SdMst='N' )  Or  
				Exists (Select 'x' From SysDb where SysId='CRM' and SysDb ='WEB') 
			  Begin  
			   select @errmsg= 'Cannot Insert /Update /Delete '  
			   goto ErrHndlr  
			  end  
		  End  
	End

	/* *** Jay 2.14 *** */
	/* *** Can Not Add/ Delete/ Update If User Level >5 *** */
	If @mode in ('A','C') and 
		((Select count('x') from Param join inserted ins on PTyp= 'USR' and PMCd= ins.ModUsr and PSCd= '' and PNum> 5)> 0)
 	Begin  
		Select @ErrMsg= 'Cannot Insert /Update As User Does Not Have This Rights'
		goto ErrHndlr
	End

	If @mode in ('D') and 
		((Select count('x') from Param join deleted del on PTyp= 'USR' and PMCd= del.ModUsr and PSCd= '' and PNum> 5)> 0) 
 	Begin  
		Select @ErrMsg= 'Cannot Delete As User Does Not Have This Rights'
		goto ErrHndlr
	End
	/* *** Jay 2.14 *** */
	If @mode in ('D') and 
		((Select count('x') from deleted del where del.cmctg = 'Z') > 0)
 	Begin  
		Select @ErrMsg= 'Cannot Delete this CateGOry(Z) of Customer'
		goto ErrHndlr
	End

 	/******** Key Cannot Be Changed ********/ 
 	if @mode = 'C'
 	Begin
		select @Row= Count('x') from deleted del where 
			 not exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd)
		If @Row > 0
		Begin 
			Select @ErrMsg= 'Cannot Change Category/Code'
			goto ErrHndlr
		End

		/****** If CmCtg= 'T' then CmCurncyCd cannot be changed if CTB Voucher Exists ******/
		select @Row= Count('x') from deleted del where CmCtg= 'T' and 
			not exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg 
				and ins.CmCd= del.CmCd and ins.CmCurCd= del.CmCurCd) and 
			exists(Select 'x' from InvHd where InCmCd= CmCd and 
				(Select PValue from Param where PTyp= 'TC' and PMCd= InTc)= 'CTB')
		If @Row> 0
		begin 
			Select @ErrMsg= 'Cannot Change Currency Code As CTB Invoice Exists'
			goto ErrHndlr
		end
	End

	if @mode in ('A','C')
	begin
		/****** Emr 211 (CmCtg-CmName Comb shld be unique) ******/ 
/*		select @row= count('x') from inserted ins where 
			Exists (select 'x' from CustMst CM where ins.CmCd<> CM.CmCd and ins.CmCtg= CM.CmCtg and 
				ins.CmName= CM.CmName) 
*/

		select @row= count('x') from inserted ins where 
			(select count('x') from CustMst CM where ins.CmCtg= CM.CmCtg and 
				ins.CmName= CM.CmName)> 1 
		if @row> 0 
		Begin
			select @errmsg= 'CmCtg-CmName Should Be Unique' 
			goto ErrHndlr
		end

		/****** Valid Customer CategoOry ******/
		select @row=count('x') from inserted where 
			not exists (select 'x' from Param where 
				    PTyp='CMCTG' and PMCd=CmCtg)
		if @row>0 
		Begin
			select @errmsg='CategOry Not Defined'
			goto ErrHndlr
		end

		/****** Contractor Code Can Be Defined Only If The Contractor Module Is To Be Used ******/
		select @row= count('x') from inserted where @mode = 'A' and CmCtg= 'T' and 
			not exists (select 'x' from Head where HCtbMod= 'Y') 
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Enter Contractor Code As ''Show Contractor Module'' Option Of Head File Is ''N'' '
			goto ErrHndlr
		end

		/****** CmCd <> '' ******/
		select @row= count('x') from inserted where CmCd= ''
		if @row> 0 
		Begin
			select @errmsg= 'Customer/Supplier Code Cannot Be Blank'
			goto ErrHndlr
		end

		/****** CmCd can be 'ZSELF' only if CmCtg= 'C' ******/
		/* CmCtg 'S' added Trading Module */
		select @row= count('x') from inserted where CmCd= 'ZSELF' and CmCtg not in ('C' , 'S')
		if @row> 0 
		Begin
			select @errmsg= ' ''ZSELF'' Can Only Belong To CatagOry = ''C'' '
			goto ErrHndlr
		end

		/****** CmCd can be only HCoCd if CmCtg= 'Z' ******/ 
		select @row= count('x') from inserted where CmCtg= 'Z' and 
			not exists(select 'x' from Head where HCd = @wSelfCd and HCoCd= CmCd)
			And SessionProperty('Replication_Agent') <> 1
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Company Code'
			goto ErrHndlr
		end

		/****** CmName <> '' ******/		
		select @row=count('x') from inserted where CmName= ''
		if @row>0 
		Begin
			select @errmsg='Customer/Supplier Name Cannot Be Blank'
			goto ErrHndlr
		end

		/****** CmName can be only HName if CmCtg= 'Z' ******/ 
		Select @row= Count('x') From Inserted Ins Where CmCtg= 'Z' And 
			Exists (Select 'x' From Deleted Del where Ins.CmCtg= del.CmCtg and Ins.CmCd= del.CmCd and 
				Ins.CmName<> del.CmName) And SessionProperty('Replication_Agent') <> 1
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Change the Company Name'
			goto ErrHndlr
		end
		
		/* Commented By Sachin in 2.14.0 Next to allow longer company names in Company Master */
		/*
		select @row= count('x') from inserted ins where CmCtg= 'Z' and 
			Not Exists (Select 'x' from deleted del where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmName= del.CmName) and 
			not exists(select 'x' from Head where HCd = @wSelfCd and HCoCd= CmCd and HName= CmName)
			And SessionProperty('Replication_Agent') <> 1
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Company Name'
			goto ErrHndlr
		end
		*/

	/* ******************Geeta******Crm***2.12*****************/
		select @row= count('x') From Inserted 
		where CmCtg='CC' And (CmMrpMulBy<>0 Or CmMulBy<>0 Or CmFixPrc<>'' Or CmGldAs<>'' Or CmLabAs<>'' Or CmIWtEqOrd<>'' Or 
			CmIWtFrOrd<>'' Or CmIGldRtEqOrd<>'' Or CmDiaRtFA<>'' Or 
			CmCSRtFA<>'' Or CmPrdInst<>'' Or CmStmpInst<>'' Or CmPayTerms<>'' Or 
			CmDelTerms<>'' Or CmAdd1<>'' Or CmAdd2<>'' Or CmAdd3<>'' Or CmTel<>'' Or
			CmFax <>'' Or CmEMail<>'' Or CmPortofDisch<>'' Or 
			CmFinDest<>'' Or CmBuyer<>'' Or CmLkUpRmRt<>'' Or CmLkUpMrpDisc<>'' Or 
			CmLkUpLabRt<>'' Or CmLkUpMetLs<>'' Or CmRegnCd<>'' Or 
			CmHInsBy <>'' Or CmHRndOrdSalPrc<>'' Or 
			CmCurCd<>'' Or CmSalPer<>'' Or CmBuyAdd1<>'' Or
			CmBuyAdd2<>'' Or CmBuyAdd3<>'' Or 
			CmBkCd<>'' Or CmAgCd<>''  Or CmVessel<>'')
		if @row>0 
		Begin
			select @errmsg='Only Customer Code/Customer Name/Customer Designs Should Be Entered'
			goto ErrHndlr
		end
	/* ******************Geeta***********************/

/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
/*	Date: 09/12/2003					Ver: 2.0.6												 */
		select @row = count('x') from inserted where
			not exists (select 'x' from Param where PTyp = 'YN' and PMCd = CmValidYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Valid (Y/N) : (Enter Y/N)'
			goto ErrHndlr
		end
/*  #########################################  Manoj  #########################################  */

		/* 4.1.2 ********************************************************* */
		select @row = count('x') from inserted where
			not exists (select 'x' from Param where PTyp = 'YN' and PMCd = CmInvShowGrsWtYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Valid (Y/N) : (Enter Y/N)'
			goto ErrHndlr
		end

		select @row = count('x') from inserted where
			not exists (select 'x' from Param where PTyp = 'YN' and PMCd = CmInvShowDiaWtYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Valid (Y/N) : (Enter Y/N)'
			goto ErrHndlr
		end

		/* 4.1.2 ********************************************************* */

		/******************Geeta****************Emr206*********************/
		select @row = count('x') from inserted where CmCd in ('ZVALUE','ZSELF') 
			and CmValidYN='N' 
		if @row>0
		Begin
			select @errmsg= 'ZSelf/ZValue Cannot Be InValid '
			goto ErrHndlr
		end
		/******************Geeta****************Emr206*********************/
		/****** If CmGldAs <> '' then 		Valid PMCd('GLDAS')  ******/

		/*** (Jen 2.14) ***/ 
		/* select @row= count('x') from inserted where CmGldAs <> '' and 
			not exists (select 'x' from Param where PTyp= 'GLDAS' and PMCd= CmGldAs
			and not (',' + PDesc225 + ',' like '%,G,%' Or ',' + PDesc225 + ',' like '%,P,%' Or ',' + PDesc225 + ',' like '%,S,%') 
			)
		*/
		select @row= count('x') from inserted where CmGldAs <> '' and 
			not exists (select 'x' from Param where PTyp= 'GLDAS' and PMCd= CmGldAs)
		/*** (Jen 2.14) ***/ 

		/*** (Bef 2.14) 
		select @row= count('x') from inserted where CmGldAs <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='GLDAS' and PMCd= CmGldAs)
		(Bef 2.14) ***/

		if @row>0 
		Begin
			select @errmsg='GOld As Value Not Defined'
			goto ErrHndlr
		end

		/****** If CmLabAs <> '' then 		Valid PMCd('GLDAS')  ******/
		select @row= count('x') from inserted where CmLabAs <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='GLDAS' and PMCd= CmLabAs)
		if @row>0 
		Begin
			select @errmsg='Labour As Value Not Defined'
			goto ErrHndlr
		end
		
		--PYMTRM- Validating Payment Term Code
		/****** If CmPayTermsCd is not blank then it should be Valid PMCd('PYMTRM')  ******/
		select @row= count('x') from inserted where CmPayTermsCd <> '' and 
			not exists (select 'x' from Param where PTyp='PYMTRM' and PMCd= CmPayTermsCd)
		if @row>0 
		Begin
			select @errmsg='Payment Term Code Not Valid'
			goto ErrHndlr
		end
		


		/****** If CmCtg='C' then 		CmLabAs <> ''  ******/
		select @row= count('x') from inserted where CmCtg in ('C', 'T') and CmLabAs = ''
		if @row>0 
		Begin
			select @errmsg= 'Labour As Value Should Be Entered'
			goto ErrHndlr
		end

		/****** CmIWtEqOrd= '' or Valid PMCd ('YN') ******/
		select @row=count('x') from inserted where CmIWtEqOrd <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmIWtEqOrd)
		if @row>0 
		Begin
			select @errmsg= 'Invoice Wts From Order (Enter Y/N)'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmIWtEqOrd <> ''  ******/
		select @row= count('x') from inserted where CmCtg = 'C' and CmIWtEqOrd = '' 
		if @row> 0 
		Begin
			select @errmsg= 'Invoice Wts From Order Should Be Entered' 
			goto ErrHndlr
		end

		/****** If CmIWtEqOrd= 'N' then 		Valid PMCd('IWTFRORD') or '' ******/
		select @row=count('x') from inserted where CmIWtEqOrd= 'N' and 
			CmIWtFrOrd <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='IWTFRORD' and PMCd=CmIWtFrOrd)
		if @row>0 
		Begin
			select @errmsg='Wts From Order Not Defined'
			goto ErrHndlr
		end
		/****** If CmIWtEqOrd= 'Y' then 		Blank ******/
		select @row=count('x') from inserted where CmIWtEqOrd='Y' and 
			CmIWtFrOrd <> '' 
		if @row>0 
		Begin
			select @errmsg='Wts From Order Should Not Be Entered'
			goto ErrHndlr
		end

		/****** CmIGldRtEqOrd  = Blank or PMCd ('YN')  ******/
		select @row=count('x') from inserted where CmIGldRtEqOrd <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmIGldRtEqOrd)
		if @row>0 
		Begin
			select @errmsg= 'Invoice gOld Rate From Order (Enter Y/N)'
			goto ErrHndlr
		end

		-- 4.4.0
		/****** CmSeekZSelfPDCM  = PMCd ('YN')  ******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmSeekZSelfPDCM)
		if @row>0 
		Begin
			select @errmsg= 'Seek ZSelf from PDCM (Enter Y/N)'
			goto ErrHndlr
		end

		/****** CmSeekZSelfRt  = PMCd ('YN')  ******/
		select @row=count('x') from inserted where not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmSeekZSelfRt)
		if @row>0 
		Begin
			select @errmsg= 'Seek ZSelf from Rate Chart (Enter Y/N)'
			goto ErrHndlr
		end
		-- 4.4.0

		/****** If CmCtg='C' then 		CmIGldRtEqOrd <> ''  ******/
		select @row=count('x') from inserted where CmCtg = 'C' and CmIGldRtEqOrd = ''
		if @row>0 
		Begin
			select @errmsg= 'Invoice gOld Rate From Order Cannot Be Blank'
			goto ErrHndlr
		end

		/****** CmDiaRtFA  =  Blank or PMCd ('FA')  ******/
		/*** (Jen 2.14) ***/ 
		select @row= count('x') from inserted where CmDiaRtFA<> '' and CmDiaRtFA<> 'A' 
		/*** (Jen 2.14) ***/ 

		/*** (Bef 2.14) 
		select @row= count('x') from inserted where CmDiaRtFA <> '' and 
			not exists (select 'x' from Param where 
				    PTyp= 'FA' and PMCd= CmDiaRtFA)
		(Bef 2.14) ***/
		if @row> 0 
		Begin
			select @errmsg= 'Enter Diamond Rate Favourable/Actual'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmDiaRtFA <> ''  ******/
		select @row= count('x') from inserted where CmCtg = 'C' and CmDiaRtFA = ''
		if @row> 0 
		Begin
			select @errmsg= 'Enter Diamond Rate Favourable/Actual'
			goto ErrHndlr
		end

		/****** CmCSRtFA  =  Blank or PMCd ('FA')  ******/
		/*** (Jen 2.14) ***/
		select @row= count('x') from inserted where CmCSRtFA <> '' and CmCSRtFA<> 'A'
		/*** (Jen 2.14) ***/

		/*** (Bef 2.14) 		select @row= count('x') from inserted where CmCSRtFA <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='FA' and PMCd= CmCSRtFA)
		(Bef 2.14) ***/

		if @row> 0 
		Begin
			select @errmsg='Enter Colour Stone Rate Favourable/Actual'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmCSRtFA <> ''  ******/
		select @row=count('x') from inserted where CmCtg = 'C' and CmCSRtFA = ''
		if @row>0 
		Begin
			select @errmsg= 'Enter Colour Stone Rate Favourable/Actual'
			goto ErrHndlr
		end

		/****** CmFixPrc  =  Blank  or  PMCd ('YN')  ******/
		select @row= count('x') from inserted where CmFixPrc <> '' and 
			not exists (select 'x' from Param where 
				    PTyp='YN' and PMCd= CmFixPrc)
		if @row>0 
		Begin
			select @errmsg= 'Fixed Price (Enter Y/N)'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmFixPrc <> ''  ******/
		/****** Manali Trading Module - CmCtg='S' added *******/
		select @row=count('x') from inserted where CmCtg In ('C','S') and CmFixPrc = ''
		if @row>0 
		Begin
			select @errmsg= 'Fixed Price (Enter Y/N)'
			goto ErrHndlr
		end

		/****** CmMulby  > 0 ******/
		/****** Manali Trading Module - CmCtg='S' added *******/
		select @row=count('x') from inserted where CmMulby<= 0 and CmCtg in ('C', 'S')  
		if @row>0 
		Begin
			select @errmsg= 'Multiplying Factor Should Be > 0'
			goto ErrHndlr
		end

		/****** CmMrpMulby  > 0 ******/		
		select @row=count('x') from inserted where CmMrpMulby<= 0 and CmCtg in ('C', 'S')  
		if @row>0 
		Begin
			select @errmsg= 'MRP Multiplying Factor Should Be > 0'
			goto ErrHndlr
		end

		/****** If CmRegnCd <> '' then 		Valid PMCd('REGION')  ******/
		select @row= count('x') from inserted where CmRegnCd <> '' and 
			not exists (select 'x' from Param where 
				    PTyp= 'REGION' and PMCd= CmRegnCd)
		if @row> 0 
		Begin
			select @errmsg= 'Region Code Not Defined'
			goto ErrHndlr
		end

		/****** If CmCtg='C' then 		CmRegnCd <> ''  ******/
		select @row=count('x') from inserted where CmCtg in ('C', 'T') and CmRegnCd= ''
		if @row>0 
		Begin
			select @errmsg= 'Region Code Should Be Entered'
			goto ErrHndlr
		end

		/****** CmHRndOrdSalPrc = PMCd('RNDOPT') ******/	
		select @row= count('x') from inserted where CmCtg<>'CC' and 
				not exists (select 'x' from Param where PTyp= 'RNDOPT' and PMCd= CmHRndOrdSalPrc)
		if @row> 0 
		begin
			select @errmsg= 'Round Off Option For Order Sales Price Not Defined'
			goto ErrHndlr
		end

		/****** CmLkUpRmRt, CmLkUpLabRt, CmLkUpMetLs, CmLkUpMrpDisc  =  Blank  (CmCtg= 'T')  ******/
		--pg.5- CmLkUpMrpDisc added 
		select @row= count('x') from inserted ins where CmCtg= 'T' 
			and (CmLkUpLabRt <> '' or CmLkUpRmRt<> '' or CmLkUpMetLs<> '' or CmLkUpMrpDisc<> '' )  
		if @row> 0 
		Begin
			select @errmsg= 'Price List Look Up For Rm Rate, Lab Rate, Metal Loss & MRP Discount Should Not Be Entered For Contractor'
			goto ErrHndlr
		end

		/****** CmLkUpRmRt  =  Blank  or  valid CmCd from CustMst (CmCtg= 'P')  ******/
		select @row= count('x') from inserted ins where CmLkUpRmRt <> '' and 
			not exists (select 'x' from CustMst CM where CM.CmCtg= 'P' 
					and CM.CmCd= ins.CmLkUpRmRt and CM.CmCurCd= ins.CmCurCd)
		if @row>0 
		Begin
			select @errmsg= 'Price List Customer For Rm Rate Look Up Not Defined/ Currency Cd Not Matching'
			goto ErrHndlr
		end

		/****** CmLkUpLabRt  =  Blank  or  valid CmCd from CustMst (CmCtg= 'P')  ******/
		select @row=count('x') from inserted ins where CmLkUpLabRt <> '' and 
			not exists (select 'x' from CustMst CM where CM.CmCtg= 'P' 
					and CM.CmCd= ins.CmLkUpLabRt and CM.CmCurCd= ins.CmCurCd)
		if @row>0 
		Begin
			select @errmsg= 'Price List Customer For Lab Rate Look Up Not Defined/ Currency Cd Not Matching'
			goto ErrHndlr
		end

		/****** CmLkUpMetLs  =  Blank  or  valid CmCd from CustMst (CmCtg= 'P')  ******/
		select @row=count('x') from inserted ins where CmLkUpMetLs <> '' and 
			not exists (select 'x' from CustMst CM where CM.CmCtg= 'P' 
					and CM.CmCd= ins.CmLkUpMetLs and CM.CmCurCd= ins.CmCurCd)
		if @row>0 
		Begin
			select @errmsg= 'Price List Customer For Metal Loss Look Up Not Defined/ Currency Cd Not Matching'
			goto ErrHndlr
		end

		/****** pg.5 CmLkUpMrpDisc =  Blank  or  valid CmCd from CustMst (CmCtg= 'P')  ******/		
		select @row=count('x') from inserted ins where CmLkUpMrpDisc <> '' and 
			not exists (select 'x' from CustMst CM where CM.CmCtg= 'P' 
					and CM.CmCd= ins.CmLkUpMrpDisc)
		if @row>0 
		Begin
			select @errmsg= 'Price List Customer For MRP Discount Look Up Not Defined'
			goto ErrHndlr
		end

		/* sv.44 PDCM look up should be blank for contractor ***/
		select @row= count('x') from inserted ins where CmCtg= 'T' and CmLkUpPDCM <> ''  
		if @row> 0 
		Begin
			select @errmsg= 'PDCM Look Up Should Not Be Entered For Contractor'
			goto ErrHndlr
		end		
		/****** sv.44 CmLkUpPDCM = Blank or valid CmCd   ******/
		select @row= count('x') from inserted ins where CmLkUpPDCM <> '' and 
			not exists (select 'x' from CustMst CM where CM.CmCtg= 'C' 
					and CM.CmCd= ins.CmLkUpPDCM and CM.CmCurCd= ins.CmCurCd)
		if @row>0 
		Begin
			select @errmsg= 'PDCM Look Up Not Defined/ Currency Cd Not Matching'
			goto ErrHndlr
		end		
		/*  sv.44 Cannot Change CurCd of Customer if that customer exists in PDCM lookup */ 
		select @row= count('x') from deleted del where CmCtg= 'C' and 
			Not Exists (Select 'x' from inserted ins where del.CmCtg= ins.CmCtg and del.CmCd= ins.CmCd and 
				del.CmCurCd= ins.CmCurCd) 
			and Exists (select 'x' from CustMst Cm where Cm.CmCtg =del.CmCtg and Cm.CmLkUpPDCM= del.CmCd ) 
		if @row>0 
		Begin
			select @errmsg= 'Customer Currency Code Cannot Be Changed As It Exists In Customer Master For PDCM Look Up'
			goto ErrHndlr
		end
		/****** sv.44 CmTCSYN = valid Y/N   ******/
		select @row = count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= CmTCSYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Apply TCS (Y/N) : (Enter Y/N)'
			goto ErrHndlr
		end

		select @row = count('x') from inserted where 
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= CMAllwNewSOYN)
		if @row>0
		Begin
			select @errmsg= 'Invalid Allow New SO YN : (Enter Y/N)'
			goto ErrHndlr
		end

	/* Zubin 213 (Cannot Change CurCd of CmCtg= 'P' if rec exists in 
			CmLkUpRmRt, CmLkUpLabRt, CmLkUpMetLs, CmLkUpMrpDisc) */ 
		--pg.5- CmLkUpMrpDisc added 
		select @row= count('x') from deleted del where CmCtg= 'P' and 
			Not Exists (Select 'x' from inserted ins where del.CmCtg= ins.CmCtg and del.CmCd= ins.CmCd and 
				del.CmCurCd= ins.CmCurCd) and 
			Exists (select 'x' from CustMst Cm where Cm.CmLkUpRmRt= del.CmCd or Cm.CmLkUpLabRt= del.CmCd or 
				Cm.CmLkUpMetLs= del.CmCd or Cm.CmLkUpMrpDisc= del.CmCd ) 
		if @row>0 
