			select @errmsg= 'Price List Customer Currency Code Cannot Be Changed As It Exists In Customer Master For ''Rm Rate''/''Lab Rate''/''Metal Loss''/''MRP Discount'' Look Up'
			goto ErrHndlr
		end
		/*** Check For Sales Person ***/
		select @row= count('x') from inserted where 
