				    PTyp='SP' and PMCd= CmSalPer)
		if @row> 0 
		Begin
			select @errmsg= 'Enter Valid Sales Executive Code'
			goto ErrHndlr
		end

		/*** Check For Sales Person ***/
		select @row=count('x') from inserted where CmCtg = 'C' and CmSalPer= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Sales Executive Code Cannot Be Blank'
			goto ErrHndlr
		end

		/* Zubin 213 ('C', 'S', 'P') added */ 
		/****** If CmCtg= 'T' then CmCurCd  =  Valid PMCd('CURNCY')  ******/
		select @row= count('x') from inserted where CmCtg In ('C', 'S', 'P', 'T') and 
			not exists (select 'x' from Param where 
				    PTyp= 'CURNCY' and PMCd= CmCurCd and PSCd= '')
		if @row> 0 
		Begin
			select @errmsg= 'Currency Code Not Defined'
			goto ErrHndlr
		end
		/* Zubin 213 (Before 213) */ 
		/****** If @SYS= '' Then CmCurCd  =  'US$'   ******/ 
/*		select @row= count('x') from inserted where @SYS= '' and CmCtg in ('C', 'S', 'P', 'Z') 
			and CmCurCd<> 'US$'
		if @row> 0 
		begin
			select @errmsg= 'Currency Code Should Be US$'
			goto ErrHndlr
		end
*/
		/* Zubin 213 */ 
		/****** CmCurCd can be only HBaseCurCd if CmCtg= 'C' and HMultiCurYN= 'N' ******/ 
		select @row= count('x') from inserted ins where @SYS= '' and CmCtg IN ('C', 'P') and 
			Not Exists (Select 'x' from deleted del where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			Exists (Select 'x' from Head where HCd= @wSelfCd and HCoCd= 'ZZZ' and HMultiCurYn= 'N' ) and 
			Not Exists(select 'x' from Head where HCd = @wSelfCd and HCoCd= 'ZZZ' and HBaseCurCd= CmCurCd) 
		if @row> 0 
		Begin
			select @errmsg= 'Customer Currency Invalid As Multi Currency Is Not Enabled' 
			goto ErrHndlr
		end

		/****** CmCurCd can be only HBaseCurCd if CmCtg= 'Z' ******/ 
		select @row= count('x') from inserted ins where @SYS= '' and CmCtg= 'Z' and 
			Not Exists (Select 'x' from deleted del where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			not exists(select 'x' from Head where HCd = @wSelfCd and HCoCd= CmCd and HBaseCurCd= CmCurCd) 
			And SessionProperty('Replication_Agent') <> 1
		if @row> 0 
		Begin
			select @errmsg= 'Company Currency Invalid' 
			goto ErrHndlr
		end
		/* Zubin 213 (if CmCurCd= Base Cur then it's '01/01/80' rec shld exist with other base curr in 
				DtTbl (DtTag= 'CNV')) 
			(if CmCurCd<> Base Cur then it's '01/01/80' rec shld exist with all base curr in DtTbl (DtTag= 'CNV')) */ 
/*		select @row= count('x') from inserted ins where @SYS= '' and 
			(
			Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= CmCurCd) and 
			Exists (select 'x' from Head where HCd= @wSelfCd and HBaseCurCd<> CmCurCd and 
				Not Exists (Select 'x' from DtTbl where DtTag= 'CNV' and DtDt= '01/01/80' and 
						( (DtCurCd1= CmCurCd and DtCurCd2= HBaseCurCd) or 
							(DtCurCd2= CmCurCd and DtCurCd1= HBaseCurCd) )
					    ) 
				) 
			)
			OR 
			(
			Not Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= CmCurCd) and 
			Exists (select 'x' from Head where HCd= @wSelfCd and 
				Not Exists (Select 'x' from DtTbl where DtTag= 'CNV' and DtDt= '01/01/80' and 
						( (DtCurCd1= CmCurCd and DtCurCd2= HBaseCurCd) or 
							(DtCurCd2= CmCurCd and DtCurCd1= HBaseCurCd) )
					    ) 
				) 
			)
		if @row>0 
		Begin
			select @errmsg= 'Invalid Currency Code As Record Does Not Exist In Date Table With All Base Currencies'
			goto ErrHndlr
		end
*/
		/* CmCurCd cannot be changed if rec exists in RmRt */ 
		select @Row= Count('x') from deleted del where @SYS= '' and CmCtg In ('C', 'P', 'T') and 
			Not Exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			Exists (Select 'x' from RmRt where RrTcTyp In ('RM', 'LMG', 'LMP', 'LMS') and RrCmCd= CmCd) 
		If @Row > 0
		Begin 
			Select @ErrMsg= 'Cannot Change Currency Code As Rm Rate Exists For This Customer'
			goto ErrHndlr
		End
		/* CmCurCd cannot be changed if rec exists in LabRt */ 
		select @Row= Count('x') from deleted del where @SYS= '' and CmCtg<> 'Z' and 
			Not Exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			Exists (Select 'x' from LabRt where LrCmCd= CmCd ) 
		If @Row > 0
		Begin 
			Select @ErrMsg= 'Cannot Change Currency Code As Labour Rate Exists For This Customer'
			goto ErrHndlr
		End
		/* CmCurCd cannot be changed if rec exists in RmRtHist */ 
		select @Row= Count('x') from deleted del where @SYS= '' and CmCtg In ('C', 'P') and 
			Not Exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			Exists (Select 'x' from RmRtHist where RhTcTyp = 'RM' and RhCmCd= CmCd) 
		If @Row > 0
		Begin 
			Select @ErrMsg= 'Cannot Change Currency Code As Rm Rate History Exists For This Customer'
			goto ErrHndlr
		End
		/* CmCurCd cannot be changed if OrdMst rec exists for the CmCd */ 
		select @Row= Count('x') from deleted del where @SYS= '' and CmCtg= 'C' and 
			Not Exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			  Exists (Select 'x' from OrdMst where OmCmCd= CmCd) 
		If @Row > 0 
		Begin 
			Select @ErrMsg= 'Cannot Change Currency Code As Order Exists For This Customer'
			goto ErrHndlr
		End
		/* CmCurCd cannot be changed if 'PR' rec exists */ 
		select @Row= Count('x') from deleted del where @SYS= '' and CmCtg= 'S' and 
			Not Exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			  Exists (Select 'x' from Txn where TTc= 'PR' and CmCd= TSuppCd) 
		If @Row > 0 
		Begin 
			Select @ErrMsg= 'Cannot Change Currency Code As Purchase Voucher Exists For This Supplier'
			goto ErrHndlr
		End
		/* CmCurCd cannot be changed if 'SA' rec exists */ 
		select @Row= Count('x') from deleted del where @SYS= '' and CmCtg= 'C' and 
			Not Exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			  Exists (Select 'x' from Txn where TTc= 'SA' and CmCd= TSuppCd) 
		If @Row > 0 
		Begin 
			Select @ErrMsg= 'Cannot Change Currency Code As Sales Voucher Exists For This Customer' 
			goto ErrHndlr
		End
		/* CmCurCd cannot be changed if CmCd exists in InvHd (IN) */ 
		select @Row= Count('x') from deleted del where @SYS= '' and CmCtg= 'C' and 
			Not Exists (Select 'x' from inserted ins where ins.CmCtg= del.CmCtg and ins.CmCd= del.CmCd and 
				ins.CmCurCd= del.CmCurCd) and 
			  Exists (Select 'x' from InvHd where InCmCd= CmCd and 
				(Select PValue from Param where PTyp= 'TC' and PMCd= InTc)= 'IN') 
		If @Row > 0 
		Begin 
			Select @ErrMsg= 'Cannot Change Currency Code As Invoice Exists For This Customer' 
			goto ErrHndlr
		End

		/* Zubin 213 */ 

		/*** Check For Valid Agent Code ***/
		select @row= count('x') from inserted where CmAgCd <> '' and  
			Not exists (Select 'x' from BnkAgMst where BkCtg = 'A' and BkCd = CmAgCd)
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Agent Code'
			goto ErrHndlr
		end

		/*** CmAgCd<> '' when CmCtg= 'C' ***/
		select @row= count('x') from inserted where CmCtg= 'C' and CmAgCd= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Agent Code Cannot Be Blank'
			goto ErrHndlr
		end

		/* Sachin - 4.1.0.0 */
		select @row= count('x') from inserted where CmGrp <> '' and  
			Not exists (Select 'x' from Param where PTyp='CMGRP' and PMCd=CmGrp)
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Customer Group'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where CmCtg= 'C' and CmGrp= '' 
		if @row> 0 
