			select @errmsg= 'Customer Group Cannot Be Blank'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where CmTyp <> '' and  
			Not exists (Select 'x' from Param where PTyp='CMTYP' and PMCd=CmTyp)
		if @row> 0 
		Begin
			select @errmsg= 'Invalid Customer Type'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where CmCtg= 'C' and CmTyp= '' 
		if @row> 0 
		Begin
			select @errmsg= 'Customer Type Cannot Be Blank'
			goto ErrHndlr
		end

		select @row= count('x') from inserted where CmPod <> '' and  
			Not exists (Select 'x' from Param where PTyp='PORTCD' and PMCd=CmPod)
