			select @errmsg= 'Cannot Delete As Price List Customer In Use In CustMst Table'
			goto ErrHndlr
		end
		select @row= count('x') from deleted del where CmCtg = 'C' 
			and exists (select 'x' from CustMst CM where CmCtg='C' and CM.CmLkUpPDCM = del.CmCd )
		if @row> 0 
