			select @errmsg= 'Cannot Delete As PDCM Customer In Use In CustMst Table'
			goto ErrHndlr
		end
		select @row= count('x') from deleted where exists (select 'x' from CustDsg where CmCtg= CdCtg and CmCd= CdCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Design Exists'
			goto ErrHndlr
		end

