		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Alloy Exists'
			goto ErrHndlr
		end

		/**** Shilpa Emr 2.04 ****/
		select @row= count('x') from deleted where exists (select 'x' from CustRm where CmCtg= CrCtg and CmCd= CrCd)
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Rm Exists'
			goto ErrHndlr
		end
		/**** Shilpa Emr 2.04 ****/
		/* 578-20 checking customer store records exists or not */
		select @row= count('x') from deleted where exists (select 'x' from CustStore where CmCtg= CstCmCtg and CmCd= CstCmCd )
		if @row> 0 
		Begin
			select @errmsg= 'Cannot Delete As Customer Store Records Exists'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where CmCtg in ('C', 'P', 'S', 'T') 
			and exists (select 'x' from LabRt where LrCmCtg= CmCtg and LrCmCd= CmCd)
		if @row> 0 
