				goto ErrHndlr
			end
		End
		--PG.11 
		if @vPTyp = 'GSTTCCHR' 
		Begin 
			/****** vPMCd = Valid Tc ******/ 
			select @row= count('x') from inserted where not exists (select 'x' from Param where PTyp ='TC' and PMCd = vPMCd)
			if @row>0 
			begin
				select @errmsg= 'Tc Not Defined'
				goto ErrHndlr
			end											
			/****** vPSCd = Valid CHR ******/
			select @row= count('x') from inserted ins where vPSCd<> '' and 
				not exists (select 'x' from vParam Prm where Prm.vPCoCd= ins.vPCoCd and Prm.vPTyp= 'CHR' 
				and Prm.vPMCd= ins.vPMCd and Prm.vPSCd= ins.vPSCd )
			if @row>0 
			begin
				select @errmsg= 'Chr Not Defined'
				goto ErrHndlr
			end						
			/****** vPValue = valid GstCode ******/			
			select @row= count('x') from inserted where not exists (select 'x' from Param where PTyp ='GSTCD' and PMCd = vPValue)
			if @row> 0 
			begin
				select @errmsg= 'Gst Code Not Defined'
				goto ErrHndlr
			end
			/****** vPNum = 0 ******/
			select @row=count('x') from inserted where vPNum<> 0
			if @row>0 
			begin
				select @errmsg= 'vPNum Should Be Zero'
				goto ErrHndlr
			end
			/****** vPDesc = Blank ******/
			select @row=count('x') from inserted where vPDesc<> ''
			if @row>0 
			begin
				select @errmsg= 'vPDesc Should Be Blank'
				goto ErrHndlr
			end
			/****** vPDesc225 = Blank ******/
			select @row=count('x') from inserted where vPDesc225<> ''
			if @row>0 
			begin
				select @errmsg= 'vPDesc225 Should Be Blank'
				goto ErrHndlr
			end
			/****** vPValue1 = Blank ******/
