			select @row= count('x') from deleted del where exists (select 'x' from vParam Pm where Pm.vPCoCd= del.vPCoCd 
					and Pm.vPTyp= 'GSTTCCHR' and Pm.vPmCd= del.vPMCd and Pm.vPSCd= del.vPSCd) 
			if @row> 0 
