			end
			/****** Cannot delete Line in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and OdLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdDsg Table'
				goto ErrHndlr
			end
			/****** Cannot delete Line in use in OrdPln table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdPln where OpCoCd= vPCoCd and OpLine= vPMCd)
			if @row>0 
			Begin
				select @errmsg= 'Cannot Delete As Line In Use In OrdPln Table'
				goto ErrHndlr
			end
		End
/* InUse Check */
		if @vPTyp= 'PRDSEQ' 
		Begin 
			/****** Cannot delete Production Sequence in use in DsgMst table ******/
			select @row=count('x') from deleted del where 				
				exists (select 'x' from DsgMst where (',' + DmPrdSeq + ',') like ('%,' + vPMCd + ',%'))
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In DsgMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in Head table ******/
			select @row=count('x') from deleted del where 			
				exists (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd and (',' + hDmPrdSeq + ',') like ('%,' + vPMCd + ',%'))
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Head Table'
				goto ErrHndlr
			end
			/****** Cannot delete Production Sequence in use in OrdDsg table ******/
			select @row=count('x') from deleted del where 				
				exists (select 'x' from OrdDsg where OdCoCd= vPCoCd and (',' + OdPrdSeq + ',') like ('%,' + vPMCd + ',%') )
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In OrdDsg Table'
				goto ErrHndlr
			end

			/****** Cannot delete Production Sequence in use in Param table where PTyp= 'PRDCTG' ******
			select @row=count('x') from deleted del where 
				exists (select 'x' from Param Pm where Pm.PTyp= 'PRDCTG' and Pm.PValue= del.vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Param Table Where PTyp= 'PRDCTG''
				goto ErrHndlr
			end
			*/
			/****** Cannot delete Production Sequence in use in OrdLn table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdLn where OdlCoCd= vPCoCd and OdlPrdSEQ = vPMCd )
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In OrdLn Table'
				goto ErrHndlr
			end	
						
			if @wPpcSystemInstalled > 0 
			begin
			/****** Cannot delete Production Sequence in use in PD.PDMst table ******/			
			select @row=count('x') from deleted del where 
                  exists (select 'x' from PD.PDMst where PdmLocSeq = vPMCd )
            if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In PD.PDMst Table'
				goto ErrHndlr
			end	
			/****** Cannot delete Production Sequence in use in Ppc.PpcMst table ******/			
			select @row=count('x') from deleted del where 
                  exists (select 'x' from Ppc.PpcMst where PpmLocSEQ = vPMCd )
            if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In Ppc.PpcMst Table'
				goto ErrHndlr
			end	
			/****** Cannot delete Production Sequence in use in PD.PdDet table ******/			
			select @row=count('x') from deleted del where 
                  exists (select 'x' from PD.PdDet where PddLocSeq = vPMCd )
            if @row>0 
			Begin
				select @errmsg='Cannot Delete As Production Sequence In Use In PD.PdDet Table'
				goto ErrHndlr
			end							
			end
			
		End
		/* InUse Check */
		if @vPTyp= 'PRCSSEQ' 
		Begin 
			/****** Cannot delete Process Sequence in use in DsgMst table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from DsgMst where (',' + DmPrcsSeq + ',') like ('%,' + vPMCd + ',%'))
			if @row>0
			Begin
				select @errmsg='Cannot Delete As Process Sequence In Use In DsgMst Table'
				goto ErrHndlr
			end
			/****** Cannot delete Process Sequence in use in Head table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Head where HCoCd= vPCoCd and HCd= @wHCd and (',' + hDmPrcsSeq + ',') like ('%,' + vPMCd + ',%'))
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Process Sequence In Use In Head Table'
				goto ErrHndlr
			end			
			/****** Cannot delete Process Sequence in use in OrdLn table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from OrdLn where OdlCoCd= vPCoCd and OdlPrcsSEQ = vPMCd )
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Process Sequence In Use In OrdLn Table'
				goto ErrHndlr
			end		
			/****** Cannot delete Process Sequence in use in vParam table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from vParam where vPCoCd = del.vPCoCd and vPTyp ='PRDSEQ' and vPValue1 = del.vPMCd)
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Process Sequence In Use In vParam where vPTyp = PRDSEQ'
				goto ErrHndlr
			end		
			
			if @wPpcSystemInstalled > 0 
			begin
			/****** Cannot delete Process Sequence in use in PD.PDMst table ******/			
			select @row=count('x') from deleted del where 
                  exists (select 'x' from PD.PDMst where PdmPrcsSeq = vPMCd )
            if @row>0 
			Begin
				select @errmsg='Cannot Delete As Process Sequence In Use In PD.PDMst Table'
				goto ErrHndlr
			end	
			/****** Cannot delete Process Sequence in use in Ppc.PpcMst table ******/			
			select @row=count('x') from deleted del where 
                  exists (select 'x' from Ppc.PpcMst where PpmPrcsSeq = vPMCd )
            if @row>0 
			Begin
				select @errmsg='Cannot Delete As Process Sequence In Use In Ppc.PpcMst Table'
				goto ErrHndlr
			end				
			end
		End

		if @vPTyp= 'WORK' 
		Begin 
			/****** Cannot delete Worker in use in Bag table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Bag where BCoCd= vPCoCd and BWrk= vPMCd)
			if @row>0 
			Begin
			select @errmsg='Cannot Delete As Worker In Use In Bag Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in Txnd table ******/
			select @row=count('x') from deleted del where 
				exists (select 'x' from Txnd where TdCoCd= vPCoCd and (TdWrk= vPMCd or TdByWrk= vPMCd))
			if @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In Txnd Table'
				goto ErrHndlr
			end
			/****** Cannot delete Worker in use in TxndPrd table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndPrd where TpCoCd= vPCoCd and TpByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndPrd Table'
				goto ErrHndlr
			End
			/****** Bhavna Cannot delete Worker in use in TxndRwrk table ******/
			Select @row=count('x') from deleted del where 
				exists (select 'x' from TxndRwrk where TrwCoCd= vPCoCd and TrwByWrk= vPMCd)
			If @row>0 
			Begin
				select @errmsg='Cannot Delete As Worker In Use In TxndRwrk Table'
				goto ErrHndlr
			End

		End
/* InUse Check */
		if @vPTyp In ('WIWSEQ','WIWLONG','RWIWSEQ','RWIWLONG')
		Begin 
			/* ****** WIWSEQ/WIWLONG/RWIWSEQ/RWIWLONG Cannot be deleted From ZZZ if it exists in other companies ****** */
			Select @Row=Count('x') From Deleted Del Where Del.vPCoCd=@wSelfCoCd And Del.vPTyp In ('WIWSEQ','WIWLONG','RWIWSEQ','RWIWLONG') And Del.vPValue3='N' 
				And Exists (Select 'x' From vParam vWIW Where vWIW.vPCoCd<>@wSelfCoCd And Del.vPTyp=vWIW.vPTyp And Del.vPMCd=vWIW.vPMCd 
							And Del.vPValue3=vWIW.vPValue3)  			
			If @Row > 0
			Begin
				select @errmsg= 'Cannot Delete As '+ @vPTyp + ' Sequence Exists in One of the Companies'
				goto ErrHndlr
			End
		End	
		/* *** JAY 3.2.0 [AutoTree] */ 
		if @vPTyp= 'TRDEF' 
		Begin 
			select @row=count('x') from deleted del 
			if @row>0 
			Begin
			select @errmsg='Cannot Delete Record'
				goto ErrHndlr
			end
		end
		/* *** JAY 3.2.0 [AutoTree] */ 
	End

	Return

ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
end



GOGO




ALTER TRIGGER [dbo].[Head_INUPDL] ON [dbo].[Head]
    FOR INSERT,UPDATE,DELETE NOT FOR REPLICATION
AS
BEGIN
	/* *** Trigger Version 3.11.0 *** */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @wSelfCd VARCHAR(8)
	DECLARE @wSelfCoCd varchar(3)
	DECLARE @ReplAgt BIT
	
	set @wSelfCoCd= 'ZZZ'
	set @wSelfCd = 'ZSELF'	

	IF @@ROWCOUNT=0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Head')
		RETURN

	select @mode=case (select count('x') from inserted) when 0 then 'D'
			else
			case (select count('x') from deleted) when 0 then 'A' else 'C' end
			end 

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		select @ROW =Count('x')  From inserted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd  +',%')
				or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 
		if @mode in ('D')
		Begin 
		select @ROW =Count('x')  From Deleted where  
		Exists ( select 'x' From SysDb where (SysId='EMR' and ','+sdCocd+',' Not  like '%,'+ HCoCd  +',%')
				or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 
	End	

	If @mode in ('A' , 'C')
	Begin
	/* Zubin 211 (hFluteBagYN= ins.hFluteBagYN and HDTPrdPtr= ins.HDTPrdPtr added) */ 
		/*** introduced hLooseInv (Jen 2.12 Patch 3)***/
		/*** introduced HConsolidatedInv, HAutomateReturns (Jen 2.13)***/
