  end     

  select @row= count('x') from inserted where @wIsJLTc = 'N' and OdExpDelDt= '01/01/1900' or (OdExpDelDt<> '01/01/1980' and     
   OdExpDelDt < (Select OmDt from OrdMst where OmIdNo=OdOmIdNo and OmCoCd= OdCoCd     
