 if @mode ='C'  
 Begin  
 if @wTcTyp = 'JT'   
  Begin  
  Select @row=Count('x') from deleted Del   
   Join TcMst On TmCoCd=Del.OdCoCd and TmTc=Del.OdTc  
   Where @wIsJLTc = 'N' and
   exists(Select 'x' from OrdDsg Od Where 
      Od.OdBaseIdKey=Del.OdIdNo)  
