  Where Exists (Select 'X' From Head where HCoCd= Ins.TdCoCd and HCd= @wHCd and              
        HNegStkYn= 'N')              
  and not Exists (select 'x' from Param Join UsrAccess on UaUsrCd = PMCd where PTyp= 'USR' and               
