		And Not Exists (Select 'x' From Deleted del Where ins.RrTcTyp=del.RrTcTyp and ins.RrCmCtg=del.RrCmCtg
						and ins.RrCmCd=del.RrCmCd and ins.RrCmCurCd=del.RrCmCurCd and ins.RrCtg=del.RrCtg and ins.RrSCtg=del.RrSCtg 
						and ins.RrSTWGrp=del.RrSTWGrp and ins.RrCd=del.RrCd and ins.RrDmCtg=del.RrDmCtg and ins.RrDmCd=del.RrDmCd
						and ins.RrLsCtg=del.RrLsCtg and ins.RrLabMCd=del.RrLabMCd and ins.RrFrLn=del.RrFrLn and ins.RrToLn=del.RrToLn And ins.RrPrtKey<>del.RrPrtKey)
