	select @row= count('x') from inserted where RrCstRt=0 and
  		(Select TsBlank from TcStr where TsTbl='RmRt'
   		and TsTyp= RrTcTyp and TsSTyp=RrCtg and TsIdName= 'RrCstRt') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Purchase Rate Cannot Be Zero'
  		goto ErrHndlr
 	end
	
	/******  If TsBlank from TcStr(TsTbl= 'RmRt', TsTyp= RrTcTyp, TsSTyp= RrCtg, TsIdName= 'RrSalRt') = 'N' 	then 	RrSalRt  =  Not Blank  ******/
	select @row= count('x') from inserted where RrSalRt= 0 and RrTcTyp <>'IPD' and
  		(Select TsBlank from TcStr where TsTbl= 'RmRt'
   		and TsTyp= RrTcTyp and TsSTyp= RrCtg and TsIdName= 'RrSalRt') = 'N'
 	if @row> 0
 	Begin
  		select @errmsg= 'Sales Rate Cannot Be Zero'
  		goto ErrHndlr
 	end
 	/***** Ec.2 if RrTcTyp='Rm' and RrCtg <>'X' then Cost Rate Should not be entered **************/
 	select @row= count('x') from inserted where RrTcTyp in ('RM','IPD') and RrCtg <>'X' and RrCtg <>'G' and RrCtg <>'P' and RrCtg <>'S' and RrCtg <>'L'   and RrFixMinTol> 0   		
 	if @row> 0
 	Begin
  		select @errmsg= 'Cost Rate Increment Cannot Be Entered For This Rm Category'
  		goto ErrHndlr
 	end
	/***** Ec.2 if RrTcTyp='Rm' and RrCtg <>'X' then Sales Rate Should not be entered **************/
 	select @row= count('x') from inserted where RrTcTyp in ('RM','IPD') and RrCtg <>'X' and RrCtg <>'G' and RrCtg <>'P' and RrCtg <>'S' and RrCtg <>'L' and RrFixMaxTol> 0   		
 	if @row> 0
 	Begin
  		select @errmsg= 'Sales Rate Increment Cannot Be Entered For This Rm Category'
  		goto ErrHndlr
 	end
 	
	/******  If RrTcTyp in ('XDM', 'XIA', 'XIO','XZA')   then 	RrCstRt <> 0 or  RrSalRt <> 0  ******/
	select @row= count('x') from inserted where RrTcTyp in('XDM', 'XIA', 'XIO','XZA') and RrCstRt= 0 and RrSalRt= 0 and RrXWtPer= 0
 	if @row> 0
 	Begin
  		select @errmsg= 'Extra Cents, Round Off And Extra Wt Percentage Value All Cannot Be Zero'
  		goto ErrHndlr
 	end

	/******  If RrTcTyp in ('XDM', 'XIA', 'XIO','XZA')   then 	RrCstRt = 0 or  RrSalRt = 0  ******/
	select @row= count('x') from inserted where RrTcTyp in('XDM', 'XIA', 'XIO','XZA') and 
			((RrCstRt<> 0 and RrSalRt<> 0) or (RrCstRt<> 0 and RrXWtPer<> 0) or (RrXWtPer<> 0 and RrSalRt<> 0))
 	if @row> 0
 	Begin
  		select @errmsg= 'Only One OF Extra Cents, Round Off And Extra Wt Percentage Value Should Be Entered'
  		goto ErrHndlr
 	end

/************* RN Comment for CR 5.6 B ***********

	/******  If RrTcTyp in ('XDM', 'XIA', 'XIO','XZA')   and  RrSalRt<> 0  then 	RrSalRt  >=  RrToLn  ******/
	select @row= count('x') from inserted where RrTcTyp in('XDM', 'XIA', 'XIO','XZA') and RrSalRt<> 0 and RrSalRt< RrToLn
 	if @row> 0
 	Begin
  		select @errmsg= 'Round Off Value Should Be Greater Than To Wt'
  		goto ErrHndlr
 	end

************RN Comment for CR 5.6 B Over ***/

	/******** all recs of 'XDM', 'XIA', 'XIO','XZA' should have Blank RmSubCtgs or all of then should have valid RmSubCtgs ********/
	select @row= count('x') from inserted ins where ins.RrTcTyp in('XDM', 'XIA', 'XIO','XZA') 
		and ins.RrSCtg<> '' and exists(Select 'x' from RmRt Rr where Rr.RrTcTyp= ins.RrTcTyp and Rr.RrSCtg= '') 
	If @Row> 0
	begin
		Select @ErrMsg= 'Record With Blank Raw Material Sub Category Exists Hence Raw Material Sub Category Should Be Blank'
		GoTo ErrHndlr
	end

	/******** all recs of 'XDM', 'XIA', 'XIO','XZA' should have Blank RmSubCtgs or all of then should have valid RmSubCtgs ********/
	select @row= count('x') from inserted ins where ins.RrTcTyp in('XDM', 'XIA', 'XIO','XZA') 
		and ins.RrSCtg= '' and exists(Select 'x' from RmRt Rr where Rr.RrTcTyp= ins.RrTcTyp and Rr.RrSCtg<> '') 
	If @Row> 0
	begin
		Select @ErrMsg= 'Record With Non Blank Raw Material Sub Category Exists Hence Raw Material Sub Category Should Not Be Blank'
		GoTo ErrHndlr
	end
	/* Zubin 213 */ 
	/* Manali 3.03 - 17/06/08 - 'LML' added */
	/* Manali 3.6.1 - 'IMK' added */
	/*bhavna removed check for CHN*/
	/*indigo-162- Tctyp-LS included **/
	Select @row= count('x') from inserted where RrTcTyp Not In ('IPD','RM', 'LMG', 'LMP', 'LMS', 'LML', 'IMK','IMC', 'CHN','MRP','LS') and RrCmCurCd<> '' 
	if @row> 0
 	Begin
		select @errmsg= 'Currency Code Should Not Be Entered'
		goto ErrHndlr
 	end
	/* Zubin 213 (Before 213) */ 

	/* *** Jay 3.01 *** [ILC] */
	select @row= count('x') from inserted ins where ins.RrTcTyp = 'ILC' and ins.RrSalRt not in (0,1,5,10,50,100)
	If @Row> 0
	begin
		Select @ErrMsg= 'Only Valid Round Of Values Can be entered (0/ 1/ 5/ 10/ 50/ 100)'
		GoTo ErrHndlr
	end

	select @row= count('x') from inserted where RrTcTyp = 'ILC' and RrFixMinTol > RrFixMaxTol 
 	if @row> 0
 	Begin
  		select @errmsg= 'Minimum Increment Should Be Less Than Maximum Increment'
  		goto ErrHndlr
 	end
	/* *** Jay 3.01 *** [ILC] */

    	/***** pg.5 RrDmCd=valid DmCd in DsgMst ****/
	select @row= count('x') from inserted Ins where Ins.RrPrtKey=@wCurrPrtn and Ins.RrTcTyp in ('MRP','MRD') and
		 Ins.RrDmCd<> '' and not exists (select 'x' from DsgMst where DmPrtKey=RrPrtKey and DmTcTyp = 'DM' And
       		DmCd= Ins.RrDmCd and  DmSz = '' )		
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Code is Not Defined'
  		goto ErrHndlr
 	end  
 	/***** pg.5 RrDmSz=valid DmSz in Param ****/
	select @row= count('x') from inserted where  RrDmSz <> '' and 
		not exists (select 'x' from Param where PTyp='DMSZ' and PMCd = RrDmSz )		
 	if @row> 0
 	Begin
  		select @errmsg= 'Design Size is Not Defined'
  		goto ErrHndlr
 	end   
/*	select @row= count('x') from inserted where @SYS= '' and RrTcTyp= 'RM' and RrCmCurCd<> 'US$' 
	if @row> 0 
	begin
		select @errmsg= 'Currency Code Should Be US$' 
		goto ErrHndlr
	end
*/

	/* Zubin 213 Curr Cd = valid curr cd from Param where CmCd = 'ZSELF' or 'ZVALUE' 
		     Curr Cd = valid curr cd from CustMst where CmCd <> 'ZSELF' */ 
	/* Manali 3.03 - 17/06/08 - 'LML' added */
	/*indigo-162- Tctyp-LS included **/
	Select @row= count('x') from inserted where @SYS= '' and RrTcTyp In ('IPD','RM', 'LMG', 'LMP', 'LMS', 'LML','MRP') and 
		(     	((RrCmCd= 'ZSELF' or RrCmCd= 'ZVALUE') and 
				Not Exists(select 'x' from Param where PTyp= 'CURNCY' and PMCd= RrCmCurCd and PSCd= '') 
		      	)
		      	Or 
		      	((RrCmCd <> 'ZSELF' and RrCmCd<> 'ZVALUE') and 
				Not exists (select 'x' from CustMst where CmCtg= RrCmCtg 
					and CmCd= RrCmCd and CmCurCd= RrCmCurCd) 
			)
		)
	if @row> 0 
	begin
		select @errmsg= 'Invalid Currency Code' 
		goto ErrHndlr
	end

	Select @row= count('x') from inserted where @SYS= '' and RrTcTyp In ('LS') and RrCmCurCd<>'' and 
		(     	((RrCmCd= 'ZSELF' or RrCmCd= 'ZVALUE') and 
				Not Exists(select 'x' from Param where PTyp= 'CURNCY' and PMCd= RrCmCurCd and PSCd= '') 
		      	)
		      	Or 
		      	((RrCmCd <> 'ZSELF' and RrCmCd<> 'ZVALUE') and RrCmCurCd <>'' 
			)
		)
	if @row> 0 
	begin
		select @errmsg= 'Currency code can only be entered for ZSELF and ZValue Customer Code, make sure its a valid Currency Code' 
		goto ErrHndlr
	end

	/* NOT REQUIRED */ 
	/* Zubin 213 (if CmCurCd= Base Cur then it's '01/01/80' rec shld exist with other base curr in 
			DtTbl (DtTag= 'CNV')) 
		(if CmCurCd<> Base Cur then it's '01/01/80' rec shld exist with all base curr in DtTbl (DtTag= 'CNV')) */ 
/*	Select @row= count('x') from inserted where @SYS= '' and RrTcTyp In ('RM', 'LMG', 'LMP', 'LMS') and 
		(
			(
			Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= RrCmCurCd) and 
			Exists (select 'x' from Head where HCd= @wSelfCd and HBaseCurCd<> RrCmCurCd and 
				Not Exists (Select 'x' from DtTbl where DtTag= 'CNV' and DtDt= '01/01/80' and 
						( (DtCurCd1= RrCmCurCd and DtCurCd2= HBaseCurCd) or 
							(DtCurCd2= RrCmCurCd and DtCurCd1= HBaseCurCd) )
					    ) 
				) 
			)
		OR 
			(
			Not Exists (Select 'x' from Head where HCd= @wSelfCd and HBaseCurCd= RrCmCurCd) and 
			Exists (select 'x' from Head where HCd= @wSelfCd and 
				Not Exists (Select 'x' from DtTbl where DtTag= 'CNV' and DtDt= '01/01/80' and 
						( (DtCurCd1= RrCmCurCd and DtCurCd2= HBaseCurCd) or 
							(DtCurCd2= RrCmCurCd and DtCurCd1= HBaseCurCd) )
					    ) 
				) 
			)
		)
	if @row>0 
	Begin
		select @errmsg= 'Invalid Currency Code As Record Does Not Exist In Date Table With All Base Currencies'
		goto ErrHndlr
	end
*/
	/*****************Bef Emr206************************
	select @row= count('x') from inserted ins where
  		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and
                        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and
		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and
   		Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and 
		Rt.RrCmCurCd= ins.RrCmCurCd and Rt.RrCtg= ins.RrCtg and
   		Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
		Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and 
		Rt.RrLsCtg= ins.RrLsCtg and Rt.RrLabMCd= ins.RrLabMCd
   		and  (    (Rt.RrFrLn<= ins.RrFrLn and
      			 Rt.RrToLn>= ins.RrFrLn)
		    or  	(Rt.RrFrLn<= ins.RrToLn and
		      	 Rt.RrToLn>= ins.RrToLn)
    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
			 ins.RrToLn>= Rt.RrToLn)
		 )
  		) > 1   */


	/**********************Geeta***Emr206**05/04/04****** If 'BS' Record exists for the same 
				Combination then don't check the Size Range******/
	/******  The Size Range should be unique  (i.e. it shouldn't overlap other size 
		ranges for the same RrTcTyp, RrCmCd, RrCmCurCd, RrDmCd, RrCtg, RrSCtg, RrCd, 
		RrDmCtg, RrLabMCd combination)  ******/
	/**********Geeta*********Emr207*********Range Size Check not reqd for Both Sides Wt-'BSW'*********/ 
	/* *** JAY 3.01 [NAS] *** */
	/*bhavna removed check for CHN*/
	select @row= count('x') from inserted ins where  ins.RrTcTyp not in ('BSW', 'NAS', 'CHN','MRP','MRD') and
  		IsNull((Select PValue from Param where PTyp= 'RMSCTG' and
                        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and
		not exists (Select * from RmRt Rr where Rr.RrTcTyp= 'BS' and
   		Rr.RrCmCtg=ins.RrCmCtg and Rr.RrCmCd= ins.RrCmCd and 
		Rr.RrCmCurCd='' and Rr.RrCtg= ins.RrCtg and
   		Rr.RrSCtg= ins.RrSCtg and Rr.RrSTWGrp= '' and 
		Rr.RrCd= '' and Rr.RrDmCtg= '' and Rr.RrDmCd=ins.RrDmCd and  
		Rr.RrLsCtg= '' and Rr.RrLabMCd= '')
		and
  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and
   		Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and 
		Rt.RrCmCurCd= ins.RrCmCurCd and Rt.RrCtg= ins.RrCtg and
   		Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
		Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and 
		Rt.RrDmCd=ins.RrDmCd and Rt.RrRmKT=ins.RrRmKT  and 
		Rt.RrLsCtg= ins.RrLsCtg and Rt.RrLabMCd= ins.RrLabMCd
   		and  (    (Rt.RrFrLn<= ins.RrFrLn and
      			 Rt.RrToLn>= ins.RrFrLn)
		    or  	(Rt.RrFrLn<= ins.RrToLn and
		      	 Rt.RrToLn>= ins.RrToLn)
    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
			 ins.RrToLn>= Rt.RrToLn)
		 )
  		) > 1   
	if @row> 0
 	begin
  		select @errmsg= 'Size Range Already Defined'
  		goto ErrHndlr
 	end 


/****************************Geeta***Emr206********** 22/04/04**************/ 
IF @mode = 'D'
	begin	
		/************** Deletion not allowed if rec exists in RmRt  RrTcTyp='RM'**************/
		select @row=count('x') from deleted  del where RrTcTyp='BS'  and  
		exists(select * from RmRt Rr where Rr.RrTcTyp='RM' and 
			Rr.RrCmCtg= del.RrCmCtg and Rr.RrCmCd=del.RrCmCd and Rr.RrCtg=del.RrCtg and 
			Rr.RrSCtg= del.RrSCtg  and Rr.RrDmCtg=del.RrDmCtg and Rr.RrLabMCd=del.RrLabMCd 
			and Rr.RrLsCtg=del.RrLsCtg and Rr.RrRngSz=del.RrRngSz and 
			Rr.RrSTWGrp=del.RrSTWGrp and Rr.RrXWtPer=del.RrXWtPer and ((RrFrLn>rrToLn) or
	  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= Rr.RrTcTyp and
	   		Rt.RrCmCtg= Rr.RrCmCtg and Rt.RrCmCd= Rr.RrCmCd and 
			Rt.RrCmCurCd= Rr.RrCmCurCd and Rt.RrCtg= Rr.RrCtg and
	   		Rt.RrSCtg= Rr.RrSCtg and Rt.RrSTWGrp= Rr.RrSTWGrp and 
			Rt.RrCd= Rr.RrCd and Rt.RrDmCtg= Rr.RrDmCtg and Rt.RrDmCd=Rr.RrDmCd and 
			Rt.RrLsCtg= Rr.RrLsCtg and Rt.RrLabMCd= Rr.RrLabMCd
	   		and  ( (Rt.RrFrLn<= Rr.RrFrLn and
	      			Rt.RrToLn>= Rr.RrFrLn)
			    or  	(Rt.RrFrLn<= Rr.RrToLn and
			      	Rt.RrToLn>= Rr.RrToLn)
	    		    or  	(Rr.RrFrLn<= Rt.RrFrLn and
				Rr.RrToLn>= Rt.RrToLn)
			 )
	  		) > 1 ) ) 
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in RmRt '
	  		goto ErrHndlr
	 	end    
	 	
		/************** Deletion not allowed if rec exists in RmRtHist  RrTcTyp='RM'**************/
		select @row=count('x') from deleted  del where RrTcTyp='BS'  and  
		exists(select * from RmRtHist Rh where Rh.RhTcTyp='RM' and 
			Rh.RhCmCtg= del.RrCmCtg and Rh.RhCmCd=del.RrCmCd and Rh.RhCtg=del.RrCtg and 
			Rh.RhSCtg= del.RrSCtg  and  Rh.RhDmCtg=del.RrDmCtg and Rh.RhLabMCd=del.RrLabMCd and 
			Rh.RhLsCtg=del.RrLsCtg and Rh.RhRngSz=del.RrRngSz and Rh.RhSTWGrp=del.RrSTWGrp 
			and Rh.RhXWtPer=del.RrXWtPer and ((RhFrLn>RhToLn) or
	  		(Select count('x') from RmRtHist Rth where Rth.RhTcTyp= Rh.RhTcTyp and Rth.RhYyyymm= Rh.RhYyyyMm and
	   		Rth.RhCmCtg= Rh.RhCmCtg and Rth.RhCmCd= Rh.RhCmCd and 
			Rth.RhCmCurCd= Rh.RhCmCurCd and Rth.RhCtg= Rh.RhCtg and
	   		Rth.RhSCtg= Rh.RhSCtg and Rth.RhSTWGrp= Rh.RhSTWGrp and 
			Rth.RhCd= Rh.RhCd and Rth.RhDmCtg= Rh.RhDmCtg and 
			Rth.RhLsCtg= Rh.RhLsCtg and Rth.RhLabMCd= Rh.RhLabMCd
	   		and  ( (Rth.RhFrLn<= Rh.RhFrLn and
	      			Rth.RhToLn>= Rh.RhFrLn)
			    or  	(Rth.RhFrLn<= Rh.RhToLn and
			      	Rth.RhToLn>= Rh.RhToLn)
	    		    or  	(Rh.RhFrLn<= Rth.RhFrLn and
				Rh.RhToLn>= Rth.RhToLn)
			 )
	  		) > 1 ))
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in RmRtHist '
	  		goto ErrHndlr
	 	end 
	 	
	 	/************** Deletion not allowed if rec exists in LabRt  RrTcTyp='CHN'**************
	 		select @row=count('x') from deleted  del where RrTcTyp='CHN'  and  
		exists(select * from LabRt Lr where Lr.LrMCd = 'CHN' and Lr.LrSCd = 'CHN' and 
			Lr.LrCmCtg = del.RrCmCtg and Lr.LrCmCd = del.RrCmCd )
		if @row > 0
	 	begin
	  		select @errmsg= 'Cannot delete, Child records exist in LabRt '
	  		goto ErrHndlr
	 	end  ***/  
	end



	if @SYS= 'XEMR' 
	BEGIN

		/******  RrCmCtg  =  valid PMCd('CMCTG')  ******/
		select @row= count('x') from inserted where RrCmCtg not in ('C', 'P', 'S', 'T')
	 	if @row> 0
	 	Begin
	  		select @errmsg= 'Customer Catagory Should Be Either ''C'', ''P'', ''S'' or ''T'' '
	  		goto ErrHndlr
	 	end

		/******  RrCmCurCd  = if RrCmCd= 'ZSELF' then valid xPMCd from xParam  (where 
							xPTyp= 'CURNCY'  and xPSCd= '') 
				     Else if RrCmCd<> 'ZSELF' then Valid CmCurCd from CustMst (Where 
					CmCtg= RrCmCtg and CmCd= RrCmCd) *****/	
		Select @row= count('x') from inserted where RrTcTyp= 'RM' and 
				(     	(RrCmCd= 'ZSELF' and 
						not Exists(select 'x' from Param where 
						PTyp= 'CURNCY' and PMCd= RrCmCurCd) 
				      	)
				      	Or 
				      	(RrCmCd <> 'ZSELF' and 
						Not exists (select 'x' from CustMst where CmCtg= RrCmCtg 
						and CmCd= RrCmCd and CmCurCd= RrCmCurCd)
					)
				)
	 	if @row> 0
 		Begin
  			select @errmsg= 'Currency Code Not Defined'
	  		goto ErrHndlr
 		end
	
		/******  The Size Range should be unique  (i.e. it shouldn't overlap other size ranges for the same RrTcTyp, RrCmCd, RrCtg, RrSCtg, RrCd, 
			RrDmCtg, RrLabMCd combination)  ******/
/***		select @row= count('x') from inserted ins where 
  			IsNull((Select PValue from Param where PTyp= 'RMSCTG' and 
                	        	PMCd= RrCtg and PSCd= RrSCtg), '') <> 'BS' and 
	  		(Select count('x') from RmRt Rt where Rt.RrTcTyp= ins.RrTcTyp and 
   			Rt.RrCmCtg= ins.RrCmCtg and Rt.RrCmCd= ins.RrCmCd and Rt.RrCmCurCd= ins.RrCmCurCd and 
			Rt.RrCtg= ins.RrCtg and Rt.RrSCtg= ins.RrSCtg and Rt.RrSTWGrp= ins.RrSTWGrp and 
			Rt.RrCd= ins.RrCd and Rt.RrDmCtg= ins.RrDmCtg and Rt.RrLsCtg= ins.RrLsCtg and 
			Rt.RrLabMCd= ins.RrLabMCd 
   			and  (    (Rt.RrFrLn<= ins.RrFrLn and
	      			 Rt.RrToLn>= ins.RrFrLn)
			    or  	(Rt.RrFrLn<= ins.RrToLn and
			      	 Rt.RrToLn>= ins.RrToLn)
	    		    or  	(ins.RrFrLn<= Rt.RrFrLn and
				 ins.RrToLn>= Rt.RrToLn)
			 )
	  		) > 1
		if @row> 0
	 	Begin
  			select @errmsg= 'Size Range Already Defined'
  			goto ErrHndlr
	 	end
***/
	END



return
ErrHndlr:
	begin
  		select @errmsg='|'+@errmsg
  		raiserror(@errmsg,16,1)
  		rollback transaction
 	end
end
GOGO
IF EXISTS (SELECT * FROM sysobjects WHERE type = 'P' AND name = 'ForCpy_GetRmRt_IPD')
    BEGIN
        DROP  Procedure ForCpy_GetRmRt_IPD
    END
 GoGO
 
create Procedure [dbo].[ForCpy_GetRmRt_IPD] 
	(@mCmCd varchar(8), @mRmCd varchar(16), @mLn1 decimal(8,3), @mLn2 decimal(8,3), 
    @mWtPerDia decimal(8,3), @mOpt As varchar(1), @mLme decimal(10,3), @mCmCtg As char(1)='C',
    @mHistCmCtg char(1) ='', @mHistCmCd varchar(8)='', @mHistYyyyMm decimal(8,0),                         
    @mCmCurCd varchar(8), @mCmLkUpRmRt varchar(8), @mPrtKey char(1), @mRt as decimal(10,3) out)
as
begin

declare @wRmRt as decimal(10,3)
Declare @wRmCtg varchar(2), @wRmSCtg varchar(5)
Declare @ctselfcocd varchar(8)
declare @ctselfcmcd varchar(8)
declare @ErrMsg varchar(500)
Declare @wRtBy varchar(2), @wRt varchar(10), @wInc decimal(10,4), @wCnd varchar(100), @wRtByForCostRt As char(1),
  @wRtChrtByPtr varchar(2), @wRtChrtByBs varchar(2), @wcndForCostRt varchar(100),
  @wCmSeekZSelfRt bit,  @wInp decimal(5,3),  @wFrLn varchar(8), @wToLn varchar(10)
declare @wCommand nvarchar(max)
declare @mBaseLMEfromRM decimal(10,3)
  
  SELECT @ctselfcocd='ZZZ'
  SELECT @ctSelfCmCd= 'ZSELF'

exec [ForCpy_GetRmRt_Base] 
	@mCmCd , @mRmCd , @mLn1 , @mLn2 , 
    @mWtPerDia , @mOpt , @mLme , @mCmCtg ,
    @mHistCmCtg , @mHistCmCd , @mHistYyyyMm ,                         
    @mCmCurCd , @mCmLkUpRmRt , @mPrtKey , @mBaseLMEfromRM  out

SELECT @mBaseLMEfromRM 

  Select @mLn1 = 0
  Select @mLn2=9999.9999
  If (@mOpt <> 'C') And (@mOpt <> 'S') 
	select 0

  If (@mCmCtg <> 'C') And (@mCmCtg <> 'S') 
	select 0

  If @mCmCurCd='' 
  begin
	select @mCmCurCd = CmCurCd from CustMst where CmCtg= @mCmCtg  and CmCd= @mCmCd 
  end
  --6.1-13 seek from custmst is removed  
  --If @mCmLkUpRmRt = '' 
  --begin
  --  select @mCmLkUpRmRt = CmLkUpRmRt from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd
  --End
   
  select @wCmSeekZSelfRt = 1 where exists (Select 'x' from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd and CmSeekZSelfRt='Y')
  
  select @wRmCtg = RmCtg ,@wRmSctg=RmSctg from RmMst where RMCd=@mRmCd 
--  If @wRmCtg = 'G' Or @wRmCtg = 'P' Or @wRmCtg = 'S' Or @wRmCtg = 'L' select 0

  declare @ws_RndOff As char(1)
  select @ws_RndOff = (select case when exists((Select 'x' from Head  Join Param on PTyp='CPYRT' and PMCd=HOrdRtRndOffRmCtg Where HCoCd=@ctselfcocd 
											and hCd=@ctSelfCmCd and ','+PDesc225+',' like '%,' + @wRmCtg + ',%' )) then  0 else 3 end)
  
    
  If(@mHistCmCtg IS NULL OR @mHistCmCtg = '') Or @mHistCmCtg <> 'P' 
  begin
    select @wRtChrtByPtr = 'P'  from RmRt where RrTcTyp= 'PTR' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and 
                 RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0 
	select @wRtChrtByPtr =isnull(@wRtChrtByPtr,'')
	

    select @wRmCtg
	select @wRmSctg
	select @wRtChrtByBs = 'BS' from RmRt where RrTcTyp= 'BS' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0

	
	select @wRtChrtByBs =isnull(@wRtChrtByBs ,'')
  End	

  select @wRtBy = PValue from Param where PTyp= 'RMSCTG' and PMCd= @wRmCtg and PSCd= @wRmSCtg  
  select @wRtByForCostRt = @wRtBy	
  
  If @wRtChrtByPtr <> '' 
    select @wRtBy = @wRtChrtByPtr
  Else
	If @wRtChrtByBs <> '' 
		select @wRtBy = @wRtChrtByBs
 

  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
    select @wRt = case when @mOpt = 'S' then 'RrSalRt' else 'RrCstRt' end
  Else
    select @wRt = case when @mOpt = 'S' then 'RhSalRt' else 'RhCstRt' end

  If @mCmCtg = 'S' And @mOpt = 'C' select @mCmCtg = 'C'


  If @mOpt ='S' 
	begin
    select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg  and RrCmCd= @mCmCd 
    If(@wInc IS NULL OR @wInc = 0)	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg  and RrSCtg= ''  and RrCmCd= @mCmCd
    If(@wInc IS NULL OR @wInc = 0)	 
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrCmCd= @ctSelfCmCd 
	If(@wInc IS NULL OR @wInc = 0)	 	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and            
           RrCtg= @wRmCtg and RrSCtg='' and RrCmCd= @ctSelfCmCd 
	If @wInc IS NULL 
		select @wInc = 0	
	end 
  Else
    select @wInc = 0

  If @mOpt = 'S' 
	begin
    select @wInp= RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg=@wRmCtg and RrSCtg= @wRmSCtg and RrCmCd=@mCmLkUpRmRt 
    If(@wInp IS NULL OR @wInp = 0)	
      select @wInp =RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg= @wRmCtg and RrSCtg= ''  and RrCmCd= @mCmLkUpRmRt 
	If @wInp IS NULL 
		select @wInp = 0
	end  
  Else
    select @wInp = 0

  
  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
	begin
		select @wFrLn = 'RrFrLn'
		select @wToLn = 'RrToLn'
	end
  Else
	begin
		select @wFrLn = 'RhFrLn'
		select @wToLn = 'RhToLn'
	End

  if @wRtBy='S' 
	begin
		If @wRmCtg = 'X'  select @mLn1 = @mLme
		select @wCnd ='  Round(' + @wFrLn+ ', 4) <= Round(' + convert(varchar,@mLn1) + ' , 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ' , 3) and '    
	end
  else if @wRtBy ='W' or @wRtBy='P' 
	select @wCnd =' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtBy = 'BS'   
	select @wCnd = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) = Round(' + + convert(varchar,@mLn2) + ', 3) and '
  else
	select @wCnd =' '    
	
  if @wRtByForCostRt='S'
	begin
		If @wRmCtg = 'X' select @mLn1 = @mLme
		select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ', 3) and '
	end
  else if @wRtByForCostRt in ('W', 'P')
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtByForCostRt = 'BS'
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn +', 4) = Round(' + convert(varchar,@mLn2) + ', 3) and '
  else 
	select @wcndForCostRt = ' '

  Declare @wAccessoriesRmIncFac varchar(max)
  SELECT @WRTCHRTBYPTR
  SELECT @WRTCHRTBYBS 

  If (@wRtChrtByPtr = '' And @wRtChrtByBs = '' ) 
  begin	
	If(@mHistCmCtg <> '')	
	begin
		Select @wCommand='Select 
						         @wRmRt= isnull((Select ' + @wRt + ' from RmRtHist where ' +
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''IPD'' and ' +
								  'RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' +  @wRmSCtg + '''  and  ' + 
								  'RhCd=''' + @mRmCd + ''' and '+ @wCnd +'RhCmCtg=''' + @mHistCmCtg + ''' and ' + 
								  'RhCmCd=''' + @mHistCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and '+ '1'+' = 1),' + 					  
								  case when(@wCmSeekZSelfRt = 1 Or @mOpt = 'C') then 
								  'Convert(Decimal(14,' +case when @wInc = 0 then '3' else @ws_RndOff end + '),' +
								  'IsNull((Select ' +@wRt + ' from RmRtHist where ' + 
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''IPD'' and  
								  RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and  
								  RhCd=''' + @mRmCd + ''' and ' + @wCnd +' RhCmCtg= ''C'' and RhCmCd =''' + @ctSelfCmCd + ''' and 
								  RhCmCurCd=''' + @mCmCurCd + ''' and ' + 
								  '1'  + ' = 1)*(1 +' + convert(varchar,@wInc) + ' / 100) ,0))' else '0' end + ')' 
	end
	Else
	begin	  
/*		select @wAccessoriesRmIncFac =										
										'(case when ''' + @wRmCtg + ''' = ''X'' then ((' + convert(varchar,@mLme) + '-RrFrLn) * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol end)  ) else 0 end) '*/
										
		select @wAccessoriesRmIncFac =										
										'(case when ''' + '1' + ''' = ''1'' then ((' + convert(varchar,@mLme) + '-'+convert(varchar,@mBaseLMEfromRM)+') * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol  end)  ) else 0 end) '
																									         
		select @wCommand='Select @wRmRt=' + 
			     'isnull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''IPD'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
				 RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg= ''P'' and RrCmCd ='''+  @mCmLkUpRmRt + ''' and 
				 RrCmCurCd=''' + @mCmCurCd + ''' and ' +'1' +  '= 1)* (1 + '  + convert(varchar,@wInp) + ' / 100) ,  ' +					 				 
                 'isnull((Select ' + @wRt  + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''IPD'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and  
                 RrCd=''' + @mRmCd + ''' and '+@wCnd + ' RrCmCtg=''' +  @mCmCtg + ''' and 
                 RrCmCd =''' + @mCmCd + ''' and RrCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1) ,' + 
                 ' ' + (case when @wCmSeekZSelfRt =1 Or @mOpt = 'C' 
				 then 'Convert(Decimal(14, '+ case when @wInc = 0 then '3' else @ws_RndOff end +'),' 
				 +'IsNull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac +					
                 ' from RmRt where RrTcTyp= ''IPD'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
                 RrCd=''' + @mRmCd + ''' and '+ @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and 
                 RrCmCd =''' + @ctSelfCmCd + ''' and RrCmCurCd=''' +  @mCmCurCd + ''' and '                                    
                 +'1' + ' = 1)*(1 +'  + convert(varchar, @wInc) + ' / 100) , 0))'  else '0' END )+ '))'
	End
  End
  Else If (@wRtChrtByPtr = 'P' Or @wRtChrtByBs = 'BS')
  begin	
    If(@mHistCmCtg <> '')
    begin
      If (@mOpt = 'C')	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist  
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''IPD'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wcndForCostRt + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @ctSelfCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1'
      Else	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist 
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''IPD'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wCnd + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @mCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1'
	End
	else
  
	begin
    If (@mOpt = 'C') 
      select @wCommand='select @wRmRt=isnull((Select  '+ @wRt + ' from RmRt where RrTcTyp=''IPD'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg='''+ @wRmSCtg +''' and 
                RrCd='''+ @mRmCd +''' and '+ @wCnd + ' RrCmCtg='''+ @mCmCtg +''' and 
                RrCmCd ='''+ @mCmCd +''' and RrCmCurCd='''+ @mCmCurCd +''' and ' +'1'+ ' = 1),
                isnull((Select ' + @wRt + ' from RmRt where RrTcTyp= ''IPD'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg=''' + @wRmSCtg +''' and 
				RrCd='''+ @mRmCd +''' and ' + @wcndForCostRt + ' RrCmCtg='''+ @mCmCtg +''' and RrCmCd ='''+ @ctSelfCmCd +''' and 
				RrCmCurCd='''+ @mCmCurCd +''' and '+ '1' + ' = 1),0))'
    Else				
     select @wCommand='Select @wRmRt= '+ @wRt +' from RmRt where RrTcTyp= ''IPD'' and 
              RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
              RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and RrCmCd =''' + @mCmCd + ''' and 
              RrCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1 '               
    End
  
  end
  select 'Command:'+isnull(@wCommand ,'')
  BEGIN TRY

  exec sp_executesql @wcommand,
						N'@mCmCd varchar(8), 
						@mRmCd varchar(16), 
                        @mLn1 decimal(8,3), 
						@mLn2 decimal(8,3), 
                        @mWtPerDia decimal(8,3), 
					    @mOpt As varchar(1),                         
					    @mLme decimal(10,3), 
						@mCmCtg As char(1),
                        @mHistCmCtg char(1) , 
						@mHistCmCd varchar(8),
                        @mHistYyyyMm decimal(8,0),                         
						@mCmCurCd varchar(8), 
                        @mCmLkUpRmRt varchar(8),                         
						@mPrtKey char(1),						
						@wRmCtg char(2),
						@wRmSCtg varchar(5),
						@wInp decimal(5,3),  
						@wRmRt decimal(10,3) output'
						,@mCmCd =@mCmCd, 
						@mRmCd =@mRmCd, 
                        @mLn1 =@mLn1, 
						@mLn2 =@mLn2, 
						@mWtPerDia =@mWtPerDia, 
						@mOpt =@mOpt,                         
						@mLme =@mLme, 
						@mCmCtg =@mCmCtg,
                        @mHistCmCtg =@mHistCmCtg, 
						@mHistCmCd =@mHistCmCd,
                        @mHistYyyyMm =@mHistYyyyMm,                         
						@mCmCurCd =@mCmCurCd, 
                        @mCmLkUpRmRt =@mCmLkuPRmRt,                         
						@mPrtKey =@mPrtKey,
						@wRmCtg=@wRmCtg,
						@wRmSCtg=@wRmSCtg,
						@wInp=@wInp,
						@wRmRt=@wRmRt output
						END TRY
						BEGIN CATCH
						 SELECT ERROR_NUMBER() AS ErrorNumber
         ,ERROR_SEVERITY() AS ErrorSeverity
         ,ERROR_STATE() AS ErrorState
         ,ERROR_PROCEDURE() AS ErrorProcedure
         ,ERROR_LINE() AS ErrorLine
         ,ERROR_MESSAGE() AS ErrorMessage
         END CATCH

Select @mrt= isnull(@wrmrt ,0)
RETURN @mrt
END
GOGO
IF EXISTS (SELECT * FROM sysobjects WHERE type = 'P' AND name = 'ForCpy_GetRmRt_IPD')
    BEGIN
        DROP  Procedure ForCpy_GetRmRt_IPD
    END
 GoGO

Create Procedure [dbo].[ForCpy_GetRmRt_IPD] 
	(@mCmCd varchar(8), @mRmCd varchar(16), @mLn1 decimal(8,3), @mLn2 decimal(8,3), 
    @mWtPerDia decimal(8,3), @mOpt As varchar(1), @mLme decimal(10,3), @mCmCtg As char(1)='C',
    @mHistCmCtg char(1) ='', @mHistCmCd varchar(8)='', @mHistYyyyMm decimal(8,0),                         
    @mCmCurCd varchar(8), @mCmLkUpRmRt varchar(8), @mPrtKey char(1), @mRt as decimal(10,3) out)
as
begin

declare @wRmRt as decimal(10,3)
Declare @wRmCtg varchar(2), @wRmSCtg varchar(5)
Declare @ctselfcocd varchar(8)
declare @ctselfcmcd varchar(8)
declare @ErrMsg varchar(500)
Declare @wRtBy varchar(2), @wRt varchar(10), @wInc decimal(10,4), @wCnd varchar(100), @wRtByForCostRt As char(1),
  @wRtChrtByPtr varchar(2), @wRtChrtByBs varchar(2), @wcndForCostRt varchar(100),
  @wCmSeekZSelfRt bit,  @wInp decimal(5,3),  @wFrLn varchar(8), @wToLn varchar(10)
declare @wCommand nvarchar(max)
declare @mBaseLMEfromRM decimal(10,3)
  
  SELECT @ctselfcocd='ZZZ'
  SELECT @ctSelfCmCd= 'ZSELF'

exec [ForCpy_GetRmRt_Base] 
	@mCmCd , @mRmCd , @mLn1 , @mLn2 , 
    @mWtPerDia , @mOpt , @mLme , @mCmCtg ,
    @mHistCmCtg , @mHistCmCd , @mHistYyyyMm ,                         
    @mCmCurCd , @mCmLkUpRmRt , @mPrtKey , @mBaseLMEfromRM  out

SELECT @mBaseLMEfromRM 

  Select @mLn1 = 0
  Select @mLn2=0
  If (@mOpt <> 'C') And (@mOpt <> 'S') 
	select 0

  If (@mCmCtg <> 'C') And (@mCmCtg <> 'S') 
	select 0

  If @mCmCurCd='' 
  begin
	select @mCmCurCd = CmCurCd from CustMst where CmCtg= @mCmCtg  and CmCd= @mCmCd 
  end
  --6.1-13 seek from custmst is removed  
  --If @mCmLkUpRmRt = '' 
  --begin
  --  select @mCmLkUpRmRt = CmLkUpRmRt from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd
  --End
   
  select @wCmSeekZSelfRt = 1 where exists (Select 'x' from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd and CmSeekZSelfRt='Y')
  
  select @wRmCtg = RmCtg ,@wRmSctg=RmSctg from RmMst where RMCd=@mRmCd 
--  If @wRmCtg = 'G' Or @wRmCtg = 'P' Or @wRmCtg = 'S' Or @wRmCtg = 'L' select 0

  declare @ws_RndOff As char(1)
  select @ws_RndOff = (select case when exists((Select 'x' from Head  Join Param on PTyp='CPYRT' and PMCd=HOrdRtRndOffRmCtg Where HCoCd=@ctselfcocd 
											and hCd=@ctSelfCmCd and ','+PDesc225+',' like '%,' + @wRmCtg + ',%' )) then  0 else 3 end)
  
    
  If(@mHistCmCtg IS NULL OR @mHistCmCtg = '') Or @mHistCmCtg <> 'P' 
  begin
    select @wRtChrtByPtr = 'P'  from RmRt where RrTcTyp= 'PTR' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and 
                 RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0 
	select @wRtChrtByPtr =isnull(@wRtChrtByPtr,'')
	

    select @wRmCtg
	select @wRmSctg
	select @wRtChrtByBs = 'BS' from RmRt where RrTcTyp= 'BS' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0

	
	select @wRtChrtByBs =isnull(@wRtChrtByBs ,'')
  End	

  select @wRtBy = PValue from Param where PTyp= 'RMSCTG' and PMCd= @wRmCtg and PSCd= @wRmSCtg  
  select @wRtByForCostRt = @wRtBy	
  
  If @wRtChrtByPtr <> '' 
    select @wRtBy = @wRtChrtByPtr
  Else
	If @wRtChrtByBs <> '' 
		select @wRtBy = @wRtChrtByBs
 

  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
    select @wRt = case when @mOpt = 'S' then 'RrSalRt' else 'RrCstRt' end
  Else
    select @wRt = case when @mOpt = 'S' then 'RhSalRt' else 'RhCstRt' end

  If @mCmCtg = 'S' And @mOpt = 'C' select @mCmCtg = 'C'


  If @mOpt ='S' 
	begin
    select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg  and RrCmCd= @mCmCd 
    If(@wInc IS NULL OR @wInc = 0)	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg  and RrSCtg= ''  and RrCmCd= @mCmCd
    If(@wInc IS NULL OR @wInc = 0)	 
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrCmCd= @ctSelfCmCd 
	If(@wInc IS NULL OR @wInc = 0)	 	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and            
           RrCtg= @wRmCtg and RrSCtg='' and RrCmCd= @ctSelfCmCd 
	If @wInc IS NULL 
		select @wInc = 0	
	end 
  Else
    select @wInc = 0

  If @mOpt = 'S' 
	begin
    select @wInp= RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg=@wRmCtg and RrSCtg= @wRmSCtg and RrCmCd=@mCmLkUpRmRt 
    If(@wInp IS NULL OR @wInp = 0)	
      select @wInp =RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg= @wRmCtg and RrSCtg= ''  and RrCmCd= @mCmLkUpRmRt 
	If @wInp IS NULL 
		select @wInp = 0
	end  
  Else
    select @wInp = 0

  
  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
	begin
		select @wFrLn = 'RrFrLn'
		select @wToLn = 'RrToLn'
	end
  Else
	begin
		select @wFrLn = 'RhFrLn'
		select @wToLn = 'RhToLn'
	End

  if @wRtBy='S' 
	begin
		--If @wRmCtg = 'X'  select @mLn1 = @mLme
		select @wCnd ='  Round(' + @wFrLn+ ', 4) <= Round(' + convert(varchar,@mLn1) + ' , 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ' , 3) and '    
	end
  else if @wRtBy ='W' or @wRtBy='P' 
	select @wCnd =' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtBy = 'BS'   
--	select @wCnd = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) = Round(' + + convert(varchar,@mLn2) + ', 3) and '
			select @wCnd ='  Round(' + @wFrLn+ ', 4) <= Round(' + convert(varchar,@mLn1) + ' , 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ' , 3) and '    

  else
	select @wCnd =' '    
	
  if @wRtByForCostRt='S'
	begin
		--If @wRmCtg = 'X' select @mLn1 = @mLme
		select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ', 3) and '
	end
  else if @wRtByForCostRt in ('W', 'P')
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtByForCostRt = 'BS'
--    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn +', 4) = Round(' + convert(varchar,@mLn2) + ', 3) and '
		select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ', 3) and '
    
  else 
	select @wcndForCostRt = ' '

  Declare @wAccessoriesRmIncFac varchar(max)
  SELECT @WRTCHRTBYPTR
  SELECT @WRTCHRTBYBS 

  If (@wRtChrtByPtr = '' And @wRtChrtByBs = '' ) 
  begin	
	If(@mHistCmCtg <> '')	
	begin
		Select @wCommand='Select 
						         @wRmRt= isnull((Select ' + @wRt + ' from RmRtHist where ' +
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''IPD'' and ' +
								  'RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' +  @wRmSCtg + '''  and  ' + 
								  'RhCd=''' + @mRmCd + ''' and '+ @wCnd +'RhCmCtg=''' + @mHistCmCtg + ''' and ' + 
								  'RhCmCd=''' + @mHistCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and '+ '1'+' = 1),' + 					  
								  case when(@wCmSeekZSelfRt = 1 Or @mOpt = 'C') then 
								  'Convert(Decimal(14,' +case when @wInc = 0 then '3' else @ws_RndOff end + '),' +
								  'IsNull((Select ' +@wRt + ' from RmRtHist where ' + 
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''IPD'' and  
								  RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and  
								  RhCd=''' + @mRmCd + ''' and ' + @wCnd +' RhCmCtg= ''C'' and RhCmCd =''' + @ctSelfCmCd + ''' and 
								  RhCmCurCd=''' + @mCmCurCd + ''' and ' + 
								  '1'  + ' = 1)*(1 +' + convert(varchar,@wInc) + ' / 100) ,0))' else '0' end + ')' 
	end
	Else
	begin	  
/*		select @wAccessoriesRmIncFac =										
										'(case when ''' + @wRmCtg + ''' = ''X'' then ((' + convert(varchar,@mLme) + '-RrFrLn) * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol end)  ) else 0 end) '*/
										
		select @wAccessoriesRmIncFac =										
										'(case when ''' + '1' + ''' = ''1'' then ((' + convert(varchar,@mLme) + '-'+convert(varchar,@mBaseLMEfromRM)+') * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol  end)  ) else 0 end) '
																									         
		select @wCommand='Select @wRmRt=' + 
			     'isnull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''IPD'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
				 RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg= ''P'' and RrCmCd ='''+  @mCmLkUpRmRt + ''' and 
				 RrCmCurCd=''' + @mCmCurCd + ''' and ' +'1' +  '= 1)* (1 + '  + convert(varchar,@wInp) + ' / 100) ,  ' +					 				 
                 'isnull((Select ' + @wRt  + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''IPD'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and  
                 RrCd=''' + @mRmCd + ''' and '+@wCnd + ' RrCmCtg=''' +  @mCmCtg + ''' and 
                 RrCmCd =''' + @mCmCd + ''' and RrCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1) ,' + 
                 ' ' + (case when @wCmSeekZSelfRt =1 Or @mOpt = 'C' 
				 then 'Convert(Decimal(14, '+ case when @wInc = 0 then '3' else @ws_RndOff end +'),' 
				 +'IsNull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac +					
                 ' from RmRt where RrTcTyp= ''IPD'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
                 RrCd=''' + @mRmCd + ''' and '+ @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and 
                 RrCmCd =''' + @ctSelfCmCd + ''' and RrCmCurCd=''' +  @mCmCurCd + ''' and '                                    
                 +'1' + ' = 1)*(1 +'  + convert(varchar, @wInc) + ' / 100) , 0))'  else '0' END )+ '))'
	End
  End
  Else If (@wRtChrtByPtr = 'P' Or @wRtChrtByBs = 'BS')
  begin	
    If(@mHistCmCtg <> '')
    begin
      If (@mOpt = 'C')	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist  
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''IPD'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wcndForCostRt + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @ctSelfCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1'
      Else	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist 
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''IPD'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wCnd + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @mCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1'
	End
	else
  
	begin
		select @wAccessoriesRmIncFac =										
										'(case when ''' + '1' + ''' = ''1'' then ((' + convert(varchar,@mLme) + '-'+convert(varchar,@mBaseLMEfromRM)+') * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol  end)  ) else 0 end) '
	
    If (@mOpt = 'C') 
      select @wCommand='select @wRmRt=isnull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac +  ' from RmRt where RrTcTyp=''IPD'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg='''+ @wRmSCtg +''' and 
                RrCd='''+ @mRmCd +''' and '+ @wCnd + ' RrCmCtg='''+ @mCmCtg +''' and 
                RrCmCd ='''+ @mCmCd +''' and RrCmCurCd='''+ @mCmCurCd +''' and ' +'1'+ ' = 1),
                isnull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac + ' from RmRt where RrTcTyp= ''IPD'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg=''' + @wRmSCtg +''' and 
				RrCd='''+ @mRmCd +''' and ' + @wcndForCostRt + ' RrCmCtg='''+ @mCmCtg +''' and RrCmCd ='''+ @ctSelfCmCd +''' and 
				RrCmCurCd='''+ @mCmCurCd +''' and '+ '1' + ' = 1),0))'
    Else				
     select @wCommand='Select @wRmRt= '+ @wRt + '+' + @wAccessoriesRmIncFac +' from RmRt where RrTcTyp= ''IPD'' and 
              RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
              RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and RrCmCd =''' + @mCmCd + ''' and 
              RrCmCurCd=''' + @mCmCurCd + ''' and ' + '1' + ' = 1 '               
    End
  
  end
  select 'Command:'+isnull(@wCommand ,'')
  BEGIN TRY

  exec sp_executesql @wcommand,
						N'@mCmCd varchar(8), 
						@mRmCd varchar(16), 
                        @mLn1 decimal(8,3), 
						@mLn2 decimal(8,3), 
                        @mWtPerDia decimal(8,3), 
					    @mOpt As varchar(1),                         
					    @mLme decimal(10,3), 
						@mCmCtg As char(1),
                        @mHistCmCtg char(1) , 
						@mHistCmCd varchar(8),
                        @mHistYyyyMm decimal(8,0),                         
						@mCmCurCd varchar(8), 
                        @mCmLkUpRmRt varchar(8),                         
						@mPrtKey char(1),						
						@wRmCtg char(2),
						@wRmSCtg varchar(5),
						@wInp decimal(5,3),  
						@wRmRt decimal(10,3) output'
						,@mCmCd =@mCmCd, 
						@mRmCd =@mRmCd, 
                        @mLn1 =@mLn1, 
						@mLn2 =@mLn2, 
						@mWtPerDia =@mWtPerDia, 
						@mOpt =@mOpt,                         
						@mLme =@mLme, 
						@mCmCtg =@mCmCtg,
                        @mHistCmCtg =@mHistCmCtg, 
						@mHistCmCd =@mHistCmCd,
                        @mHistYyyyMm =@mHistYyyyMm,                         
						@mCmCurCd =@mCmCurCd, 
                        @mCmLkUpRmRt =@mCmLkuPRmRt,                         
						@mPrtKey =@mPrtKey,
						@wRmCtg=@wRmCtg,
						@wRmSCtg=@wRmSCtg,
						@wInp=@wInp,
						@wRmRt=@wRmRt output
						END TRY
						BEGIN CATCH
						 SELECT ERROR_NUMBER() AS ErrorNumber
         ,ERROR_SEVERITY() AS ErrorSeverity
         ,ERROR_STATE() AS ErrorState
         ,ERROR_PROCEDURE() AS ErrorProcedure
         ,ERROR_LINE() AS ErrorLine
         ,ERROR_MESSAGE() AS ErrorMessage
         END CATCH

Select @mrt= isnull(@wrmrt ,0)
RETURN @mrt
END

GOGO

IF EXISTS (SELECT * FROM sysobjects WHERE type = 'P' AND name = 'ForCpy_GetRmRt_Base')
    BEGIN
        DROP  Procedure ForCpy_GetRmRt_Base
    END
 GoGO

create Procedure [dbo].[ForCpy_GetRmRt_Base] 
	(@mCmCd varchar(8), @mRmCd varchar(16), @mLn1 decimal(8,3), @mLn2 decimal(8,3), 
    @mWtPerDia decimal(8,3), @mOpt As varchar(1), @mLme decimal(10,3), @mCmCtg As char(1)='C',
    @mHistCmCtg char(1) ='', @mHistCmCd varchar(8)='', @mHistYyyyMm decimal(8,0),                         
    @mCmCurCd varchar(8), @mCmLkUpRmRt varchar(8), @mPrtKey char(1), @mRt as decimal(10,3) out)
as
begin

declare @wRmRt as decimal(10,3)
Declare @wRmCtg varchar(2), @wRmSCtg varchar(5)
Declare @ctselfcocd varchar(8)
declare @ctselfcmcd varchar(8)
declare @ErrMsg varchar(500)
Declare @wRtBy varchar(2), @wRt varchar(10), @wInc decimal(10,4), @wCnd varchar(100), @wRtByForCostRt As char(1),
  @wRtChrtByPtr varchar(2), @wRtChrtByBs varchar(2), @wcndForCostRt varchar(100),
  @wCmSeekZSelfRt bit,  @wInp decimal(5,3),  @wFrLn varchar(8), @wToLn varchar(10)
declare @wCommand nvarchar(max)
  
  SELECT @ctselfcocd='ZZZ'
  SELECT @ctSelfCmCd= 'ZSELF'

  If (@mOpt <> 'C') And (@mOpt <> 'S') 
	select 0

  If (@mCmCtg <> 'C') And (@mCmCtg <> 'S') 
	select 0

  If @mCmCurCd='' 
  begin
	select @mCmCurCd = CmCurCd from CustMst where CmCtg= @mCmCtg  and CmCd= @mCmCd 
  end
  --6.1-13 seek from custmst is removed  
  --If @mCmLkUpRmRt = '' 
  --begin
  --  select @mCmLkUpRmRt = CmLkUpRmRt from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd
  --End
   
  select @wCmSeekZSelfRt = 1 where exists (Select 'x' from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd and CmSeekZSelfRt='Y')
  
  select @wRmCtg = RmCtg ,@wRmSctg=RmSctg from RmMst where RMCd=@mRmCd 
--  If @wRmCtg = 'G' Or @wRmCtg = 'P' Or @wRmCtg = 'S' Or @wRmCtg = 'L' select 0

  declare @ws_RndOff As char(1)
  select @ws_RndOff = (select case when exists((Select 'x' from Head  Join Param on PTyp='CPYRT' and PMCd=HOrdRtRndOffRmCtg Where HCoCd=@ctselfcocd 
											and hCd=@ctSelfCmCd and ','+PDesc225+',' like '%,' + @wRmCtg + ',%' )) then  0 else 3 end)
  
    
  If(@mHistCmCtg IS NULL OR @mHistCmCtg = '') Or @mHistCmCtg <> 'P' 
  begin
    select @wRtChrtByPtr = 'P'  from RmRt where RrTcTyp= 'PTR' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and 
                 RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0 
	select @wRtChrtByPtr =isnull(@wRtChrtByPtr,'')
	

    select @wRmCtg
	select @wRmSctg
	select @wRtChrtByBs = 'BS' from RmRt where RrTcTyp= 'BS' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0

	
	select @wRtChrtByBs =isnull(@wRtChrtByBs ,'')
  End	

  select @wRtBy = PValue from Param where PTyp= 'RMSCTG' and PMCd= @wRmCtg and PSCd= @wRmSCtg  
  select @wRtByForCostRt = @wRtBy	
  
  If @wRtChrtByPtr <> '' 
    select @wRtBy = @wRtChrtByPtr
  Else
	If @wRtChrtByBs <> '' 
		select @wRtBy = @wRtChrtByBs
 

  select @wRt = 'RrXWtPer'
   
  
  If @mCmCtg = 'S' And @mOpt = 'C' select @mCmCtg = 'C'


  If @mOpt ='S' 
	begin
    select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg  and RrCmCd= @mCmCd 
    If(@wInc IS NULL OR @wInc = 0)	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg  and RrSCtg= ''  and RrCmCd= @mCmCd
    If(@wInc IS NULL OR @wInc = 0)	 
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrCmCd= @ctSelfCmCd 
	If(@wInc IS NULL OR @wInc = 0)	 	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and            
           RrCtg= @wRmCtg and RrSCtg='' and RrCmCd= @ctSelfCmCd 
	If @wInc IS NULL 
		select @wInc = 0	
	end 
  Else
    select @wInc = 0

  If @mOpt = 'S' 
	begin
    select @wInp= RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg=@wRmCtg and RrSCtg= @wRmSCtg and RrCmCd=@mCmLkUpRmRt 
    If(@wInp IS NULL OR @wInp = 0)	
      select @wInp =RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg= @wRmCtg and RrSCtg= ''  and RrCmCd= @mCmLkUpRmRt 
	If @wInp IS NULL 
		select @wInp = 0
	end  
  Else
    select @wInp = 0

  
  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
	begin
		select @wFrLn = 'RrFrLn'
		select @wToLn = 'RrToLn'
	end
  Else
	begin
		select @wFrLn = 'RhFrLn'
		select @wToLn = 'RhToLn'
	End

  if @wRtBy='S' 
	begin
		If @wRmCtg = 'sri'  select @mLn1 = @mLme
		select @wCnd ='  Round(' + @wFrLn+ ', 4) <= Round(' + convert(varchar,@mLn1) + ' , 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ' , 3) and '    
	end
  else if @wRtBy ='W' or @wRtBy='P' 
	select @wCnd =' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtBy = 'BS'   
	select @wCnd = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) = Round(' + + convert(varchar,@mLn2) + ', 3) and '
  else
	select @wCnd =' '    
	
  if @wRtByForCostRt='S'
	begin
		If @wRmCtg = 'sri' select @mLn1 = @mLme
		select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ', 3) and '
	end
  else if @wRtByForCostRt in ('W', 'P')
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtByForCostRt = 'BS'
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn +', 4) = Round(' + convert(varchar,@mLn2) + ', 3) and '
  else 
	select @wcndForCostRt = ' '

  Declare @wAccessoriesRmIncFac varchar(max)
  SELECT @WRTCHRTBYPTR
  SELECT @WRTCHRTBYBS 

  If (@wRtChrtByPtr = '' And @wRtChrtByBs = '' ) 
  begin	
	If(@mHistCmCtg <> '')	
	begin
		Select @wCommand='Select 
						         @wRmRt= isnull((Select ' + @wRt + ' from RmRtHist where ' +
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''RM'' and ' +
								  'RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' +  @wRmSCtg + '''  and  ' + 
								  'RhCd=''' + @mRmCd + ''' and '+ @wCnd +'RhCmCtg=''' + @mHistCmCtg + ''' and ' + 
								  'RhCmCd=''' + @mHistCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and '+ @wRt+' <> 0),' + 					  
								  case when(@wCmSeekZSelfRt = 1 Or @mOpt = 'C') then 
								  'Convert(Decimal(14,' +case when @wInc = 0 then '3' else @ws_RndOff end + '),' +
								  'IsNull((Select ' +@wRt + ' from RmRtHist where ' + 
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''RM'' and  
								  RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and  
								  RhCd=''' + @mRmCd + ''' and ' + @wCnd +' RhCmCtg= ''C'' and RhCmCd =''' + @ctSelfCmCd + ''' and 
								  RhCmCurCd=''' + @mCmCurCd + ''' and ' + 
								  @wRt + ' <> 0)*(1 +' + convert(varchar,@wInc) + ' / 100) ,0))' else '0' end + ')' 
	end
	Else
	begin	  
/*		select @wAccessoriesRmIncFac =										
										'(case when ''' + @wRmCtg + ''' = ''X'' then ((' + convert(varchar,@mLme) + '-RrFrLn) * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol end)  ) else 0 end) '*/
										
		select @wAccessoriesRmIncFac =										
										'(case when ''' + @wRmCtg + ''' = ''X'' then ((' + convert(varchar,@mLme) + '-RrFrLn) * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then 0 else 0  end)  ) else 0 end) '
																									         
		select @wCommand='Select @wRmRt=' + 
			     'isnull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
				 RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg= ''P'' and RrCmCd ='''+  @mCmLkUpRmRt + ''' and 
				 RrCmCurCd=''' + @mCmCurCd + ''' and ' +@wRt +  '<> 0)* (1 + '  + convert(varchar,@wInp) + ' / 100) ,  ' +					 				 
                 'isnull((Select ' + @wRt  + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and  
                 RrCd=''' + @mRmCd + ''' and '+@wCnd + ' RrCmCtg=''' +  @mCmCtg + ''' and 
                 RrCmCd =''' + @mCmCd + ''' and RrCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0) ,' + 
                 ' ' + (case when @wCmSeekZSelfRt =1 Or @mOpt = 'C' 
				 then 'Convert(Decimal(14, '+ case when @wInc = 0 then '3' else @ws_RndOff end +'),' 
				 +'IsNull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac +					
                 ' from RmRt where RrTcTyp= ''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
                 RrCd=''' + @mRmCd + ''' and '+ @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and 
                 RrCmCd =''' + @ctSelfCmCd + ''' and RrCmCurCd=''' +  @mCmCurCd + ''' and '                                    
                 +@wRt + ' <> 0)*(1 +'  + convert(varchar, @wInc) + ' / 100) , 0))'  else '0' END )+ '))'
	End
  End
  Else If (@wRtChrtByPtr = 'P' Or @wRtChrtByBs = 'BS')
  begin	
    If(@mHistCmCtg <> '')
    begin
      If (@mOpt = 'C')	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist  
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''RM'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wcndForCostRt + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @ctSelfCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0'
      Else	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist 
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''RM'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wCnd + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @mCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0'
	End
	else
  
	begin
    If (@mOpt = 'C') 
      select @wCommand='select @wRmRt=isnull((Select  '+ @wRt + ' from RmRt where RrTcTyp=''RM'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg='''+ @wRmSCtg +''' and 
                RrCd='''+ @mRmCd +''' and '+ @wCnd + ' RrCmCtg='''+ @mCmCtg +''' and 
                RrCmCd ='''+ @mCmCd +''' and RrCmCurCd='''+ @mCmCurCd +''' and ' +@wRt + ' <> 0),
                isnull((Select ' + @wRt + ' from RmRt where RrTcTyp= ''RM'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg=''' + @wRmSCtg +''' and 
				RrCd='''+ @mRmCd +''' and ' + @wcndForCostRt + ' RrCmCtg='''+ @mCmCtg +''' and RrCmCd ='''+ @ctSelfCmCd +''' and 
				RrCmCurCd='''+ @mCmCurCd +''' and '+ @wRt + ' <> 0),0))'
    Else				
     select @wCommand='Select @wRmRt= '+ @wRt +' from RmRt where RrTcTyp= ''RM'' and 
              RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
              RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and RrCmCd =''' + @mCmCd + ''' and 
              RrCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0 '               
    End
  
  end
  select 'Command:'+isnull(@wCommand ,'')
  BEGIN TRY

  exec sp_executesql @wcommand,
						N'@mCmCd varchar(8), 
						@mRmCd varchar(16), 
                        @mLn1 decimal(8,3), 
						@mLn2 decimal(8,3), 
                        @mWtPerDia decimal(8,3), 
					    @mOpt As varchar(1),                         
					    @mLme decimal(10,3), 
						@mCmCtg As char(1),
                        @mHistCmCtg char(1) , 
						@mHistCmCd varchar(8),
                        @mHistYyyyMm decimal(8,0),                         
						@mCmCurCd varchar(8), 
                        @mCmLkUpRmRt varchar(8),                         
						@mPrtKey char(1),						
						@wRmCtg char(2),
						@wRmSCtg varchar(5),
						@wInp decimal(5,3),  
						@wRmRt decimal(10,3) output'
						,@mCmCd =@mCmCd, 
						@mRmCd =@mRmCd, 
                        @mLn1 =@mLn1, 
						@mLn2 =@mLn2, 
						@mWtPerDia =@mWtPerDia, 
						@mOpt =@mOpt,                         
						@mLme =@mLme, 
						@mCmCtg =@mCmCtg,
                        @mHistCmCtg =@mHistCmCtg, 
						@mHistCmCd =@mHistCmCd,
                        @mHistYyyyMm =@mHistYyyyMm,                         
						@mCmCurCd =@mCmCurCd, 
                        @mCmLkUpRmRt =@mCmLkuPRmRt,                         
						@mPrtKey =@mPrtKey,
						@wRmCtg=@wRmCtg,
						@wRmSCtg=@wRmSCtg,
						@wInp=@wInp,
						@wRmRt=@wRmRt output
						END TRY
						BEGIN CATCH
						 SELECT ERROR_NUMBER() AS ErrorNumber
         ,ERROR_SEVERITY() AS ErrorSeverity
         ,ERROR_STATE() AS ErrorState
         ,ERROR_PROCEDURE() AS ErrorProcedure
         ,ERROR_LINE() AS ErrorLine
         ,ERROR_MESSAGE() AS ErrorMessage
         END CATCH

Select @mrt= isnull(@wrmrt ,0)
RETURN @mrt
END

GOGO

ALTER Procedure [dbo].[ForCpy_GetRmRt] 
	(@mCmCd varchar(8), @mRmCd varchar(16), @mLn1 decimal(8,3), @mLn2 decimal(8,3), 
    @mWtPerDia decimal(8,3), @mOpt As varchar(1), @mLme decimal(10,3), @mCmCtg As char(1)='C',
    @mHistCmCtg char(1) ='', @mHistCmCd varchar(8)='', @mHistYyyyMm decimal(8,0),                         
    @mCmCurCd varchar(8), @mCmLkUpRmRt varchar(8), @mPrtKey char(1), @mRt as decimal(10,3) out)
as
begin

declare @wRmRt as decimal(10,3)
Declare @wRmCtg varchar(2), @wRmSCtg varchar(5)
Declare @ctselfcocd varchar(8)
declare @ctselfcmcd varchar(8)
declare @ErrMsg varchar(500)
Declare @wRtBy varchar(2), @wRt varchar(10), @wInc decimal(10,4), @wCnd varchar(100), @wRtByForCostRt As char(1),
  @wRtChrtByPtr varchar(2), @wRtChrtByBs varchar(2), @wcndForCostRt varchar(100),
  @wCmSeekZSelfRt bit,  @wInp decimal(5,3),  @wFrLn varchar(8), @wToLn varchar(10)
declare @wCommand nvarchar(max)
  
  SELECT @ctselfcocd='ZZZ'
  SELECT @ctSelfCmCd= 'ZSELF'

  If (@mOpt <> 'C') And (@mOpt <> 'S') 
	select 0

  If (@mCmCtg <> 'C') And (@mCmCtg <> 'S') 
	select 0

  If @mCmCurCd='' 
  begin
	select @mCmCurCd = CmCurCd from CustMst where CmCtg= @mCmCtg  and CmCd= @mCmCd 
  end
  --6.1-13 seek from custmst is removed  
  --If @mCmLkUpRmRt = '' 
  --begin
  --  select @mCmLkUpRmRt = CmLkUpRmRt from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd
  --End
   
  select @wCmSeekZSelfRt = 1 where exists (Select 'x' from CustMst where CmCtg= @mCmCtg and CmCd= @mCmCd and CmSeekZSelfRt='Y')
  
  select @wRmCtg = RmCtg ,@wRmSctg=RmSctg from RmMst where RMCd=@mRmCd 
--  If @wRmCtg = 'G' Or @wRmCtg = 'P' Or @wRmCtg = 'S' Or @wRmCtg = 'L' select 0

  declare @ws_RndOff As char(1)
  select @ws_RndOff = (select case when exists((Select 'x' from Head  Join Param on PTyp='CPYRT' and PMCd=HOrdRtRndOffRmCtg Where HCoCd=@ctselfcocd 
											and hCd=@ctSelfCmCd and ','+PDesc225+',' like '%,' + @wRmCtg + ',%' )) then  0 else 3 end)
  
    
  If(@mHistCmCtg IS NULL OR @mHistCmCtg = '') Or @mHistCmCtg <> 'P' 
  begin
    select @wRtChrtByPtr = 'P'  from RmRt where RrTcTyp= 'PTR' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and 
                 RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0 
	select @wRtChrtByPtr =isnull(@wRtChrtByPtr,'')
	

    select @wRmCtg
	select @wRmSctg
	select @wRtChrtByBs = 'BS' from RmRt where RrTcTyp= 'BS' and RrCmCtg= @mCmCtg 
                 And RrCmCd = @mCmCd and RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrSTWGrp= '' and RrCd= '' and RrDmCtg= '' 
                 and RrLsCtg= '' and RrLabMCd= '' and RrFrLn= 0 and RrToLn= 0

	
	select @wRtChrtByBs =isnull(@wRtChrtByBs ,'')
  End	

  select @wRtBy = PValue from Param where PTyp= 'RMSCTG' and PMCd= @wRmCtg and PSCd= @wRmSCtg  
  select @wRtByForCostRt = @wRtBy	
  
  If @wRtChrtByPtr <> '' 
    select @wRtBy = @wRtChrtByPtr
  Else
	If @wRtChrtByBs <> '' 
		select @wRtBy = @wRtChrtByBs
 

  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
    select @wRt = case when @mOpt = 'S' then 'RrSalRt' else 'RrCstRt' end
  Else
    select @wRt = case when @mOpt = 'S' then 'RhSalRt' else 'RhCstRt' end

  If @mCmCtg = 'S' And @mOpt = 'C' select @mCmCtg = 'C'


  If @mOpt ='S' 
	begin
    select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg  and RrCmCd= @mCmCd 
    If(@wInc IS NULL OR @wInc = 0)	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg  and RrSCtg= ''  and RrCmCd= @mCmCd
    If(@wInc IS NULL OR @wInc = 0)	 
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and 
           RrCtg= @wRmCtg and RrSCtg= @wRmSCtg and RrCmCd= @ctSelfCmCd 
	If(@wInc IS NULL OR @wInc = 0)	 	
      select @wInc = RrSalRt from RmRt where RrTcTyp= 'INC' and RrCmCtg= @mCmCtg and            
           RrCtg= @wRmCtg and RrSCtg='' and RrCmCd= @ctSelfCmCd 
	If @wInc IS NULL 
		select @wInc = 0	
	end 
  Else
    select @wInc = 0

  If @mOpt = 'S' 
	begin
    select @wInp= RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg=@wRmCtg and RrSCtg= @wRmSCtg and RrCmCd=@mCmLkUpRmRt 
    If(@wInp IS NULL OR @wInp = 0)	
      select @wInp =RrSalRt from RmRt where RrTcTyp= 'INP' and RrCmCtg= 'P' and 
           RrCtg= @wRmCtg and RrSCtg= ''  and RrCmCd= @mCmLkUpRmRt 
	If @wInp IS NULL 
		select @wInp = 0
	end  
  Else
    select @wInp = 0

  
  IF(@mHistCmCtg IS NULL OR @mHistCmCtg = '')
	begin
		select @wFrLn = 'RrFrLn'
		select @wToLn = 'RrToLn'
	end
  Else
	begin
		select @wFrLn = 'RhFrLn'
		select @wToLn = 'RhToLn'
	End

  if @wRtBy='S' 
	begin
		If @wRmCtg = 'sri'  select @mLn1 = @mLme
		select @wCnd ='  Round(' + @wFrLn+ ', 4) <= Round(' + convert(varchar,@mLn1) + ' , 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ' , 3) and '    
	end
  else if @wRtBy ='W' or @wRtBy='P' 
	select @wCnd =' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtBy = 'BS'   
	select @wCnd = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) = Round(' + + convert(varchar,@mLn2) + ', 3) and '
  else
	select @wCnd =' '    
	
  if @wRtByForCostRt='S'
	begin
		If @wRmCtg = 'sri' select @mLn1 = @mLme
		select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mLn1) + ', 3) and '
	end
  else if @wRtByForCostRt in ('W', 'P')
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) <= Round(' + convert(varchar,@mWtPerDia) + ', 4) And Round(' + @wToLn + ', 4) >= Round(' + convert(varchar,@mWtPerDia) + ', 4) and '
  else if @wRtByForCostRt = 'BS'
    select @wcndForCostRt = ' Round(' + @wFrLn + ', 4) = Round(' + convert(varchar,@mLn1) + ', 3) And Round(' + @wToLn +', 4) = Round(' + convert(varchar,@mLn2) + ', 3) and '
  else 
	select @wcndForCostRt = ' '

  Declare @wAccessoriesRmIncFac varchar(max)
  SELECT @WRTCHRTBYPTR
  SELECT @WRTCHRTBYBS 

  If (@wRtChrtByPtr = '' And @wRtChrtByBs = '' ) 
  begin	
	If(@mHistCmCtg <> '')	
	begin
		Select @wCommand='Select 
						         @wRmRt= isnull((Select ' + @wRt + ' from RmRtHist where ' +
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''RM'' and ' +
								  'RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' +  @wRmSCtg + '''  and  ' + 
								  'RhCd=''' + @mRmCd + ''' and '+ @wCnd +'RhCmCtg=''' + @mHistCmCtg + ''' and ' + 
								  'RhCmCd=''' + @mHistCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and '+ @wRt+' <> 0),' + 					  
								  case when(@wCmSeekZSelfRt = 1 Or @mOpt = 'C') then 
								  'Convert(Decimal(14,' +case when @wInc = 0 then '3' else @ws_RndOff end + '),' +
								  'IsNull((Select ' +@wRt + ' from RmRtHist where ' + 
								  'RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''RM'' and  
								  RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and  
								  RhCd=''' + @mRmCd + ''' and ' + @wCnd +' RhCmCtg= ''C'' and RhCmCd =''' + @ctSelfCmCd + ''' and 
								  RhCmCurCd=''' + @mCmCurCd + ''' and ' + 
								  @wRt + ' <> 0)*(1 +' + convert(varchar,@wInc) + ' / 100) ,0))' else '0' end + ')' 
	end
	Else
	begin	  
/*		select @wAccessoriesRmIncFac =										
										'(case when ''' + @wRmCtg + ''' = ''X'' then ((' + convert(varchar,@mLme) + '-RrFrLn) * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then RrFixMinTol else RrFixMaxTol end)  ) else 0 end) '*/
										
		select @wAccessoriesRmIncFac =										
										'(case when ''' + @wRmCtg + ''' = ''X'' then ((' + convert(varchar,@mLme) + '-RrFrLn) * ' +
										'(case when ''' + @mOpt + ''' = ''C'' then 0 else 0  end)  ) else 0 end) '
																									         
		select @wCommand='Select @wRmRt=' + 
			     'isnull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
				 RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg= ''P'' and RrCmCd ='''+  @mCmLkUpRmRt + ''' and 
				 RrCmCurCd=''' + @mCmCurCd + ''' and ' +@wRt +  '<> 0)* (1 + '  + convert(varchar,@wInp) + ' / 100) ,  ' +					 				 
                 'isnull((Select ' + @wRt  + '+' + @wAccessoriesRmIncFac + 
                 ' from RmRt where RrTcTyp=''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and  
                 RrCd=''' + @mRmCd + ''' and '+@wCnd + ' RrCmCtg=''' +  @mCmCtg + ''' and 
                 RrCmCd =''' + @mCmCd + ''' and RrCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0) ,' + 
                 ' ' + (case when @wCmSeekZSelfRt =1 Or @mOpt = 'C' 
				 then 'Convert(Decimal(14, '+ case when @wInc = 0 then '3' else @ws_RndOff end +'),' 
				 +'IsNull((Select ' + @wRt + '+' + @wAccessoriesRmIncFac +					
                 ' from RmRt where RrTcTyp= ''RM'' and RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
                 RrCd=''' + @mRmCd + ''' and '+ @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and 
                 RrCmCd =''' + @ctSelfCmCd + ''' and RrCmCurCd=''' +  @mCmCurCd + ''' and '                                    
                 +@wRt + ' <> 0)*(1 +'  + convert(varchar, @wInc) + ' / 100) , 0))'  else '0' END )+ '))'
	End
  End
  Else If (@wRtChrtByPtr = 'P' Or @wRtChrtByBs = 'BS')
  begin	
    If(@mHistCmCtg <> '')
    begin
      If (@mOpt = 'C')	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist  
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp=''RM'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wcndForCostRt + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @ctSelfCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0'
      Else	  
        select @wCommand='Select @wRmRt=' + @wRt + ' from RmRtHist 
                where RhYyyyMm=' + convert(varchar,@mHistYyyyMm) + ' and RhTcTyp= ''RM'' and 
                RhCtg=''' + @wRmCtg + ''' and RhSCtg=''' + @wRmSCtg + ''' and 
                RhCd=''' + @mRmCd + ''' and ' + @wCnd + ' RhCmCtg= ''C'' and RhCmCd =''' + 
                @mCmCd + ''' and RhCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0'
	End
	else
  
	begin
    If (@mOpt = 'C') 
      select @wCommand='select @wRmRt=isnull((Select  '+ @wRt + ' from RmRt where RrTcTyp=''RM'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg='''+ @wRmSCtg +''' and 
                RrCd='''+ @mRmCd +''' and '+ @wCnd + ' RrCmCtg='''+ @mCmCtg +''' and 
                RrCmCd ='''+ @mCmCd +''' and RrCmCurCd='''+ @mCmCurCd +''' and ' +@wRt + ' <> 0),
                isnull((Select ' + @wRt + ' from RmRt where RrTcTyp= ''RM'' and 
				RrCtg='''+ @wRmCtg +''' and RrSCtg=''' + @wRmSCtg +''' and 
				RrCd='''+ @mRmCd +''' and ' + @wcndForCostRt + ' RrCmCtg='''+ @mCmCtg +''' and RrCmCd ='''+ @ctSelfCmCd +''' and 
				RrCmCurCd='''+ @mCmCurCd +''' and '+ @wRt + ' <> 0),0))'
    Else				
     select @wCommand='Select @wRmRt= '+ @wRt +' from RmRt where RrTcTyp= ''RM'' and 
              RrCtg=''' + @wRmCtg + ''' and RrSCtg=''' + @wRmSCtg + ''' and 
              RrCd=''' + @mRmCd + ''' and ' + @wCnd + ' RrCmCtg=''' + @mCmCtg + ''' and RrCmCd =''' + @mCmCd + ''' and 
              RrCmCurCd=''' + @mCmCurCd + ''' and ' + @wRt + ' <> 0 '               
    End
  
  end
  select 'Command:'+isnull(@wCommand ,'')
  BEGIN TRY

  exec sp_executesql @wcommand,
						N'@mCmCd varchar(8), 
						@mRmCd varchar(16), 
                        @mLn1 decimal(8,3), 
						@mLn2 decimal(8,3), 
                        @mWtPerDia decimal(8,3), 
					    @mOpt As varchar(1),                         
					    @mLme decimal(10,3), 
						@mCmCtg As char(1),
                        @mHistCmCtg char(1) , 
						@mHistCmCd varchar(8),
                        @mHistYyyyMm decimal(8,0),                         
						@mCmCurCd varchar(8), 
                        @mCmLkUpRmRt varchar(8),                         
						@mPrtKey char(1),						
						@wRmCtg char(2),
						@wRmSCtg varchar(5),
						@wInp decimal(5,3),  
						@wRmRt decimal(10,3) output'
						,@mCmCd =@mCmCd, 
						@mRmCd =@mRmCd, 
                        @mLn1 =@mLn1, 
						@mLn2 =@mLn2, 
						@mWtPerDia =@mWtPerDia, 
						@mOpt =@mOpt,                         
						@mLme =@mLme, 
						@mCmCtg =@mCmCtg,
                        @mHistCmCtg =@mHistCmCtg, 
						@mHistCmCd =@mHistCmCd,
                        @mHistYyyyMm =@mHistYyyyMm,                         
						@mCmCurCd =@mCmCurCd, 
                        @mCmLkUpRmRt =@mCmLkuPRmRt,                         
						@mPrtKey =@mPrtKey,
						@wRmCtg=@wRmCtg,
						@wRmSCtg=@wRmSCtg,
						@wInp=@wInp,
						@wRmRt=@wRmRt output
						END TRY
						BEGIN CATCH
						 SELECT ERROR_NUMBER() AS ErrorNumber
         ,ERROR_SEVERITY() AS ErrorSeverity
         ,ERROR_STATE() AS ErrorState
         ,ERROR_PROCEDURE() AS ErrorProcedure
         ,ERROR_LINE() AS ErrorLine
         ,ERROR_MESSAGE() AS ErrorMessage
         END CATCH

Select @mrt= isnull(@wrmrt ,0)
RETURN @mrt
END


GOGO

ALTER TRIGGER [dbo].[RmMst_INUPDL] ON [dbo].[RmMst] 
     FOR INSERT,UPDATE,DELETE
	NOT FOR REPLICATION
AS
BEGIN
	/* *** Trigger Version Emr 3.10.0 *** */
	DECLARE @ROW INT
	DECLARE @mode char(1)
	DECLARE @errmsg varchar(255)
	DECLARE @SYS VARCHAR(5)
	Declare @wHCoCd Varchar(8) 
	Declare @wCurrPrtn varchar(1)
	DECLARE @ReplAgt BIT  

	IF @@ROWCOUNT= 0
		RETURN
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'RmMst' )
		RETURN

	Set @SYS= IsNull((Select PMCd from Param where PTyp= 'SYS' and PMCd= 'XEMR' and PSCd= ''), '') 

	select @mode= case (select count('x') from inserted) when 0 then 'D'
			 else
				case (select count('x') from deleted) when 0 then 'A' else 'C' end
			 end 

	Select @wHCoCd= 'ZZZ'
	Select @wCurrPrtn= 'C'

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
 	if @mode in ('A','C') And @ReplAgt <> 1
 	Begin		
		Select @row=count('x') From Inserted Where RmPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end

		Select @row=count('x') From Inserted Where RmPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	End

	if @mode = 'D' And @ReplAgt <> 1 
	Begin
		Select @row= count('x') From deleted del Where del.RmPrtKey<>@wCurrPrtn
		If @row> 0 
		Begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		End
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */


 	If @mode = 'C'
 	Begin
		/******** Primary Key (RmCd) along with RmCtg and RmSCtg Cannot Be Changed ********/ 
		/* Check on Current Db */
		select @Row= Count('x') from deleted del where del.RmPrtKey=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.RmCd= del.RmCd and 
				    ins.RmCtg= del.RmCtg and ins.RmSCtg= del.RmSCtg)
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change Rm Code/ Category/ SubCategory'
			GoTo ErrHndlr
		end

		/******** Cannot Change Customs Code When InvRm Record Exists ********/ 
		/* Check on Current Db */
		select @Row= Count('x') from deleted del where RmZ= 'N' and RmPrtKey=@wCurrPrtn and 
			not exists (Select 'x' from inserted ins where ins.RmCd= del.RmCd and ins.RmPrtKey=del.RmPrtKey and ins.RmZCd= del.RmZCd)
			and exists(Select 'x' from InvRm where IrRmCd= del.RmCd)
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change Customs Code When InvRm Record Exists'
			GoTo ErrHndlr
		end

		/******** Cannot Change RmQw When RmRt Record Exists ********/ 
		/* Check on Current Db */
		Select @Row= Count('x') from deleted del where del.RmPrtKey=@wCurrPrtn and 
			not exists (Select 'x' from inserted ins where ins.RmCd=del.RmCd and ins.RmQw=del.RmQw and ins.RmQwCst=del.RmQwCst and ins.RmPrtKey=@wCurrPrtn)
			and exists (Select 'x' from RmRt where RrTcTyp= 'RM' and RrCd= del.RmCd and RrPrtKey=RmPrtKey) 
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change Sale/Cost Q/W As Rm Rate Record Exists'
			GoTo ErrHndlr
		end	

		/******** Cannot Change RmQw When OrdRm Record Exists ********/ 
		/* Check on Current Db */
		select @Row= Count('x') from deleted del where del.RmPrtKey=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.RmCd= del.RmCd and ins.RmQw= del.RmQw and ins.RmQwCst=del.RmQwCst and ins.RmPrtKey=del.RmPrtKey )
			and exists(Select 'x' from OrdRm where OrRmCd= del.RmCd and OrPrtKey=RmPrtKey) 
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change Sale/Cost Q/W As Order Rm Record Exists'
			GoTo ErrHndlr
		end

		/******** Manali 3.10.0 - Cannot Change RmQw When MultiPrcQtRm Record Exists ********/ 
		/* Check on Current Db */
		select @Row= Count('x') from deleted del where del.RmPrtKey=@wCurrPrtn and
			not exists (Select 'x' from inserted ins where ins.RmCd= del.RmCd and ins.RmQw= del.RmQw and ins.RmQwCst=del.RmQwCst and ins.RmPrtKey=del.RmPrtKey )
			and exists(Select 'x' from MultiPrcQtRm where MqrRmCd= del.RmCd and MqrPrtKey=RmPrtKey) 
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change Sale/Cost Q/W As MultiPrcQtRm Record Exists'
			GoTo ErrHndlr
		end

		/******** Cannot Change RmQw When Txnd Record Exists ********/ 
		/* Check on Current Db */
		select @Row= Count('x') from deleted del where del.RmPrtKey=@wCurrPrtn and 
			not exists (Select 'x' from inserted ins where ins.RmCd= del.RmCd and ins.RmPrtKey=del.RmPrtKey and ins.RmQw= del.RmQw)
			and exists(Select 'x' from Txnd where TdRmCd= del.RmCd) 
		If @Row > 0
		begin 
			Select @ErrMsg= 'Cannot Change Q/W As Txnd Record Exists'
			GoTo ErrHndlr
		end

		/* ****** Sachin 2.12 - 06/12/05 - SJM ****** */ 
			/****** RmPurityWt cannot be changed for Silver if HSlvModYN is Set to 'N' in Head ******/
			/* Check on Current Db */
			select @row= count('x') from inserted ins where ins.RmCtg='S' and ins.RmPrtKey=@wCurrPrtn and
				Not Exists (Select 'x' from deleted del where ins.RmCd= del.RmCd and ins.RmPurityWt= del.RmPurityWt and ins.RmPrtKey=del.RmPrtKey) and 
				Exists (Select 'x' from Head where HCoCd=@wHCoCd And HSlvModYN='N') 				
			if @row> 0 
			begin
				select @errmsg= 'Cannot Change Prd Purity if Silver Module option is set to ''N'' in Head' 
				goto ErrHndlr
			end 
		/* ****** Sachin 2.12 - 06/12/05 - SJM ****** */ 
		
		/* ***** Manali 3.03 - 17/06/08 - Palladium Module */		
		/****** RmPurityWt cannot be changed for Palladium if HPdModYN is Set to 'N' in Head ******/
		/* Check on Current Db */
		select @row= count('x') from inserted ins where ins.RmCtg='L' and ins.RmPrtKey=@wCurrPrtn and
			Not Exists (Select 'x' from deleted del where ins.RmCd= del.RmCd and ins.RmPurityWt= del.RmPurityWt and ins.RmPrtKey=del.RmPrtKey) and 
			Exists (Select 'x' from Head where HCoCd=@wHCoCd And HPdModYN='N') 				
		if @row> 0 
		begin
			select @errmsg= 'Cannot Change Prd Purity if Palladium Module option is set to ''N'' in Head' 
			goto ErrHndlr
		end 
		/* ***** Manali 3.03 - 17/06/08 - Palladium Module */		
	End

 	if @mode in ('A','C')
 	Begin
		/****** RmId = PSCD('RMID') ******/
		/* Current Partition  */
		select @row= count('x') from Inserted where RmId <> '' And RmZ= 'N' And RmPrtKey=@wCurrPrtn and
			not exists (select 'x' from Param where PTyp= 'RMID' and PMCd= RmCtg And PSCd = RmId)
		if @row> 0 
		begin
			select @errmsg= 'Raw Material Id  Not Defined'
			goto ErrHndlr
		end
		
		/****** RmId = PSCD('RMID') ******/
		/* Current Partition  */
		select @row= count('x') from Inserted where RmId <> '' And RmZ= 'Y'  And RmPrtKey=@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Raw Material Id Should be Blank'
			goto ErrHndlr
		end
	
		/****** RmSCtg= PSCd ('RMSCTG', RmCtg) ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmPrtKey=@wCurrPrtn and not exists (select 'x' from Param where 
			PTyp= 'RMSCTG' and PMCd= RmCtg and PSCd= RmSCtg)
		if @row> 0 
		begin
			select @errmsg= 'Raw Material Sub Category Not Defined'
			goto ErrHndlr
		end
	

	
		select @row= count('x') from inserted where RmCtg in (	'G', 'P', 'S', 'L',  'X') and RmZ= 'N' and RmPrtKey=@wCurrPrtn and RmSTWGrp <>'' and
			not exists (select 'x' from Param where PTyp= 'STWGRP' and PMCd= RmSTWGrp)
		if @row> 0 
		begin
			select @errmsg= 'Size To Weight Group Not Defined'
			goto ErrHndlr
		end
	
		/****** RmSTWGrp= PMCd ('STWGRP') when RmCtg= 'C' or 'D' and RmZ= 'N' ******/
		/* Current Partition  */
		--6.1 new 'G', 'P', 'S', 'L', 'M', 'X' added
		select @row= count('x') from inserted where RmCtg in ('C', 'D') and RmZ= 'N' and RmPrtKey=@wCurrPrtn and
			not exists (select 'x' from Param where PTyp= 'STWGRP' and PMCd= RmSTWGrp)
		if @row> 0 
		begin
			select @errmsg= 'Size To Weight Group Not Defined'
			goto ErrHndlr
		end
	
		/****** RmSTWGrp= Blank when RmCtg in ('G', 'P', 'S', 'A', 'M', 'X') or RmZ= 'Y' ******/
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L'  added */
		--6.1 new 'G', 'P', 'S', 'L', 'M', 'X'
		select @row= count('x') from inserted where RmSTWGrp<> '' and RmPrtKey=@wCurrPrtn and 
			(RmCtg in ('A') or RmZ= 'Y')  			
		if @row> 0 
		begin
			select @errmsg= 'Size To Weight Group Should Be Blank'
			goto ErrHndlr
		end
	
		/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
		/*	Date: 09/12/2003																			 */
		/****** RmValidYn = PMCd ('YN') ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmPrtKey=@wCurrPrtn and
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= RmValidYN)
		if @row> 0
		begin
			select @errmsg= 'Valid (Y/N) Not Defined'
			goto ErrHndlr
		End
		/*  #########################################  Manoj  #########################################  */
	
		/****** RmParentCd= PMCd ('PARENTCD') when RmCtg= 'C' or 'D' and RmZ= 'N' ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmParentCd<> '' and RmCtg in ('C', 'D') and RmZ= 'N' and RmPrtKey=@wCurrPrtn and 
			Not exists (select 'x' from Param where PTyp= 'PARENTCD' and PMCd= RmParentCd)
		if @row> 0 
		begin
			select @errmsg= 'Parent Code Not Defined'
			goto ErrHndlr
		end
	
		/****** RmParentCd= Blank when RmCtg in ('G', 'P', 'S', 'A', 'M', 'X') or RmZ= 'Y' ******/
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L'  added */
		select @row= count('x') from inserted where RmParentCd<>'' and RmPrtKey=@wCurrPrtn and
			(RmCtg in ('G', 'P', 'S', 'L', 'A', 'M', 'X') or RmZ= 'Y')  			
		if @row> 0 
		begin
			select @errmsg= 'Parent Code Should Be Blank'
			goto ErrHndlr
		end
	
		/* Current Partition  */		
		select @row= count('x') from inserted where RmCd= '' and RmPrtKey=@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Raw Material Code Cannot Be Blank'
			goto ErrHndlr
		end
	
		/****** RmSpGrav <> 0 ******/
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L' added */
		select @row= count('x') from inserted where RmSpGrav= 0 and RmPrtKey=@wCurrPrtn and
			RmCtg in ('G', 'P', 'S', 'L', 'A', 'M') 
		if @row> 0 
		begin
			select @errmsg= 'Specific Gravity Cannot Be Zero'
			goto ErrHndlr
		end
	
		/****** RmPurityRt <> 0 ******/
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L' added */
		select @row= count('x') from inserted where RmPurityRt= 0 and RmPrtKey=@wCurrPrtn and
			RmCtg in ('G', 'P', 'S', 'L','M') 
		if @row> 0 
		begin
			select @errmsg= 'Purity Cannot Be Zero'
			goto ErrHndlr
		end
	
		/****** RmPurityWt <> 0 for RmCtg= G,P ******/
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L' added */
		select @row= count('x') from inserted where RmPurityWt= 0 and RmPrtKey=@wCurrPrtn and
			RmCtg in ('G', 'P', 'S', 'L','M') 
		if @row> 0 
		begin
			select @errmsg= 'Production Purity Cannot Be Zero'
			goto ErrHndlr
		end
	
		/* **** Zubin 211 **** */ 
			/****** RmPurityWt Cannot be changed RmCtg= G,P,S ******/
			/* Current Partition  */
			/* *** Manali 3.03 - 17/06/08 - 'L' added */
		select @row= count('x') from inserted ins where ins.RmCtg In ('G', 'P', 'S', 'L','M') and ins.RmPrtKey=@wCurrPrtn and 
				Not Exists (Select 'x' from deleted del where ins.RmCd= del.RmCd and ins.RmPurityWt= del.RmPurityWt and ins.RmPrtKey=del.RmPrtKey) and 
				Exists (Select 'x' from Txnd where TdRmCd= RmCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Change Production Purity As RmCd Is Used In Txnd Table' 
				goto ErrHndlr
			end
		/* **** Zubin 211 **** */ 

		/****** RmBasePurityWt <> 0 for RmCtg= X ******/
		/* Current Partition  */
		select @row= count('x') from inserted where Round(RmBasePurityWt, 4)= 0 and RmZ= 'N' and RmPrtKey=@wCurrPrtn 
			and RmCtg= 'X' 
		if @row> 0 
		begin
			select @errmsg= 'Base Production Purity Cannot Be Zero For Accessories'
			goto ErrHndlr
		end
	
		/****** RmBasePurityWt = 0 for RmZ= 'Y' or RmCtg = G,P,S,D,C,A,M ******/
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L' added */
		select @row= count('x') from inserted where Round(RmBasePurityWt, 4)<> 0 and RmPrtKey=@wCurrPrtn and
			(RmZ= 'Y' or RmCtg in ('G', 'P', 'S', 'L', 'D', 'C', 'A', 'M')) 
		if @row> 0 
		begin
			select @errmsg= 'Base Production Purity Should Be Zero For RmCtg = G,P,S,L,D,C,A,M Or Custom Code'
			goto ErrHndlr
		end
	
		/****** RmCmCd = Blank or valid CmCd from CustMst (CmCtg= 'C') ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmCmCd<> '' and RmPrtKey=@wCurrPrtn
			and not exists (select 'x' from CustMst where 
			CmCtg= 'C' and CmCd= RmCmCd)
		if @row> 0 
		begin
			select @errmsg= 'Customer Code Not Defined'
			goto ErrHndlr
		end

			
		/****** RmUom = PMCd ('RMUOM') ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmPrtKey=@wCurrPrtn and
			not exists (select 'x' from Param where PTyp= 'RMUOM' and PMCd= RmUom)
		if @row>0 
		begin
			select @errmsg= 'Raw Material Unit Of Measurement Not Defined'
			goto ErrHndlr
		end
	
	/*		Manoj 2.10.0		*/
		/****** RmSCtg = PSCd ('RMCOL', RmCtg) ******/
	/*	select @row= count('x') from inserted where not exists (select 'x' from Param where 
				PTyp= 'RMCOL' and PMCd= RmCtg and PSCd= RmCol)
		if @row> 0 
		begin
			select @errmsg= 'Raw Material Colour Not Defined'
			goto ErrHndlr
		end
	*/
		/* Current Partition  */
		select @row= count('x') from inserted Ins where Ins.RmPrtKey=@wCurrPrtn and 
			Ins.RmCol <> IsNull((Select Del.RmCol From Deleted Del Where Ins.RmCd = Del.RmCd and Ins.RmPrtKey=Del.RmPrtKey), '') And 
			not exists (select 'x' from Param where PTyp= 'RMCOL' and PMCd= RmCtg and PSCd= RmCol And PValidYn = 'Y')
		if @row> 0 
		begin
			select @errmsg= 'Raw Material Colour Not Defined / Invalid.'
			goto ErrHndlr
		end
	/*		Manoj 2.10.0		*/
		
		/****** If RmCtg= 'G' or 'P' or 'S' then RmKt = PMCd ('KT')  	else RmKt= Blank or PMCd ('KT') ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmKt<> '' and RmPrtKey=@wCurrPrtn
			and not exists (select 'x' from Param where 
			PTyp= 'KT' and PMCd= RmKt)
		if @row> 0 
		begin
			select @errmsg= 'Karat Not Defined'
			goto ErrHndlr
		end
	
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L'  added */
		select @row= count('x') from inserted where RmCtg in ('G', 'P', 'S', 'L') and RmKt= '' and RmPrtKey=@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Karat Not Defined'
			goto ErrHndlr
		end
	
		/****** RmZ = PMCd ('YN') ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmPrtKey=@wCurrPrtn and
			not exists (select 'x' from Param where PTyp= 'YN' and PMCd= RmZ)
		if @row> 0 
		begin
			select @errmsg= 'Specify If Customs Code (Y/N)'
			goto ErrHndlr
		end
	
		/****** If RmZ = 'N'  then 
				If RmCtg = 'A'  then  Blank 	else RmCd from RmMst (RmCtg= RmCtg, RmZ= 'Y')  
			If RmZ = 'Y'  then Blank 	******/
		
		/* Check on Current Db - added the deleted condition so that push-to-current ignores this check */
		select @row= count('x') from inserted where inserted.RmZ= 'N' and inserted.RmPrtKey=@wCurrPrtn and
			inserted.RmCtg<> 'A'  and 
			Not Exists (Select 'x' From Deleted del Where inserted.RmCd=del.RmCd and inserted.RmPrtKey<>del.RmPrtKey) and 
			Not exists (select 'x' from RmMst Rm where 
				Rm.RmCtg= inserted.RmCtg and Rm.RmZ= 'Y' and Rm.RmCd= inserted.RmZCd and Rm.RmPrtKey=inserted.RmPrtKey)
		if @row> 0 
		begin
			select @errmsg= 'Customs Code Not Defined'
			goto ErrHndlr
		end

		/* Current Partition  */
		select @row= count('x') from inserted where (RmZ= 'Y' or RmCtg= 'A') and RmPrtKey=@wCurrPrtn  
			and RmZCd<> '' 
		if @row> 0 
		begin
			select @errmsg= 'Customs Code Should Not Be Entered'
			goto ErrHndlr
		end

	/*  #################################  Manoj #### Ver: 2.0.6  #################################  */
	/*	Date: 09/12/2003																			 */
		/****** If RmZ = 'N' And RmZCd<>'' And inserted RmZCd <> deleted RmZCd	******/
		/******		then  RmCd from RmMst (RmValidYN=)  						******/
		/* Check On Current Db - updated the deleted condition so that push-to-current ignores this check */
		Select @row= count('x') From Inserted Ins Where Ins.RmZ = 'N' And Ins.RmZCd <> '' 
				And Ins.RmPrtKey=@wCurrPrtn and 
					Ins.RmZCd <> IsNull((Select RmZCd from Deleted Del Where Del.RmCd = Ins.RmCd 
										and Del.RmPrtKey=(Case When Del.RmPrtKey<>@wCurrPrtn Then Del.RmPrtKey Else Ins.RmPrtKey End)), '') And
				Not Exists (Select 'x' from RmMst Rm Where Rm.RmCd = Ins.RmZCd And Rm.RmValidYN = 'Y' 
							And Rm.RmPrtKey=ins.RmPrtKey)
		if @row> 0
		begin
			select @errmsg= 'Customs Code Not Valid'
			goto ErrHndlr
		end
	/*  #########################################  Manoj  #########################################  */
	
		/****** RmBaseCd = valid RmCode of RmCtg 'G' or 'P' or 'S' when RmCtg= 'X' and RmZ= 'N' ******/
		/* Check On Current Db */
		/* *** Manali 3.03 - 17/06/08 - 'L'  added */
		select @row= count('x') from inserted ins where RmCtg= 'X' and RmZ= 'N' and RmPrtKey=@wCurrPrtn and
			not exists (select 'x' from RmMst Rm where Rm.RmCtg in ('G', 'P', 'S', 'L') and Rm.RmZ= 'N' 
				    and Rm.RmCd= ins.RmBaseCd and Rm.RmPrtKey=ins.RmPrtKey)
		if @row> 0 
		begin
			select @errmsg= 'Base Code For Accessories Should Be A Valid RmCode Of RmCtg ''G'' or ''P'' or ''S'' or ''L'''
			goto ErrHndlr
		end
	
		/****** RmBaseCd = Blank when RmZ= 'Y' or RmCtg= G,P,S,D,C,A,M ******/
		/* Current Partition  */
		/* *** Manali 3.03 - 17/06/08 - 'L'  added */
		select @row= count('x') from inserted ins where RmBaseCd<> '' and RmPrtKey=@wCurrPrtn and
			(RmZ= 'Y' or RmCtg in ('G', 'P', 'S', 'L', 'D', 'C', 'A', 'M')) 
		if @row> 0 
		begin
			select @errmsg= 'Base Code Should Be Blank For RmCtg= G,P,S,D,C,A,M and Custom Codes'
			goto ErrHndlr
		end
	
		/* ****** Sachin 2.13.0 - 29-05-2006 ****** */
		/****** Enter 'Q' or 'W' in Sales RmQw for all RmCategories ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmPrtKey=@wCurrPrtn and 
				not exists (select 'x' from Param where PTyp= 'LABQW' and PMCd= RmQw and PSCd= '')
		if @row> 0 
		begin
			select @errmsg= 'Mention If RM Sale Value Calculation Is By Quantity Or Weight'
			goto ErrHndlr
		end
	
		/****** Enter 'Q' or 'W' in Cost RmQw for all RmCategories ******/
		/* Current Partition  */
		select @row= count('x') from inserted where RmPrtKey=@wCurrPrtn and
				not exists (select 'x' from Param where PTyp= 'LABQW' and PMCd= RmQwCst and PSCd= '')
		if @row> 0 
		begin
			select @errmsg= 'Mention If RM Cost Value Calculation Is By Quantity Or Weight'
			goto ErrHndlr
		end

		/***** Manali 3.8.0 - AlyCd for RmCtg GPSL *****/
		select @row= count('x') from inserted Ins where RmPrtKey=@wCurrPrtn and RmCtg In ('G', 'P', 'S', 'L')
				and RmAlyCd<>'' and not exists(select 'x' from RmMst Rm where Rm.RmCtg= 'A' and Rm.RmCd=Ins.RmAlyCd and Rm.RmZ='N' and Rm.RmValidYn='Y')
		if @row> 0 
		begin
			select @errmsg= 'Invalid Alloy Code'
			goto ErrHndlr
		end

		select @row= count('x') from inserted Ins where RmPrtKey=@wCurrPrtn and RmCtg Not In ('G', 'P', 'S', 'L')
				and RmAlyCd<>'' 
		if @row> 0 
		begin
			select @errmsg= 'Alloy Code Cannot Be Entered'
			goto ErrHndlr
		end

		/* JewelSmith.2 Stone Class <>'' */
		select @row= count('x') from inserted where RmStnCls= '' and RmPrtKey=@wCurrPrtn and RmCtg in ('C', 'D')   			
		if @row> 0 
		begin
			select @errmsg= 'Stone Class Should Not Be Blank'
			goto ErrHndlr
		end
		/* JewelSmith.2 Stone Class ='' for other than DC */
		select @row= count('x') from inserted where RmStnCls<> '' and RmPrtKey=@wCurrPrtn and RmCtg not in ('C', 'D')   			
		if @row> 0 
		begin
			select @errmsg= 'Stone Class Should Be Blank'
			goto ErrHndlr
		end

		/****** RmQw = Blank if RmCtg in ('G', 'P', 'S', 'D', 'C', 'A', 'M') ******/
		/*select @row= count('x') from inserted where RmQw<> '' and RmCtg in ('G', 'P', 'S', 'D', 'C', 'A', 'M') 
	
		if @row> 0 
		begin
			select @errmsg= 'Q/W Should Be Blank For Categories G,P,S,D,C,A and M'
			goto ErrHndlr
		end*/
		
		--4 ZRmPurity cannot change if customs match exists 
		select @row= count('x') from inserted ins where ins.RmCtg In ('G', 'P', 'S', 'L','M') and ins.RmPrtKey=@wCurrPrtn and 
			Not Exists (Select 'x' from deleted del where ins.RmCd= del.RmCd and ins.RmPurityZ= del.RmPurityZ and ins.RmPrtKey=del.RmPrtKey) 
			and Exists (Select 'x' from InvRm join InvZRm on IzTc =IrTc and IzYy =IrYy and IzChr =IrChr and IzNo =IrNo 
			 where IrRmCd = RmCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Change ZPurity As RmCd Is Used In InvRm Table' 
				goto ErrHndlr
			end
		
	End

	if @mode = 'D' And @ReplAgt <> 1
	Begin

		/****** Cannot delete RmCd where RmZ= 'N' which  is in use in CustAly Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and RmPrtKey=@wCurrPrtn and
			exists (select 'x' from CustAly where CaRmCd= RmCd or CaAlyCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In CustAly Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which  is in use in DsgRm Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and RmPrtKey=@wCurrPrtn and
			exists (select 'x' from DsgRm where DrRmCd= RmCd or DrAlyCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In DsgRm Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'Y' which  is in use in RmMst Table ******/
		/* Check On Current Db */
		select @row= count('x') from deleted del where del.RmZ= 'Y' and 
			exists (select 'x' from RmMst Rm where Rm.RmZ= 'N' and Rm.RmZCd= del.RmCd and Rm.RmPrtKey=del.RmPrtKey)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Custom Code In Use In RmMst Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which  is in use in RmRt Table ******/
		/* Check On Current Db */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from RmRt where RrCd= RmCd and RrPrtKey=RmPrtKey)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In RmRt Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which  is in use in OrdRm Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from OrdRm where OrRmCd= RmCd or OrAlyCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In OrdRm Table'
			goto ErrHndlr
		end

		/****** Manali 3.10.0 - Cannot delete RmCd where RmZ= 'N' which  is in use in MultiPrcQtRm Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from MultiPrcQtRm where MqrRmCd= RmCd or MqrAlyCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In MultiPrcQtRm Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which  is in use in OrdTgt Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from OrdTgt where OtRmCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In OrdTgt Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which is in use in FgRm Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from FgRm where FrRmCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In FgRm Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which is in use in SYyMm Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from SYyMm where SRmCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In SYyMm Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which is in use in Txnd Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from Txnd where TdRmCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In Txnd Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'N' which is in use in Grade Table ******/
		/* Partition Check Not required */
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from Grade where GrRmCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code Is Used In Grade Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'Y' which is in use in TxndZ Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'Y' and 
			exists (select 'x' from TxndZ where TzRmZCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Customs Code In Use In TxndZ Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where RmZ= 'Y' which is in use in InvRm Table ******/
		/* Check On Complete Db */
		select @row= count('x') from deleted del where RmZ= 'Y' and 
			exists (select 'x' from InvRm where IrRmZCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Customs Code In Use In InvRm Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where which is in use in RmAlyCmp Table ******/
		/* Partition Check Not Required */
		select @row= count('x') from deleted del where 
			exists (select 'x' from RmAlyCmp where RaCd= RmCd or RaCmpCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm/ Customs Code In Use In RmAlyCmp Table'
			goto ErrHndlr
		end
		
		/*VK.5*/		
		/****** Cannot delete RmCd which is in use in CertDet Table ******/		
		select @row= count('x') from deleted del where RmZ= 'N' and 
			exists (select 'x' from CertDet where CdRmCd= RmCd)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use In CertDet Table'
			goto ErrHndlr
		end

		/****** Cannot delete RmCd where which is in use as Base Code in RmMst Table ******/
		/* Check On Current Db */
		select @row= count('x') from deleted del where del.RmZ= 'N' and del.RmCtg in ('G', 'P', 'S', 'L') and 
			exists (select 'x' from RmMst Rm where Rm.RmCtg= 'X' and Rm.RmZ= 'N' 
						and Rm.RmBaseCd= del.RmCd and Rm.RmPrtKey=del.RmPrtKey)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use As Base Code In RmMst Table'
			goto ErrHndlr
		end

		select @row= count('x') from deleted del where del.RmZ= 'N' and del.RmCtg in ('A') and 
			exists (select 'x' from RmMst Rm where Rm.RmCtg In ('G', 'P', 'S', 'L') and Rm.RmZ= 'N' 
						and Rm.RmAlyCd= del.RmCd and Rm.RmPrtKey=del.RmPrtKey)
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete As Rm Code In Use As Alloy Code In RmMst Table'
			goto ErrHndlr
		end

	End

	if @SYS= 'XEMR' 
	/* Partition Checks Not done On 'XEMR' */
	BEGIN

		if @mode = 'D' 
		Begin
			/****** Cannot delete RmCd where RmZ= 'N' which  is in use in xTxnRm Table ******/
			select @row= count('x') from deleted del where RmZ= 'N' and 
				exists (select 'x' from xTxnRm where xTrRmCd= RmCd
					or xTrRmCtg= 'A' and  xTrAlyCd= RmCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Rm Code In Use In xTxnRm Table'
				goto ErrHndlr
			end	
	
			/****** Cannot delete RmCd where RmZ= 'N' which  is in use in xTxnTgt Table ******/
			select @row= count('x') from deleted del where RmZ= 'N' and 
				exists (select 'x' from xTxnTgt where xTtRmCd= RmCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Rm Code In Use In xTxnTgt Table'
				goto ErrHndlr
			end

			/****** Cannot delete RmCd where RmZ= 'N' which is in use in xStkYyMm Table ******/	
			select @row= count('x') from deleted del where RmZ= 'N' and 
				exists (select 'x' from xStkYyMm where xSyRmCd= RmCd)
			if @row> 0 
			begin
				select @errmsg= 'Cannot Delete As Rm Code In Use In xStkYyMm Table'
				goto ErrHndlr
			end
		End
	END

return
ErrHndlr:
	begin
		select @errmsg='|'+@errmsg
		raiserror(@errmsg,16,1)
		rollback transaction 
	end
END

GOGO

ALTER TRIGGER [dbo].[Fmd_INUPDL] ON [dbo].[Fmd] 
       FOR INSERT,UPDATE,DELETE  
	NOT FOR REPLICATION
AS  
BEGIN  
	DECLARE @ROW INT  
	DECLARE @mode char(1)  
	DECLARE @errmsg varchar(255)  
	Declare @wTcTyp Varchar(3)	
	Declare @wHCd Varchar(8)
	DECLARE @ReplAgt BIT  
	DECLARE @wCurrPrtn VarChar(1) 
	
	IF @@ROWCOUNT=0   RETURN  
	
	If Exists(Select 'x' From TrgDisa Where TdTblNm = 'Fmd' )  
	RETURN  
	  
	select @mode=case (select count('x') from inserted) when 0 then 'D'  
		else  
		case (select count('x') from deleted) when 0 then 'A' else 'C' end  
		end   

	Select @wHCd= 'ZSELF'
	Select @wCurrPrtn='C'

	/*** Storing Tc Type In The Variable @wTcTyp ***/
	if @mode in ('A','C')
	begin
		select @wTcTyp= max(PValue) from inserted join Param on PTyp= 'TC' and PMCd= FmdTc and PSCd=''
	end
	if @mode in ('D')
	begin
		select @wTcTyp= max(PValue) from deleted join Param on PTyp= 'TC' and PMCd= FmdTc and PSCd=''
	end

	/* **** Checking Whether a Normal Transaction or Replicated One **** */
	Set @ReplAgt=Convert(BIT,SessionProperty('Replication_Agent'))

	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	if @mode='C'
	begin
		Select @row=count('x') From Inserted Where FmdPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Edit Records of Previous Partition'
			goto ErrHndlr
		end
	End

	if @mode='A'
	Begin
		Select @row=count('x') From Inserted Where FmdPrtKey <> @wCurrPrtn 
		if @row> 0 
		begin
			select @errmsg= 'Cannot Insert Partition Key Other Than ''C'''
			goto ErrHndlr
		end
	end 

	If @Mode='D' 
	Begin 
		select @row= count('x') from deleted del where del.FmdPrtKey<>@wCurrPrtn
		if @row> 0 
		begin
			select @errmsg= 'Cannot Delete Records From Previous Partition'
			goto ErrHndlr
		end
	End
	/******* Sachin 3.02.0 [30/11/07] - Purge Partition (Speed Optimization) */
	
	If  (@ReplAgt<>1)
	Begin
		/******Cannot Insert/Update/Delete  if Crm database /Emr database with TrdCocd not in sdCoCd ****/
		/***if SysId=Emr Record not found then normal behaviour i.e can insert/update/delete****/
		if @mode in ('A','C')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From inserted where FmdPrtKey=@wCurrPrtn and 
		Exists (select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FmdCoCd +',%')) 
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Insert /Update ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('D')
		Begin 
		/* Current Partition */
		select @ROW =Count('x')  From Deleted where FmdPrtKey=@wCurrPrtn and 
		Exists ( select 'x' From SysDb where (SysId='EMR' and (SysDb='LTP' Or ','+sdCocd+',' Not  like '%,'+ FmdCoCd +',%'))
			or (SysId='CRM' and SysDb='WEB'))
		if @Row > 0		
			Begin 
				select @errmsg= 'Cannot Delete ' 
				goto ErrHndlr 
			end 
		End 

		if @mode in ('C')
		Begin 
			/* Current Partition */
			Select @Row= Count('x') from Deleted where FmdPrtKey=@wCurrPrtn and
			     	not exists(select 'x' from Bag where FmdPrtKey=BPrtKey and FmdCoCd= BCoCd
			     	and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
			     	and BLoc = 'PFG')
			If @Row> 0
			Begin
				Select @ErrMsg= 'Cannot Change As Bag Is Closed Or Bag Not In PFG'
				GoTo ErrHndlr
			End
		End
	
		if @mode= 'A'
		Begin
			/**** If @mode= 'A' then Valid Bag, BCls= 'N', BLoc= 'PFG' ****/
			/* Current Partition */
			select @Row= Count('x') from inserted
				where FmdPRtKEy=@wCurrPrtn and not exists(select 'x' from Bag where FmdPrtKey=BPrtKey and FmdCoCd= BCoCd
					and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
					and BLoc = 'PFG'
					and FmdFdYy = (Select max(FdYy) from Fgd where FdPRtKey=FmdPrtKey and FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo)
					and FmdFdKey = (Select max(FdKey) from Fgd where FdPrtKey=FmdPrtKey and FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo
						and FdYy = FmdFdYy))
			If @Row> 0
			begin
				Select @ErrMsg= 'Invalid Bag No/ Bag Closed/ Bag Not In FG'
				GoTo ErrHndlr
			end
		End
	
		/*** Update the current FgSubLoc(BFgSubLoc) of the bag based on the value
		FmdToFgSubLoc of the Fmd table record which is inserted ***/
		/* Current Partition */
		update Bag set
		BFgSubLoc= IsNull((select ins1.FmdToFgSubLoc from inserted ins1 where
			    	Ins1.FmdPrtKey=Ins.FmdPrtKey and ins1.FmdCoCd= ins.FmdCoCd and ins1.FmdBYy= ins.FmdBYy
				and ins1.FmdBChr= ins.FmdBChr and ins1.FmdBNo= ins.FmdBNo
				and ins1.FmdYy= (Select max(ins2.FmdYy) from inserted ins2
							where ins2.FmdPrtKey=ins1.FmdPrtKey and ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo)
				and ins1.FmdKey= (Select max(ins2.FmdKey) from inserted ins2
							where ins2.FmdPrtKey=ins1.FmdPrtKey and ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo
							and ins2.FmdYy= ins1.FmdYy)
				), '')
		From inserted ins where BPrtKey=ins.FmdPrtKey and BCoCd= ins.FmdCoCd and BYy= ins.FmdBYy
			and BChr= ins.FmdBChr and BNo= ins.FmdBNo
	
	
		if @mode in ('D') and @wTcTyp in ('FM')
		Begin
			/* Current Partition */
			select @Row= Count('x') from Deleted where FmdPrtKey=@wCurrPRtn and FmdBNo<> 0 and
				     not exists(select 'x' from Bag where FmdPrtKey=BPrtKey and FmdCoCd= BCoCd
				     and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
				     and BLoc= 'PFG')
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Delete As Bag Is Closed Or Bag Not In PFG'
				GoTo ErrHndlr
				end
	
			/* Current Partition */
			update Bag set
			BFgSubLoc= IsNull((select del1.FmdFrFgSubLoc from deleted del1 where
				    	del1.FmdPrtKey=del.FmdPrtKey and del1.FmdCoCd= del.FmdCoCd and del1.FmdBYy= del.FmdBYy
					and del1.FmdBChr= del.FmdBChr and del1.FmdBNo= del.FmdBNo
					and del1.FmdYy= (Select min(del2.FmdYy) from deleted del2
								where del2.FmdPrtKey=del1.FmdPrtKey and del2.FmdCoCd= del1.FmdCoCd
								and del2.FmdBYy= del1.FmdBYy
								and del2.FmdBChr= del1.FmdBChr
								and del2.FmdBNo= del1.FmdBNo)
					and del1.FmdKey= (Select min(del2.FmdKey) from deleted del2
								where del2.FmdPrtKey=del1.FmdPrtKey and del2.FmdCoCd= del1.FmdCoCd
								and del2.FmdBYy= del1.FmdBYy
								and del2.FmdBChr= del1.FmdBChr
								and del2.FmdBNo= del1.FmdBNo
								and del2.FmdYy= del1.FmdYy)
					), '')
			From deleted del where del.FmdPrtKey=@wCurrPrtn and BPrtKey=del.FmdPrtKey and BCoCd= del.FmdCoCd and BYy= del.FmdBYy
				and BChr= del.FmdBChr and BNo= del.FmdBNo
	
		End 

	End


	/******** Only One TcTyp records can be Inserted at a time.********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from inserted Join param On
		PTyp= 'TC' and PMCd= FmdTc and PSCd= '' Where FmdPRtKEy=@wCurrPrtn 
	If @Row> 1
	begin
		Select @ErrMsg= 'Transactions Of Only One TcType Can Be Acted On'
	  	GoTo ErrHndlr
	end

	/******** Only One TcTyp records can be Deleted at a time. *********/
	/* Current Partition */	
	select @Row= Count(distinct(PValue)) from deleted Join param on
		PTyp= 'TC' and PMcd= FmdTc and PSCd='' Where FmdPrtKey=@wCurrPrtn 
	If @Row> 1
	begin
		Select @ErrMsg= 'Transactions Of Only One TcType Can Be Acted On'
		GoTo ErrHndlr
	end

	if @mode in ('A', 'C')
	Begin
		/******* Valid FmdTc,FmdYy,FmdChr, FmdNo combination ********/
		/* Current Partition */
		Select @Row= Count('x') From Inserted Ins Where Ins.FmdPrtKey=@wCurrPrtn and
  			Not Exists (Select 'x' From Fm Where FmCoCd=Ins.FmdCoCd
				And FmTc= Ins.FmdTc And FmYy= Ins.FmdYy
				And FmChr= Ins.FmdChr And FmNo= Ins.FmdNo)
	  	If @Row> 0
 		begin
			Select @ErrMsg= 'Voucher No. Does Not Exist'
       			GoTo ErrHndlr
  		end

		/***** FdSr <> 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FmdPrtKey=@wCurrPrtn and FmdSr<= 0
		If @Row>0
		begin
	  		Select @ErrMsg= 'Sr. Cannot be 0'
		  	GoTo ErrHndlr
		end

		/***** FdKey > 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FmdPrtKEy=@wCurrPrtn and FmdKey<= 0
		If @Row>0
		begin
	  		Select @ErrMsg= 'Key Cannot be <= 0'
		  	GoTo ErrHndlr
		end

		/***** FdBNo > 0 *****/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where FmdPrtKEy=@wCurrPrtn and FmdBNo<= 0
		If @Row>0
		begin
	  		Select @ErrMsg= 'Bag No. Cannot be <= 0'
		  	GoTo ErrHndlr
		end

		/* Emr 211 (FmdCoCd, FmdYy, FmdKey Key comb shld be unique) */
		/* Current Partition */
		select @row= count('x') from inserted ins where ins.FmdPrtKey=@wCurrPrtn and
			(Select count('x') from Fmd Fd where Fd.FmdPrtKey=ins.FmdPrtKey and Fd.FmdCoCd= ins.FmdCoCd and Fd.FmdYy= ins.FmdYy and
				Fd.FmdKey= ins.FmdKey)> 1
	  	if @row> 0
  		begin
   			select @errmsg= 'FmdCoCd-FmdYy-FmdKey Key Combination Should Be Unique'
	   		goto ErrHndlr
  		end
	/* **** Zubin 211 **** */

		/* Flute Bags cannot be Moved in FG */
		/* *** Jay 2.13(CT) *** */
		/* Current Partition */
		select @Row= count('x') from Inserted where FmdPrtKey=@wCurrPrtn and
			Exists (Select 'x' from Param where PTyp= 'BCHR' and PMCd= FmdBChr and PSCd= '' and PValue<> 'P')
		If @Row> 0
	   	begin
			Select @ErrMsg= 'Only Primary Bags Can Be Moved To FG Sub-Location'
			GoTo ErrHndlr
		end
		/* **** Zubin 211 **** */

		/*** FmdToFgSubLoc  =  vPMCd('FGSUBLOC') ***/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.FmdPrtKey=@wCurrPrtn and
  			Not Exists (Select vPMCd From vParam Where vPCoCd= FmdCoCd and
					vPTyp= 'FGSUBLOC' And vPMCd = FmdToFgSubLoc)
	  	If @Row> 0
 		begin
			Select @ErrMsg= 'To Fg Sub Location Not Defined'
       			GoTo ErrHndlr
  		end

		/*** FmdFrFgSubLoc  =  FmdToFgSubLoc ***/
		/* Current Partition */
		Select @Row=Count('x') From Inserted Ins Where Ins.FmdPrtKey=@wCurrPrtn and Ins.FmdFrFgSubLoc = Ins.FmdToFgSubLoc
	  	If @Row> 0
 		begin
			Select @ErrMsg= 'To Fg Sub Location and From Fg Sub Loc cannot be same '
       			GoTo ErrHndlr
  		end
		If @Mode= 'C'
		BEGIN
			/******* If Mode = 'C' then Cannot change Key Values,Bag No ********/
			/* Current Partition */
			select @Row= Count('x') from Deleted Del where Del.FmdPrtKey=@wCurrPrtn and
				 Not Exists (Select 'x' from Inserted Ins where Ins.FmdPrtKey=Del.FmdPrtKey and Ins.FmdCoCd=Del.FmdCoCd
				 and Ins.FmdTc=Del.FmdTc and Ins.Fmdyy=Del.FmdYy and Ins.FmdChr= Del.FmdChr
				 and Ins.FmdNo=Del.FmdNo and Ins.FmdSr=Del.FmdSr and Ins.FmdBYy= Del.FmdBYy
				 and Ins.FmdBChr=Del.FmdBChr and Ins.FmdBNo=Del.FmdBNo and Ins.FmdFrFgSubLoc= Del.FmdFrFgSubLoc
				 and Ins.FmdKey= Del.FmdKey and Ins.FmdFdYy = Del.FmdFdYy and
				 Ins.FmdFdKey = Del.FmdFdKey)
			If @Row > 0
			Begin
				Select @ErrMsg= 'Cannot Change Voucher No./Bag No/Key'
				GoTo ErrHndlr
			End

			/******* Cannot Change If Fwb Transaction Has Taken Place For The Bag After The Movement ******/
			/* Current Partition */
			select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPrtn and
			     exists(Select 'x' from Fgd Fgd1 where Fgd1.FdPrtKey=del.FmdPrtKey and Fgd1.FdCoCd= del.FmdCoCd and
				     Fgd1.FdBYy= del.FmdBYy and Fgd1.FdBChr= del.FmdBChr and
				     Fgd1.FdBNo= del.FmdBNo and
				     ((Fgd1.FdYy > del.FmdFdYy)
					or
					(Fgd1.FdYy = del.FmdFdYy and Fgd1.FdKey> del.FmdFdKey))
				)
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Change As Not The Last FG Movement Of The Bag'
				GoTo ErrHndlr
			end

			/******* Cannot Change If this Fg Movement is not the last FG Movement For The Bag ******/
			/* Current Partition */
			select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPRtn and
				exists(Select 'x' from Fmd Fmd1 where Fmd1.FmdPrtKey=del.FmdPrtKey and Fmd1.FmdCoCd= del.FmdCoCd and
				Fmd1.FmdBYy= del.FmdBYy and Fmd1.FmdBChr= del.FmdBChr and
				Fmd1.FmdBNo= del.FmdBNo and
				(	(Fmd1.FmdYy> del.FmdYy)
					or
					(Fmd1.FmdYy= del.FmdYy and Fmd1.FmdKey> del.FmdKey)
				)	)
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Change As Not The Last Fg Movement Of The Bag'
				GoTo ErrHndlr
			end
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
		/*
			select @Row= Count('x') from Deleted where
			     	not exists(select 'x' from Bag where FmdCoCd= BCoCd
			     	and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
			     	and BLoc = 'PFG')
			If @Row> 0
			begin
				Select @ErrMsg= 'Cannot Change As Bag Is Closed Or Bag Not In PFG'
				GoTo ErrHndlr
			end
		*/
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
		END
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
/*		if @mode= 'A'
		Begin
*/			/**** If @mode= 'A' then Valid Bag, BCls= 'N', BLoc= 'PFG' ****/
/*			select @Row= Count('x') from inserted
				where not exists(select 'x' from Bag where FmdCoCd= BCoCd
					and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
					and BLoc = 'PFG'
					and FmdFdYy = (Select max(FdYy) from Fgd where FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo)
					and FmdFdKey = (Select max(FdKey) from Fgd where FdCoCd= FmdCoCd
						and FdBYy = FmdBYy and FdBChr = FmdBChr and FdBNo= FmdBNo
						and FdYy = FmdFdYy))
			If @Row> 0
			begin
				Select @ErrMsg= 'Invalid Bag No/ Bag Closed/ Bag Not In FG'
				GoTo ErrHndlr
			end
		End
*/
		/*** Update the current FgSubLoc(BFgSubLoc) of the bag based on the value
		FmdToFgSubLoc of the Fmd table record which is inserted ***/
/*		update Bag set
		BFgSubLoc= IsNull((select ins1.FmdToFgSubLoc from inserted ins1 where
			    	ins1.FmdCoCd= ins.FmdCoCd and ins1.FmdBYy= ins.FmdBYy
				and ins1.FmdBChr= ins.FmdBChr and ins1.FmdBNo= ins.FmdBNo
				and ins1.FmdYy= (Select max(ins2.FmdYy) from inserted ins2
							where ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo)
				and ins1.FmdKey= (Select max(ins2.FmdKey) from inserted ins2
							where ins2.FmdCoCd= ins1.FmdCoCd
							and ins2.FmdBYy= ins1.FmdBYy
							and ins2.FmdBChr= ins1.FmdBChr
							and ins2.FmdBNo= ins1.FmdBNo
							and ins2.FmdYy= ins1.FmdYy)
				), '')
		From inserted ins where BCoCd= ins.FmdCoCd and BYy= ins.FmdBYy
			and BChr= ins.FmdBChr and BNo= ins.FmdBNo
*/
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
	End
	/*** UPDATES ***/
	/*** Bag forward update, BFgSubLoc= FmdToFgSubLoc
	     If delete then Reverse FmdToFgLoc to max record in Fmd ****/
	if @mode in ('D') and @wTcTyp in ('FM')
	Begin
		/******* Cannot Delete If Fmd Transaction Has Taken Place For The Bag After
			 The Movement ******/
		/* Current Partition */
		select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPrtn and del.FmdBNo<> 0 and
			exists(Select 'x' from Fmd Fmd1 where Fmd1.FmdPrtKey=del.FmdPrtKey and Fmd1.FmdCoCd= del.FmdCoCd and
					Fmd1.FmdBYy= del.FmdBYy and Fmd1.FmdBChr= del.FmdBChr and
					Fmd1.FmdBNo= del.FmdBNo and
					(	(Fmd1.FmdYy> del.FmdYy)
						or
						(Fmd1.FmdYy= del.FmdYy and Fmd1.FmdKey> del.FmdKey)
					)
				)
		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Delete As Not The Last Fg Movement Of The Bag'
			GoTo ErrHndlr
		end

		/******* Cannot Delete If Fwb Transaction Has Taken Place For The Bag After
			 The Movement ******/
		/* Current Partition */
		select @Row= Count('x') from Deleted del where del.FmdPrtKey=@wCurrPrtn and del.FmdBNo<> 0 and
			     exists(Select 'x' from Fgd Fgd1 where Fgd1.FdPrtKey=del.FmdPrtKey and Fgd1.FdCoCd= del.FmdCoCd and
				     Fgd1.FdBYy= del.FmdBYy and Fgd1.FdBChr= del.FmdBChr and
				     Fgd1.FdBNo= del.FmdBNo and
				     (	(Fgd1.FdYy> del.FmdFdYy)
						or
					(Fgd1.FdYy= del.FmdFdYy and Fgd1.FdKey> del.FmdFdKey)
				     )
				)
		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Delete As Not The Last Transaction Of The Bag'
			GoTo ErrHndlr
		end

--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
/*		select @Row= Count('x') from Deleted where FmdBNo<> 0 and
			     not exists(select 'x' from Bag where FmdCoCd= BCoCd
			     and FmdBYy= BYy and FmdBChr= BChr and FmdBNo= BNo and BCls= 'N'
			     and BLoc= 'PFG')
		If @Row> 0
		begin
			Select @ErrMsg= 'Cannot Delete As Bag Is Closed Or Bag Not In PFG'
			GoTo ErrHndlr
			end
*/
/*		update Bag set
		BFgSubLoc= IsNull((select del1.FmdFrFgSubLoc from deleted del1 where
			    	del1.FmdCoCd= del.FmdCoCd and del1.FmdBYy= del.FmdBYy
				and del1.FmdBChr= del.FmdBChr and del1.FmdBNo= del.FmdBNo
				and del1.FmdYy= (Select min(del2.FmdYy) from deleted del2
							where del2.FmdCoCd= del1.FmdCoCd
							and del2.FmdBYy= del1.FmdBYy
							and del2.FmdBChr= del1.FmdBChr
							and del2.FmdBNo= del1.FmdBNo)
				and del1.FmdKey= (Select min(del2.FmdKey) from deleted del2
							where del2.FmdCoCd= del1.FmdCoCd
							and del2.FmdBYy= del1.FmdBYy
							and del2.FmdBChr= del1.FmdBChr
							and del2.FmdBNo= del1.FmdBNo
							and del2.FmdYy= del1.FmdYy)
				), '')
		From deleted del where BCoCd= del.FmdCoCd and BYy= del.FmdBYy
			and BChr= del.FmdBChr and BNo= del.FmdBNo
*/
--	######################################## Manoj - Shifted To _NR_INUPDL ########################################
	End
Return
ErrHndlr:
	BEGIN
		Select @ErrMsg='|'+@ErrMsg
		RaisError(@ErrMsg,16,1)
		Rollback Transaction
	END
END

GOGO
DELETE FROM TRGDISA
GOGO
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED



